/* 平成29年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h29.committeeSessions.push(...[{"id":"h29-20170314-3","meetingId":"h29-c-budget","date":"2017年3月14日","dateIso":"2017-03-14","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時０５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を161件整理しています。","topics":[{"id":"topic-01","title":"起立少数であります。ご着席願います。 よって、本動議は否決いたしました。 それでは、改めまして、第５号議案、平成２９年度品川区一般会計予算","agenda":"起立少数であります。ご着席願います。 よって、本動議は否決いたしました。 それでは、改めまして、第５号議案、平成２９年度品川区一般会計予算","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３５３ページ、３５７ページ、空き家改修についてお伺いをさせてほしいと求めました。この街路樹等維持管理費、剪定等ありますけれども、それと、かむろ坂の桜植替え工事費について、内容をお知らせほしいと求めました。","respondent":"多並道路課長","answer":"ここの平成２９年度に計上しています費用といたしましては、管理するための費用ということで、計上しています。その１段上のかむろ坂の桜につきましては、適正な時期に植え替えていきたいということで、計上させていただいた内容です。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"桜の見ごろのときの桜が、すごく見栄えがよくなくなってしまって、そういう基準というのがどうなっているのか教えてほしいと求めました。","respondent":"多並道路課長","answer":"桜の寿命等ですけれども、一般的に高木の寿命、全体的には８０年ぐらいと言われております。ひとつの楽しみでもありますので、その点、よく注意して剪定はしていきたいと思っているところです。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、３５５ページ、改修工事助成、および３５３ページ、住宅耐震化支援費についてお伺いいたします。予算書を見ますと、おそらくこれは耐震化支援費に入ると思うのですけれども、それを確認させてほしいと求めました。","respondent":"鈴木建築課長","answer":"予算書の３５３ページのほうには、件数は書いてございませんが、その３０万円をプラスした金額が記載されているというものです。東京都が平成２５年に調査をかけた中で、倒壊危険度が高いエリア、そこで重点的にやっていきたいというものです。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それぞれありがとうございました。施工に入ったときに、派遣アドバイザーの方も実地現場調査に来るのかどうか、お知らせほしいと求めました。","respondent":"鈴木建築課長","answer":"１回１時間から２時間程度、２ｍ以上を超える擁壁になりますので、必ず確認申請が必要になります。ほかの一級建築士が受けるのかによって違いますけれども、基本的には現場のほうは、しっかり資格を持った方が工事管理をなさるという話です。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、３５７ページ、空き家対策についてお伺いをさせてほしいと求めました。防草シート購入１０件ということなのですけれども、そういうことなのかどうなのか、お聞きしたいと思います。","respondent":"今井住宅課長","answer":"活用モデルという形で、こちらのほうは２件、目標ということで考えております。保全通知を差し上げている方の中から１０件程度はご希望があるというふうに考えておりまして、１０件達成する見込みというふうに考えております。","id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問","question":"区のほうで依頼を受けて、区のほうで、この当該空き家のところに防草のシートを敷くという認識でよろしいのか尋ねました。","respondent":"今井住宅課長","answer":"今般の防草シートの購入支援につきましては、防草シートの代金の２分の１程度になります限度額５,０００円で助成をするという形で考えております。シート代のみです。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"意見","question":"ぜひ、そういった地域の、近隣の方からの依頼がありましたら、ぜひよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問","question":"３２３ページ、３４３ページ、公園整備事業費について伺っていきたいと思います。駅周辺等ですが、区内のバイク、それから二輪の保有台数について、今日はわかりますか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"バイクの保有台数ですけれども、こちら、税務課のほうにちょっと確認いたしまして、原付につきましては１万４,７７６台、自動二輪につきましては８,１２２台が登録されているということで、確認いたしました。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問・要望","question":"確認させていただきました。ちょっと不勉強で教えていただきたいのですが、何らかの形で品川区まで入ってくるものかどうか、の説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"つる委員","kind":"確認","question":"これは確認します。原付しか止められない所と、自動二輪も止められる所の、その内訳がわかればの説明を求めました。","respondent":"桑波田交通安全担当課長","answer":"バイクの駐車場所のスペースについては先ほどのとおりなのですけれども、一応、施設の大きさによって、大きいバイク用の所もありますし、原付用のちょっと狭いスペースという所もありますので、ちょっと細かいところの数字、内訳までは把握していないところです。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問","question":"３９台余裕があるのですが、２９台の放置バイクがあったということで、それを全部入れたとしても１０台の余裕があるのですよね。放置バイクもしっかりと、せっかく整備している所に止めてもらえるような工夫をされたほうがいいかと思うのですが、これについての説明を求めました。","respondent":"桑波田交通安全担当課長","answer":"ホームページ等でも、そういったものがネット上でも見られるようになっておりますので、引き続きいろいろな場所があるということを周知していきたいと考えております。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"街路樹約４,０００本に対して、今現在、何本になったか教えてください。パーセンテージもの説明を求めました。","respondent":"多並道路課長","answer":"区内の街路樹については、現在３,９９９本、委員のご指摘のとおり、約４,０００本です。そのうち、桜が１,３１８本で、割合としましては、約３３％が桜で、ほかの区よりは非常に多い街路樹の割合だと、我々、認識しています。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"不健全木が１９本あって、それから工法、昨年の決算でも要望させていただいた根上がり対策ですね。これの説明を求めました。","respondent":"多並道路課長","answer":"空洞が５０％以上あるものが１９本あったということで、５０％以上倒木の危険性があるということで、その１９本を対象にしているものです。平成２９年度の予算で計上させていただいて、その１９本の、それがこの計上させていただいた費用です。","id":"exchange-013"},{"speaker":"つる委員","kind":"提案","question":"１９本ですから、全部ではないので、多分、植え替えた所は、どうしても少し空が見える。桜の木が植えられていくように、これも引き続き、要望も含めて、提案も含めて、言い続けていきたいなと思いますとの意見を述べました。","respondent":"溝口公園課長","answer":"正確には４カ所ですね、４カ所のトイレ改修について、予算を計上させていただいているものです。ほかにも旧東海道沿いのトイレ、また大井町の駅前のトイレ等ありますので、そういったものを改修していきたいというふうに考えているものです。","id":"exchange-014"},{"speaker":"つる委員","kind":"提案","question":"平成２７年度の決算のときに、提案をさせていただいていたので、非常に喜んでおります。ましてや、武蔵小山、大きい駅ですからとの意見を述べました。","respondent":"溝口公園課長","answer":"人的、予算的にも、計画的に進めていくという箇所でいくと、やはり５、６カ所。４カ所から６カ所ぐらい、やはりこのぐらいが、ちょうど計画的に進められる限界なのかなというふうに感じているものです。","id":"exchange-015"},{"speaker":"つる委員","kind":"提案","question":"提案もしていきたいと思いますし、いろいろなところから引っ張ってきて、促進されるようにしたいと思います。おもてなしトイレは、品川区どこから入ってもおもてなしトイレがある、そういう整備をぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"３５７ページ、マンション管理支援、また、３４７ページ、大崎駅周辺地区再開発事業、大崎西口駅前地区について伺います。それと、マンション建替え時の課題は何だと区は考えていらっしゃるのかも伺いたいと思います。","respondent":"今井住宅課長","answer":"ただ、今１件、建替えを行いたいというふうな具体的なご相談があります。まずは意識、またはその建替えに向かう集約ですとか、住民の合意が一番の課題になるかと思います。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"それで、この直面しているマンションというのは、区内にどれぐらいあるのか、区は把握してらっしゃるのか伺いたいと思います。実態調査が必要だと思うのですけれども、この実施も求めますけれども、いかがか尋ねました。","respondent":"今井住宅課長","answer":"旧耐震・耐震の部分で、旧耐震の割合が大体２５％程度、マンション全体の２５％程度のような報告が出てくる見込みです。実際にマンション管理セミナーということで実施いたしましたけれども、十分、長寿命化もできるというふうにも聞いております。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"伺いたいと思います。この先行モデル事業の成果とは何だったのか、伺います。","respondent":"今井住宅課長、稲田都市開発課長","answer":"先ほどの割合ですけれども、現在調査を行っておりますのは、東京都と連携して、分譲マンションのほうです。平成２７年度、平成２８年度と、その辺を検討してまいりました。容積率、それから都市づくりの中での補助金制度、また税制制度等の関係等を提案したです。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"超高層マンションのほうが困難があるのではないかということについて、もう一度、区の認識を伺いたいと思います。それと、計画はどのような計画なのか、わかればの説明を求めました。","respondent":"今井住宅課長、稲田都市開発課長","answer":"いかに普段の管理規約、もしくは通常の日常管理の中で、大規模修繕などの計画を練っていくかにかかっていると思います。この地区で、借家人等はちょっと今のところ把握できないのですが、建物数から言えば、このエリアの中で１３棟あるところです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"提案","question":"この方の土地は、耐震化したばかりのビルですから、この終末期の問題も既にクリアしているわけなのですけれども、納得いかないと。この場所で事業を続けたいという希望は当然のことだと思いますけれども、品川区はそういうふうに思わないのでしょうか、伺いたいと思いますとの意見を述べました。","respondent":"稲田都市開発課長","answer":"この大崎駅の西口地区、この地区に関しましても、平成２４年から地元の方と意見交換会等しておりまして、今後また合意形成等に向けて進めていくと思われます。","id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"３２５ページの補助１６３号線整備について伺います。どのように、もしかしたら、区役所前でありますから、区役所に影響が出てくるのか、そのことについて伺いたいと思います。","respondent":"多並道路課長","answer":"その後に、下の街路の整備を行うのが１年間、平成３２年度ということで、現在、平成３２年度に完了させる予定で、工事を進めているものです。一緒に検討しながら、今後の補助１６３号線整備のあり方についてということを、検討していこうという経費が入っているものです。","id":"exchange-022"},{"speaker":"松永委員","kind":"提案","question":"ちょっと提案なのですけれども、タクシーの乗降者スペースをぜひつくっていただきたいと思うのですけれども、そのことについて伺います。ぜひそうしたサインを、矢印の方向というのをつけていただきたいと思うのですけれども、そのことについても合わせて伺いたいと思いますとの意見を述べました。","respondent":"多並道路課長","answer":"１つ今回の事業の中であるのが、どうやって入れるかどうかというのを、工夫しないといけないかなと考えているところです。ちょうど我々の補助１６３号線でやっている工事から続いて、その掲示をできないかとか、協議をしていきたいと思っているところです。","id":"exchange-023"},{"speaker":"松永委員","kind":"質問・要望","question":"新しい壁画を、また同じ学校の生徒さんに描いていただきたいとは思うのですけれども、そのことについてどのように考えていらっしゃるのでしょうか。それとも、また残していくのか、その辺、お伺いしたいと思います。","respondent":"多並道路課長","answer":"補助１６３号線は新たな事業区間ということで、事業を、どのような整備を進めるかという協議を進めていくところです。やはり地域の方のご意見をお伺いして、よりよい形でということで、進めていきたいと思っているところです。","id":"exchange-024"},{"speaker":"松永委員","kind":"提案","question":"提案ですけれども、この場所はこのように変わりますというような立て看板をつけながら、少しずつ対策をとってみてはいかがでしょうか。もちろんトラック以外にもいろいろな車が止まっておりますので、その辺の対策について伺いたいと思いますとの意見を述べました。","respondent":"多並道路課長","answer":"大田区とも続くので大田区、警視庁とも協議しているところですけれども、自転車レーンを整備する予定となっています。今後も協議しながら、詳細については詰めていきたいと思っているところです。","id":"exchange-025"},{"speaker":"松永委員","kind":"提案","question":"そこで、３１９ページのシェアサイクル事業について伺います。平成２９年度予算書では、公園等整備費に５００万円となっておりますが、場所はある程度決まっているのか尋ねました。","respondent":"多並道路課長、安井土木管理課長","answer":"平成２９年度につきましては、あとは桜新道の塗り替えと、やっていきたいと考えています。は地元ともよく協議しながら、今後進めていくということで、引き続き協議を進めているところです。まず間違いなく、区の重要な観光スポットですので、こちらのほうはつくるということで予定はしておりますけれども。","id":"exchange-026"},{"speaker":"松永委員","kind":"質問","question":"次に、３４１ページのしながわ水族館運営費について、関連して３４３ページのしながわ区民公園改修工事について伺います。そのことについて伺います。","respondent":"溝口公園課長","answer":"委員お話しの所は、レストラン横の階段になっている部分だと思います。勝島の海に触れ合える、そういったゾーンの設定をして、階段状になっているものです。","id":"exchange-027"},{"speaker":"松永委員","kind":"提案","question":"勝島の海ということで、ぜひその海を活用してみてはいかがかということで、ちょっと提案させてほしいと求めました。昔あの場所でボートをやられていたということをお伺いしたのですけれども、なぜボートを取りやめてしまったのか、その辺も伺いたいと思いますとの意見を述べました。","respondent":"溝口公園課長","answer":"そういうコンセプトのもとにつくってきて、皆さんに親しまれてきている公園だというふうに認識しています。本来であれば活用という形でいろいろ考えていきたいところではありますが、そういったところで一旦は中止という形でさせていただいたのが現状です。","id":"exchange-028"},{"speaker":"松永委員","kind":"意見","question":"全国水族館ランキング、じゃらんnetというところでちょっと調べさせていただいたのですが、しながわ水族館は３２位と健闘しております。ぜひ水族館以外にも、そうしたアトラクションを１つ増やしてみてはいかがかと思うのですが、最後に改めて区の意見の説明を求めました。","respondent":"溝口公園課長","answer":"平成２９年度予算の中でも、勝島のレストランをどう活用していくのか、そういったところの検討費用も計上させていただいているところです。詳細設計に入っていく予定になっておりますので、公園になるように、検討していきたいというふうに考えているものです。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"３３７ページ、３４２ページ、公園新設改良費についてお伺いをいたします。航路とか、ポイント、拠点、そして来訪者人数など、そういったことをお知らせください。","respondent":"和田河川下水道課長","answer":"舟運社会実験継続中でございまして、今後検討していくわけですが、定期航路にとまっていただく。それから、東品川二丁目防災桟橋をハブの桟橋として、区内の舟運の活性化が図れればというような構想を考えているところです。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"どのくらいの来訪者人数というのは、まだ予想はできないか尋ねました。","respondent":"和田河川下水道課長","answer":"２８日間の運行の中で、２１７便、概算で１,３００人ほど乗っていただいたという計算があります。どのような乗降客数ですかね、そのようなものが考えられるかということを、検討していきたいと考えています。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうした事業にしていっていただきたいと考えておりますけれども、同時に、また船から見える景観づくりというのは非常に重要になってくると思います。この２つの事業があると思われるのですけれども、この２つの事業は一体どういうものなのかをお知らせください。","respondent":"中村都市計画課長、和田河川下水道課長","answer":"そしてこれから、基準の策定の１つの基礎の調査にしようというところで、今回計上しているものです。水辺の賑わい構想検討委託ですけれども、今、現在ある水辺からの景観をどうやって守っていくかという視点で検討するものです。この辺を生かして、どのように賑わいを創出していくかという視点で検討するのが、賑わい構想の検討委託です。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ、前向きなそうした検討を重ねていって、人が多く来る賑わいづくりというのを、ぜひともやっていただきたいと考えております。これを１つのきっかけとして、天王洲エリアのかつての輝きを取り戻すべく、区のお考えはどのようになっているか尋ねました。","respondent":"和田河川下水道課長","answer":"対岸には、我々の品川天王洲桟橋もあります。今後は、東品川二丁目防災桟橋も含めまして、天王洲全体で水辺の活性化ということでご利用いただければというふうに考えてあります。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"次は、公園についてお伺いいたしますけれども、しながわ中央公園拡張部に、前回、建設委員会で視察に参りました。今後ともそうした方向でやっていっていただきたいのですけれども、今後、品川区としても公園新設改良時にそのようにしていくのかをお知らせください。","respondent":"溝口公園課長","answer":"管理事務所を新たに設置しておりますので、そういった中での防災備蓄倉庫を整備したり、そういったところでの整備というのは行っていきます。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひとも整備を進めていっていただきたいと考えております。これは同様に、今後の公園や改良時に進めていくべきだと私は考えているのですけれども、品川区としてはどのようにお考えか尋ねました。","respondent":"溝口公園課長","answer":"そこの公園・児童遊園を使って、災害時にどのように活動するのか、そういった中の一環として出てきているものです。地域から、かまどベンチの設置のお話が、そういったものはしっかりと整備をしていきたいというふうに考えてあります。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問・要望","question":"地域の方から、いざとなったらコンロとなる防災スツール、かまどベンチは、非常にいいので、ぜひ進めていってほしいというお声も頂戴しております。","respondent":"溝口公園課長","answer":"今現在、防災広場の整備につきましては、木造密集地域の解消ということを目的に整備を進めているところです。そういったところの中で土地を購入し、広場として整備をしているといった事業ですので、ご理解いただきたいと思います。","id":"exchange-036"},{"speaker":"筒井委員","kind":"質問","question":"よくわかりました。東側は、木造密集地域が少ないので、やらないということでよろしいのか尋ねました。","respondent":"溝口公園課長","answer":"かまどベンチですとか、そういったものの設置のお話があれば、それはしっかり受けた形で整備を進めてきている。これまでも、これからも、しっかりとそういったご意見を聞きながら整備を進めていきたいというふうに考えているものです。","id":"exchange-037"},{"speaker":"筒井委員","kind":"質問・要望","question":"しっかりと地域の声を拾っていただいて、必要なところはしっかりと整備をしていっていただきたいと考えております。この災害用設備を活用した訓練もやっていただきたいのですけれども、その点、区としてのお考えはいかがか尋ねました。","respondent":"溝口公園課長","answer":"私ども行政側がつくっただけでおしまいというわけではありませんので、その先、そういったところも１つ大切だと考えています。必要なところ、また、整備できるところはしっかり整備をしていきたいというふうに考えているものです。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問","question":"そして、ちょっと時間がありますので、３４１ページの八潮地区まちづくり検討経費について、お伺いをしたいと思います。そうした商業施設誘致などの仕掛けが必要だと考えていますけれども、その点、区としてはいかがお考えか尋ねました。","respondent":"中村都市計画課長","answer":"こういったものも課題の１つとしては捉えておりますけれども、入居開始してから約３４年ということで、将来のことについて考えていきたいと考えています。","id":"exchange-039"},{"speaker":"横山委員","kind":"質問・要望","question":"１点目に、下水道管改修事業、河川管理費についてお伺いいたします。平成２８年１１月７日から、小山五丁目、六丁目、荏原五丁目の工事がスタートしておりますが、スケジュールを確認させてほしいと求めました。","respondent":"和田河川下水道課長","answer":"ご指摘の、立会道路の改修工事ですが、これは東京都下水道局の工事です。平成２９年１１月完了予定で工事を進めていたところなのですけれども、平成３０年５月中旬まで工事を延長する予定だというふうに聞いております。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"こちら、地域への事前の説明の徹底と、立会川幹線の再構築を着実に進めていただくことを都に要望していただきたいと考えております。報告義務の有無にかかわらず、区側もアンテナを張っていただいて、区民の安心・安全への取組みを強く要望いたします。","respondent":"和田河川下水道課長","answer":"幹線の再構築の、いろいろな幹線が東京都内にあるわけなのですけれども、優先的にこの立会川幹線を事業化して取り組んでいるところです。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問・要望","question":"ちょっと専門用語も多いもので、詳しく、わかりやすく教えていただきたい部分があります。工事工法の概要について、わかりやすく、簡単で構いませんので、お願いします。","respondent":"和田河川下水道課長","answer":"今、下水道管は耐用年数が８０年程度で考えているですので、８０年サイクルで更新をしていかざるを得ないというようなことを記述されたものです。既存の下水道管の間に空隙ができるものですから、その空隙にモルタルを充填して固めて、全体として強度を強化するという工事です。","id":"exchange-042"},{"speaker":"横山委員","kind":"質問・要望","question":"次の質問、２点目なのですけれども、荏原南公園、子ども達のアイデアを活かした公園について、お伺いいたします。特に、以下の８つのポイントについて、詳細設計の内容を確認させてください。","respondent":"溝口公園課長","answer":"それぞれに、これまでと同様、子どもたちのアイデアを入れた遊具を設置していきたいというふうに考えてあります。今後も引き続き、事故等のない施工に心がけて、まちづくりを進めていきたいというふうに考えているものです。","id":"exchange-043"},{"speaker":"あくつ委員","kind":"質問・要望","question":"時間があれば、３４７ページの大崎駅周辺地区の再開発で、大崎エリアマネジメントについて伺いたいと思います。は地域住民からの要望があれば、交通管理者である警察に働きかけをしていただけるのかどうか、この辺についてお伺いします。","respondent":"桑波田交通安全担当課長","answer":"ゾーン３０につきましては、交通安全の対策の１つということで、推し進めているところです。今後も区民のほうに、地元の場所を知っていただいて、安全活動に役立てていきたいと考えております。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問","question":"どういう優先順位でこの４３カ所、３分の１のマックスのですから、１,５００万円以上の工事。これは多分１,５００万円では到底無理のような工事の感じがするのですけれども、これは働きかけを行っていくのか、それについて伺いたいと思います。","respondent":"鈴木建築課長","answer":"一定、東京都が５ｍ以上、傾斜が３０度以上でかけておりますが、大きいものから小さいものまで、さまざまです。こういったものを４３カ所のうちから抜き出して、アドバイザー派遣等を使って、働きかけをして、助成につなげていきたいというものです。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私、個人的にそういうの大好きなものですから。レディーメードのものがあるのか、それともこれはオーダーメードの１点ものなのか、それについての説明を求めました。","respondent":"溝口公園課長","answer":"ある１つのそういった造形の遊具等をつくるメーカーがありますので、関連する会社を含めてお願いして、ずっとつくってきているというのが共通点だというふうに認識しているところではあります。","id":"exchange-046"},{"speaker":"あくつ委員","kind":"質問・要望","question":"シティプロモーションの１つとして広報していく、こういう手法もあるのではないかと思うのですが、いかがでしょうかというところです。ですから、この不思議な造形美を、ぜひシティプロモーションとして活用していただきたいと思うのですが、いかがか尋ねました。","respondent":"中島企画部副参事","answer":"ポスターでも、その公園の恐竜のほうを使わせていただいたところ、これは何とか、これはどことか、いろいろ反響がありました。区民が品川区にさらに誇りと愛着を持てるように、今後のシティプロモーション活動の中で、さらに活用できるか検討させていただきたいと思います。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１点だけ要望です。非常にちょっと心苦しいところがあるのですが、これはぜひ対応はしてほしいと求めましたが、いかがでしょうかというところ。","respondent":"溝口公園課長","answer":"今後も、地域の方、またはご利用者の方の声を聞きながら、ベンチの設置、そういったものは考えていきたいというふうに考えているものです。１２７カ所、そのうち、洋式のトイレが１カ所でもあるものが３８カ所になってあります。","id":"exchange-048"},{"speaker":"吉田委員","kind":"確認","question":"３５８ページ、３目区民住宅費、伺いたいと思います。検討する必要があると考えるのですけれども、その辺はどうなっていますか尋ねました。","respondent":"多並道路課長","answer":"品川区の場合は非常に歩道も狭い中でもありますので、基本的には車道の横を走るのを基本とするというのが、考え方の１つです。国全体で同じような、今後は進めていこうというのが示されて、区としてもそうやっていきたいというものです。","id":"exchange-049"},{"speaker":"吉田委員","kind":"質問・要望","question":"それまでに、他区との連携も図られているように伺いましたので、それまでにきちんと整備されるように要望したいと思います。損害賠償の分も含めて入っていくということでいいでしょうか、確認させてください。","respondent":"多並道路課長、安井土木管理課長","answer":"平成２８年７月に示されたところでありますので、今後は品川区でも、その国の基準にのっとってやっていきたいと。今後もこのような形で、警視庁ともよく協議しながら進めていきたいという内容です。利用者のを別にかけるということではなくて、自転車そのもの、それぞれにかけていくというような形になろうかと思います。","id":"exchange-050"},{"speaker":"吉田委員","kind":"質問","question":"さっき、伺うのを忘れました。一律でも、品川区の場合、それは無理だよねという、そういう道もあるように思うのですけれども、その辺どうなのか、もう１回お答えいただけますか。","respondent":"多並道路課長","answer":"１.５ｍとか、警視庁と連携して、そこの場所を通るのですよという。幅が０.５ｍもしくは０.６ｍとか、あくまでも、こちら側をこの方向に進むというのを標示で示していくというのが内容です。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問","question":"３５７ページの住宅総務費で、東日本大震災支援費の被災者受入住宅費と、東日本大震災支援費の中で住宅原状回復費ですね。それから合わせて、現段階で、東北から避難してきて品川区に住んでらっしゃる方の状況の説明を求めました。","respondent":"今井住宅課長、寺嶋木密整備推進課長、久保田総務課長","answer":"３５７ページ、東日本大震災支援費と、３５９ページの同じく支援費です。木密整備推進課で実施しています密集事業の中で従前居住者用住宅というものがございまして、３３９ページの下から６行目になります。状況としては以上です。把握しているものにつきましては、合計で３６世帯８３人、これが２月の時点での数字です。","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問","question":"東京都は、該当者にヒアリングをしているのですが、品川区はこの状況を把握していらっしゃるのか、教えてください。この住宅支援費の打ち切り後、どうするのか決まっていない避難者が７割以上に上るということなのですが、品川区ではいかがか尋ねました。","respondent":"今井住宅課長","answer":"平成２９年３月末までに、それ以外の対象の方が、品川区内５世帯いらっしゃるというふうな認識です。今申し上げました５世帯につきましては、転居または福島県にお戻りになることを含めまして、全て４月以降のお住まいの先は確保されている状況です。","id":"exchange-053"},{"speaker":"吉田委員","kind":"質問","question":"避難者の方がいらっしゃるということなわけで、そういう方たちの状況というのは、把握していらっしゃるのでしょうか。不安定な立場の人が相談したいと考えたときに、品川区にはそれを受け止める窓口はあるのか、伺いたいと思います。","respondent":"久保田総務課長","answer":"２カ月に１回程度、２カ月に１回ですけれども、郵便でお知らせをしているです。ただ、住民票等を移されて区民等である方は、通常の区民の方と同じように、いろいろなご相談には応じているです。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問・要望","question":"納付促進の費用が大変急増していて、どういう趣旨の急増かなということで伺いたいと思います。しごと応援センターですか、その機能をぜひ活用してほしいな、。","respondent":"今井住宅課長","answer":"１カ月、故意ではなくて遅れている場合もありますので丁寧に対応しているとともに、何とか回収できないかということで検討してまいりました。生活困窮者の自立支援相談窓口等ありますので、関係各課と連携しながら、相談等に対応していきたいと考えています。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問・要望","question":"私は、暮らし・しごと応援センターで、家計相談、設置する必要がないのに始めたということを大変評価しております。その機能をぜひ有効に生かしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"南委員","kind":"質問・要望","question":"３３１ページ、その後に八潮地区まちづくり検討経費、立会川・勝島地区まちづくりビジョン策定費について伺います。これからはどういうふうに進めていくのか、一連の作業工程、プロセスについて伺いたいと思います。","respondent":"和田河川下水道課長","answer":"マンホールトイレ設置公園の下水道の耐震化を進めておりますが、この災害復旧拠点等の耐震化も、平成２９年度に完了の見込みです。これにつきましては非常に時間がかかるということで、現在のところ、いつまでという目標を立てていない状況です。","id":"exchange-057"},{"speaker":"南委員","kind":"質問・要望","question":"誰でも共通する思いですから、そういう計画は持っているというふうに聞いておりますけれども、そのあたりはどういうふうな状況になっているのか。これからどういうふうにしていこうか、いつまでにやっていこうかという、そこのところの内容の説明を求めました。","respondent":"和田河川下水道課長","answer":"東京都も考えているところですが、一般の住宅、一般のエリアへの展開に移っていくというふうに考えてあります。","id":"exchange-058"},{"speaker":"南委員","kind":"質問・要望","question":"八潮の住民、関係者が入っていける、そういう設定にしていただきたいというのが１つあります。それから、集約建替余剰地活用というのは具体的にどういうことなのか、ちょっと教えてほしいと求めました。","respondent":"中村都市計画課長","answer":"既存６９棟、１つはリフォームですとか、こういった様々なケースに応じて検討していく必要があると考えております。こういったところで、今後検討していく内容の１つの可能性として、掲げております。","id":"exchange-059"},{"speaker":"南委員","kind":"質問・要望","question":"その中で集約をしていくと、そこは厳格にとっていただいて、進めていただきたいということを、ちょっと要望したいと思います。そこも握って離さないでいただきたいと考えていますけれども、改めて区の見解をお願いします。","respondent":"中村都市計画課長","answer":"そういったところが課題というふうに認識をしております。ただ、具体的な内容につきましては、やはりこちらも地域の皆様のご意見も伺いながら進めていかなければいけないというふうに考えてあります。","id":"exchange-060"},{"speaker":"沢田委員","kind":"意見","question":"２０２０年までということでしたけれども、買った場所がどうなっているのかなというところで、そういう土地がこれから増えていくのかとの意見を述べました。","respondent":"中村都市計画課長","answer":"もうその１年から２年前には工事に着工しなければいけないというところを考えますと、かなり短い期間ということになると思います。この管理の方法も、ある程度まとまった時点で、道路の工事に着手するという、そういった可能性もあるというふうには聞いてあります。","id":"exchange-061"},{"speaker":"沢田委員","kind":"質問・要望","question":"地域の人ともそういったことを検討していってほしいと求めました。今どういう状況、そういうことがあるのかどうか、実際の状況についての説明を求めました。","respondent":"溝口公園課長","answer":"実際、公園内での、ここ最近ですけれども、犯罪が起こっているという話は聞いておりません。公園内で何か犯罪が起きて、防犯カメラが必要となったというようなケースは、ここ近年ではございません。","id":"exchange-062"},{"speaker":"沢田委員","kind":"質問・要望","question":"今の防犯カメラはずっと見ているわけではないですから、ぜひ、こういった防犯カメラの設置というのは増やしていただきたいなと思います。その分の予算というのは、そういった課題と言うか、公園に防犯カメラを設置することに対する課題というようなところは何かありますか。","respondent":"溝口公園課長","answer":"すぐ、即日に警備員が対応できるような対応をとっております。そうしたところをして、より安全にご利用いただけるような公園づくりというのを目指していきたいというふうに考えているところです。","id":"exchange-063"},{"speaker":"沢田委員","kind":"質問・要望","question":"ぜひ、安心・安全に、公園もですけれども、地域もそうですけれども、しっかりとできるように、整備をしていってほしいと求めました。巡回の警備にかかるお金とか、そういったことも予算を考えて、ぜひ整備していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"いながわ委員","kind":"質問・要望","question":"今後、それからもっと北側と言うのですか、水族館側の整備をお考えであるかどうか。ここの３５３ページに書いてある除却工事助成の木造一戸建て２００棟、アパート５０棟というのは、いかがお考えですかということ。","respondent":"溝口公園課長、鈴木建築課長","answer":"休めたり、そういったものができるのか、そういったところについては十分検討していきたいというふうに考えているものです。午前中もご説明しましたように、あるいは実施状況のホームページでの公表などを謳う基本的な内容になっておりまして、職員のほうが検討して。","id":"exchange-065"},{"speaker":"いながわ委員","kind":"質問・要望","question":"それで耐震に関しては、ちょっと木密の今回のと絡めると、耐震の、今回、今、質問したものに関しては、助成額が増額をされる。やはり相乗効果で実績は上がっていくと思いますので、エリアの拡大ということを今後考えてほしいと求めましたが、いかがでしょう。","respondent":"鈴木建築課長","answer":"設計、耐震工事、これらで周知に努めてまいりたいというふうに考えてあります。","id":"exchange-066"},{"speaker":"塚本委員","kind":"確認","question":"この３２８ｋｍ、いわゆる一般的に区道というものが、ほぼ全て対象となるということでいいのかという確認が１つです。この２つ、まず２点お伺いをさせてください。","respondent":"多並道路課長","answer":"現在の点検というか、巡回を先ほどお話ししましたが、３地区に分けながら、今の巡回の点検というのを、人の目で行っているところです。月１回は必ず巡回をしまして、頻度の高いところは週２回行っているところで、このような頻度で行っていくというものです。","id":"exchange-067"},{"speaker":"塚本委員","kind":"質問","question":"このようなことで説明されておりますけれども、どの程度、でこぼこを検知するようなシステムなのか。そうではない場合も含めて、どの程度のものを検知するものなのか、の説明を求めました。","respondent":"多並道路課長","answer":"今後注意したほうがいいだろうというのを、実際に通ってみて、それを実際に拾えるような形ですね。設定しながらやっていきたいというのが、どちらかと言うと、そういう形のものがやっていきたいという内容です。","id":"exchange-068"},{"speaker":"塚本委員","kind":"意見","question":"多分、耐久年度とか、そういうのでやっているのではないかと思いますが。そういう定期的な全面舗装みたいなことの計画にも生かしていけるのではないかと思うのですが、そういうお考えがあるかどうか、の説明を求めました。","respondent":"多並道路課長","answer":"そこの柏市が、今のような長期的な、もしくは改修計画の１つの目安にしていると聞いているところです。いわゆる改修時期も、数値化を１つの目安にしながらやっているところも、そのような考えで進めていきたいと思っているところです。","id":"exchange-069"},{"speaker":"塚本委員","kind":"質問・要望","question":"国が、こういった義務付けをして助成をしていこうというふうに定めた狙いというか、理由ですね、これをまず１つ伺いたいと思います。","respondent":"鈴木建築課長","answer":"倒壊危険度５の地区は、品川区内はございません。次に高い４地区が、この１１地区ですので、そこで重点的にやっていくというものです。","id":"exchange-070"},{"speaker":"塚本委員","kind":"質問","question":"人が歩いて建物を見てとかなのか、何か違うデータ等があってなのかというところを、ちょっとお伺いしたいというのが１つと。やってほしいようなところには何度も訪問するような、戸別訪問について、どれくらいの戸別訪問ができるのかというところの説明を求めました。","respondent":"鈴木建築課長","answer":"１軒１軒まずチャイムを押して訪ねて、そういったところを説明しながら、簡単なアンケートもその場でとりたいというふうに考えてあります。地区内の耐震化に対する考え的なところを最後取りまとめて、重点的に回るところも、その後考えていきたいです。","id":"exchange-071"},{"speaker":"塚本委員","kind":"提案","question":"これは提案なのですが、ぜひこの感震ブレーカーの普及と啓発と一緒にやっていただけると、大変に効果的なのではないかなと。地域的には、おそらくこの１１地区、かぶっていると思いますので、その点もいかがでしょうかということで、お伺いいたしますとの意見を述べました。","respondent":"鈴木建築課長","answer":"戸別訪問の委託先ですが、今現在、プロポーザルで事業者を選定する方向で、調整というか、準備を進めているところです。そういったところも、不安を解消しながら、しっかりＰＲを進めていきたいと思います。","id":"exchange-072"},{"speaker":"塚本委員","kind":"質問・要望","question":"ちょっと最後に時間があるので、１つだけお聞かせください。３３９ページ、何かあれば、一言だけお聞かせほしいと求めました。","respondent":"中村都市計画課長","answer":"荏原町、来年度を予定しております。それ以降は、今、東急大井町線の中で下神明ですとか旗の台、そういったところも働きかけていきたいと考えております。","id":"exchange-073"},{"speaker":"西本委員","kind":"質問","question":"やはり大きな突破口になるのではないかなというふうに思いますので、そういう考え方ではいかがでしょうかということについてのご見解をお聞きします。","respondent":"溝口公園課長、桑波田交通安全担当課長、中村都市計画課長、今井住宅課長","answer":"私のほうからは、大森駅水神口の地下機械式駐輪場の工事をやっている関係で、入庫ブースのスケルトンの関係についてお答えします。近い方は、なるべく自転車のご利用は控えてくださいということで、これまでも訴えてきたところです。いや１０年、２０年、こういったスパンの中で考えていく必要があると考えております。最後に、ファミーユ西五反田東館、総戸数４００戸ですが、平成３１年の３月となっております。","id":"exchange-074"},{"speaker":"西本委員","kind":"質問・要望","question":"区民住宅のほうですけれども、これはどうするのですかね。それをどのように考えていくのか尋ねました。","respondent":"桑波田交通安全担当課長、中村都市計画課長、今井住宅課長","answer":"大森駅周辺の駐輪場の整備状況ですけれども、大田区のほうについても、また新しくつくるというような状況は今のところ把握しているところではございません。専門家を入れて、そういった意見も聞きながら、取り込みながら進めていきたいと考えております。フラット型家賃の１５年間終了に伴います対策についてですけれども、入居時、そして毎年の助成額の決定のときに通知を差し上げているところです。","id":"exchange-075"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それと、今出ていたので、３４１ページ、八潮地区のまちづくり、この辺をもう一度伺います。委託ですから、こんなところが留意点であるよと、今までのご答弁以外であれば教えてほしいと求めました。","respondent":"中村都市計画課長、和田河川下水道課長","answer":"そういったところまで、さらに深く掘り下げる形で、皆様の意見をお伺いしながら進めてまいりたいと考えております。水辺の賑わい創出構想検討委託についてです。品川区内のいろいろな水辺のそれぞれの性格によって、どんな賑やかしができるかどうかということを、現状を踏まえて検討していきたいと考えています。","id":"exchange-076"},{"speaker":"渡辺委員","kind":"質問・要望","question":"この辺は、地域要望も多いと聞いていますので、拠点づくりの、今の内訳も含めた要望が結構あると思いますが、ぜひ検討いただきたいのが１つ。この辺も具体的に、区がリーダーシップをとって研究される必要性も含めて、お考えを伺えればと思います。","respondent":"中村都市計画課長、和田河川下水道課長","answer":"他地区でもこういった団地の中で建替えを達成するまでに、２０年ほど検討に要したというところもあります。これも、地域の皆様のご意見も伺いながらというところになるかと思いますけれども、そのような進め方で考えております。艇庫等の設置ですけれども、水辺の拠点としてどこがふさわしいのか、検討してまいりたいと考えています。様々な方法で、水辺の景観をどのように向上していくかというものを、委託の中で考えていきたいと考えております。","id":"exchange-077"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そして、という、何となくストーリーがある中で、計画と実施の、もう一度、スケジュール観と言うのですかね、この構想の検討の後どう生かしていくか。大変強い要望があって、会議体が招集されて、この４月にということで。","respondent":"和田河川下水道課長","answer":"先ほど申しましたように、２１７の運行をしたわけなのですけれども、しながわ水族館とか大井競馬場のご利用の提案がありませんでした。今度の４月１日と２日に、警視庁それから海上保安庁のご協力もいただきながら、河口部でマナーの啓発活動を行うというものです。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問","question":"それに関わって、補助２９号線道路計画についても伺います。駅の北側と南側、それぞれ伺います。","respondent":"東野まちづくり立体化担当課長","answer":"こちら、五丁目１９番地区というところになります。駅の北側におきましては、ただいま、五丁目１０番地区におきまして、再開発等の勉強会等が行われているということで伺っております。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問","question":"その北側の五丁目１０番のところは勉強会ということですけれども、具体的な高さですとか、階数とか、用途というのは、わかりますか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"五丁目１０番地区につきましては、まだ勉強会です。具体的な高さ等につきましては、今後、地権者の中で詰めていくような形になります。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問","question":"手続きなど、スケジュールも合わせて、それぞれ伺います。そして、北側のところの勉強会は、どんなことを検討しているのかも伺います。","respondent":"東野まちづくり立体化担当課長","answer":"勉強会等が行われているところにつきましては、そちらの情報を注視しながら、区としての支援を今後考えていきたいというふうに考えております。現在、こちらについてもまちづくりの勉強会を立ち上げているところですので、その辺の情報についても収集しています。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問","question":"どういう検討をして、勉強会でやっているかというのもお聞きしたので、わかる範囲でそれをご答弁ほしいと求めました。過年度の検討成果もお聞きしましたので、伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"それから過年度の検討成果ですけれども、特定整備路線沿道まちづくり推進費という中で、この地区についても考えられてきたところです。具体的に言いますと、こちらが過年度の検討の成果だと考えていますので、それらをもとにまちづくりを進めてまいりたいと思います。","id":"exchange-082"},{"speaker":"のだて委員","kind":"質問","question":"具体的に、戸越五丁目１９番の再開発についても伺いたいと思います。直近で事業化が予想されているということで、組合の認可や建物の解体・着工、完成などのスケジュールを伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"平成２９年度都市計画決定を予定するということになりますと、それから組合の認可につきましても、同じ平成３０年度が予定されます。建物の竣工につきましては、平成３３年度から、遅くとも平成３４年度ぐらいにはなってくるのかと思います。","id":"exchange-083"},{"speaker":"のだて委員","kind":"質問","question":"計画内容はどうなっているでしょうか。階数、高さ、用途、延床面積、そして総事業費、補助金、公共施設管理負担金、委託会社を伺います。","respondent":"東野まちづくり立体化担当課長","answer":"延床面積が約２万１,０００m2、金額的なところは、まだ情報については入ってきておりません。それから委託会社、こちらは事業協力者という意味でいきますと、大成建設が事業協力者になっております。","id":"exchange-084"},{"speaker":"のだて委員","kind":"質問","question":"土地、建物、借家、借地などの権利者について、全体が何人で、何人が参加・加入しているのか伺います。先ほどの大成建設は、参加組合員ということでよろしかったか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"借家人につきましては、増減あるところなのですけれども、私どもに届け出がある範囲では７５人というふうに聞いております。先ほどの土地建物所有者、借地権者２１件のうち、１９件が今、参加を表明しています。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問","question":"この１９番の再開発と、補助２９号線はどう関係しているのかも伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"五丁目１９番のところの再開発の範囲につきましては、今、０.３ｈａほどありますけれども、補助２９号線のところに一部かかってあります。先ほど委員からもお話がありました、公共施設管理者負担金という中での処理をしていくというふうに、私どもは聞いております。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"この１９番のところを、補助２９号線から立ち退かなければならない方の入居先にしようというお話もあるのか、伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"こちらの五丁目１９番の再開発計画の１つのコンセプトとしまして、補助２９号線、またはほかの特定整備路線にかかる方の住居の受け皿としてつくっていきたいというようなことも聞いておりますので、そういう可能性があると思います。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問","question":"この商店街の分断で、住民にどういう影響を与えるのか伺います。地域商業機能の低下も、住民にどういう影響を与えるのか伺います。","respondent":"東野まちづくり立体化担当課長","answer":"ただ単純に危惧しているだけではなくて、今後のまちづくりを地域の中で考えていきたいというところで、この再開発計画も出てきたところです。区としては、そういったまちの声に対して、支援をしていきたいというふうに考えてあります。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"地域の方も危惧しているところで、この補助２９号線を、それが原因なわけですから、これをやめていけば、そういった課題はないわけでありまして、この補助２９号線を、そういった面からもやめていくべきだと思いますが、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"商店街の皆様のご意見を１つ取り上げてみますと、もう１０年以上前から、今まで様々な検討をされていらっしゃいます。協議会の方針として、そして区と、また東京都が連携して進めているものです。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問","question":"そんなところに超高層がふさわしいと思うのか、伺います。この面からも、超高層はふさわしくないと思いますが、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"この駅前の再開発につきましては、地元の皆様方がこのようにしたいという考えの中で、区としても支援をしているものです。この高さ自体が、すなわち皆様のコミュニケーションの障害になるという、そういったご意見は伺ってはいないところです。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問","question":"区がどう考えているかということもお聞きしましたので、これがふさわしいと思うのか、伺いたいと思います。","respondent":"中村都市計画課長","answer":"区といたしましても、地元の皆様のそういった意向も踏まえて、また可能な限りの支援をしていくという考えです。こういったものを前向きに受け入れられる地元の方々の意思を尊重して、これからも支援を最大限続けていきたいと、そのように考えているところです。","id":"exchange-091"},{"speaker":"木村委員","kind":"質問","question":"私は、３１７ページの交通安全啓発費、それから３２７ページの道路バリアフリー事業、３２１ページ、ＬＥＤからの質問をいたします。３３１万円余ですけれども、交通安全宣言から５０年ということでありますが、この事業の説明もお願いをしたいと思います。","respondent":"桑波田交通安全担当課長","answer":"ここと連携を図りながら、区としても安全の教育を実施していこうということで、追加しています。これにつきましては、昭和４２年７月に、品川区において交通安全宣言を実施しました。","id":"exchange-092"},{"speaker":"木村委員","kind":"質問・要望","question":"蛍光灯、そして白熱灯、それから水銀灯とありますけれども、３種類の中からどれを取り除き、ＬＥＤに変えていくのでしょうか。その変えるわけというものもお聞かせを願えればと思います。","respondent":"多並道路課長","answer":"街路灯につきましては、国際条約の水銀に関する水俣条約に基づきまして、２０２０年までには水銀ランプ等の製造が禁止されるということを踏まえまして、平成３１年度までに、今の水銀灯をＬＥＤ化をしていくというのを、計画的に行っていこうというものです。","id":"exchange-093"},{"speaker":"木村委員","kind":"意見","question":"平成３１年に全てこの水銀灯がなくなるということでありますが、あと、これらも全て交換をしていく予定なのかどうかというのもお聞かせください。そして、平成３１年を目途に取り替えるということですけれども、先ほどのをお答えくださいとの意見を述べました。","respondent":"多並道路課長","answer":"水銀灯をＬＥＤ化していくのは、平成３１年度までに進めてまいります。ほかの水銀が含まれない製品についても、対象として考えていきたいというのが、今の考えです。","id":"exchange-094"},{"speaker":"木村委員","kind":"意見","question":"このＬＥＤなのですけれども、家庭の中で、普通の生活の中でも十二分に使えるものなのかどうかということも、の説明を求めました。","respondent":"多並道路課長","answer":"我々、街路灯でやっているものは、かなり大きい製品でやっているものなのですけれども、それ以外、民生品についても、電気会社に聞くところによると、かなりエネルギー効率が高いということで、環境課のほうでも一般家庭のほうに普及啓発しています。","id":"exchange-095"},{"speaker":"木村委員","kind":"意見","question":"次に、３２７ページの上から２行目、道路バリアフリー事業ですけれども、大井町駅周辺バリアフリー工事、７,０００万円、計上されています。これは、高齢者の方々にとってみれば、大変なバリアになると思いますけれども、これはどうしてなのかもの説明を求めました。","respondent":"多並道路課長","answer":"平成２７年から平成２９年の間、平成３１年度までということで、計画的に進めているものです。きれいに平坦化の整備をしていくと、そのような感じでやって、よりよい使い方ができるような形で行っているものです。","id":"exchange-096"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、３３９ページ、京浜急行線連続立体交差化、北品川駅前広場整備等検討委託について、お伺いをいたしたいと思います。これもオーダーを出すときに、そういう考えもオーダーの中に入れていただきたいと考えていますが、そのお考えをお願いしたい。","respondent":"東野まちづくり立体化担当課長","answer":"先般行われました京浜急行の連続立体交差化事業の素案説明会と合わせまして、地元のほうに説明をさせていただきました。そういった地元の要望を聞きながら、今、進めているところですので、委員のご提案につきましても一考させていただきたいというふうに思います。","id":"exchange-097"},{"speaker":"石田（秀）委員","kind":"提案","question":"本当にいいものになってほしいなと思っておりまして、大きさも含めて広告物みたいなところの規制が入ってしまうのかというのがよくわかりません。踏まえたけれども、それを超えてどういうふうにしていくというぐらいの、せっかく提案してもらうのなら、そういうことを１つとの意見を述べました。","respondent":"和田河川下水道課長","answer":"水辺の賑わい創出構想検討ですけれども、一方で、現在の守らなければならない景観というものも一方であります。我々のこの構想のほうもやっていかなければならないというふうに考えてございまして、検討を進めてまいりたいというふうに考えてあります。","id":"exchange-098"},{"speaker":"石田（秀）委員","kind":"質問","question":"ここをどうやって、やはりそこは超えなければならない部分があるのだろうなと、すごく感じています。ありかなと思うので、もう一度、ちょっと考え方を聞かせてもらっていいか尋ねました。","respondent":"和田河川下水道課長","answer":"基本的には定期航路を、定期航路とはいえ、途中がしっかりと賑やかでないとだめだという意識も持っていると。先ほど来からおっしゃっている東京都の条例も、その辺を議論を深めていって、検討していきたいというふうに考えてあります。","id":"exchange-099"},{"speaker":"石田（秀）委員","kind":"提案","question":"そういう提案をして、例えば第四日野小学校の卒業生に記念で配るとか、その板を何枚もつくっておいて。提案をして、そういう片隅を持っていてほしいなと思うのだけれども、考えの説明を求めました。","respondent":"多並道路課長","answer":"今の委員のご提案のとおり、やはり育ってきた学校の周辺でもありますし、やはり地元でも親しまれてきた桜ということですので、よくその辺は、地元もありますが、あと小学校も含めて幅広くご意見をお伺いして、有効活用できるのであれば図っていきたいと思うところです。","id":"exchange-100"},{"speaker":"こんの委員","kind":"質問","question":"具体的な方策をとっていくと思われますけれども、今後の、この老朽化への対策をどのように考えていらっしゃいますでしょうか。それについても改めて、行財政改革特別委員会でも少しお聞きしておりますけれども、改めてご説明願います。","respondent":"今井住宅課長","answer":"区営住宅の老朽化への対応ですが、計画的に修繕を行いまして、適切に進めているところです。平成２８年８月に、今後予定されております長寿命化の改修または建替え等を踏まえまして、計画を立てていきたいというふうに考えております。","id":"exchange-101"},{"speaker":"こんの委員","kind":"質問","question":"国の制度化された老朽化の観点で長寿命化という策定指針が出た、それに基づいて区としても進めていきたいというお考えを伺いました。１００％に近いぐらい、このバリアフリーの考え方は、その点についてもご見解の説明を求めました。","respondent":"今井住宅課長","answer":"手すりの設置ですとか、そういうもので対応してきたところですけれども、ほかの事業とも連携しながら見守りをしていきたいと考えています。一定、大規模な建替えや大規模な改修の時期に合わせて、大きなバリアフリーは進めていきたいというふうな考えです。","id":"exchange-102"},{"speaker":"こんの委員","kind":"提案","question":"実は平成２４年のときに、エレベーターの設置をというふうに提案をさせていただいた際に、日影の問題でつけられませんというご答弁だったのですとの意見を述べました。","respondent":"今井住宅課長","answer":"２カ所の大きくエレベーターを設置できる場所といっても、エレベーターの設置というのは、協議はしていますけれども難しいというふうな状況です。ほかの利用者の方々の状況を考えながら、検討は進めて、今後も続けていきたいと考えています。","id":"exchange-103"},{"speaker":"こんの委員","kind":"質問・要望","question":"理由を改めて伺ったのですが、ものすごく段差が高いのですよね、あそこ。ご答弁もう一言お願いいたします。","respondent":"今井住宅課長","answer":"複合施設であるということを踏まえて検討するとともに、または別の住宅等への住替えなどについても、またきちんとご案内できるように進めていきたいというふうに思っております。","id":"exchange-104"},{"speaker":"こんの委員","kind":"質問・要望","question":"こちらは先ほども質問が出ておりました、確認ですけれども、桐畑隧道を出てきた水神町会のお祭り広場の所を言っているのでしょうか。ここの徹底をどうされているのか、またしていただきたいのですけれども、いかがか尋ねました。","respondent":"多並道路課長","answer":"予定ですと、その後に、今、委員のご指摘にあったような場所を、今後やっていこうというところで、考えています。設置した後、そこの有効性というのは検討していきたいと、やっていきたいと思っているところです。","id":"exchange-105"},{"speaker":"高橋（し）委員","kind":"質問","question":"そちらの、今の４つの駅の駐輪場の稼働率と言うのでしょうか。それから利用状況についてのご見解と、ここの人口増加の中で、それに対する今後の見通しについてお伺いいたします。","respondent":"桑波田交通安全担当課長","answer":"品川シーサイドにつきましては７４.９％ということで、それぞれの場所によって、需要、利用について大分差があるところです。そういった需要を含めまして、民間を含めて、今後また設置に向けて考えていくことが必要であると考えております。","id":"exchange-106"},{"speaker":"高橋（し）委員","kind":"質問","question":"立会川のほうが８３％、あとシーサイドも、かなりマンションも多いということで、７４.９％ということであります。見通しで、少し探していくというお話でしたが、見通し的にはどのような状況か尋ねました。","respondent":"桑波田交通安全担当課長","answer":"民間も含めてやっているところです。そういったところも含めましてご案内して、ご利用いただくように進めていきたいと考えております。","id":"exchange-107"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"立会川のほうも、ぜひ今後の増加に備えて、用地の取得について動いてほしいと求めました。このような駐輪場、立会川・勝島まちづくりビジョン策定の中でどのような観点で計画案を立てていかれるのか、お教えほしいと求めました。","respondent":"中村都市計画課長","answer":"当然考えていく必要があると考えていますが、周辺の駅まで利用されるというところにおきましては、所管と十分調整をしながら進めていきたいというふうに考えております。","id":"exchange-108"},{"speaker":"高橋（し）委員","kind":"質問","question":"いろいろまちづくりの計画等が進められていますが、一般質問でもお尋ねしたのですが、マスタープランの中ではあまり具体的には出てきておりません。この人口増加について、東品川地区のまちづくりについて、改めて具体的にどのような取組みをなされるのか、お教えください。","respondent":"中村都市計画課長","answer":"四丁目で再開発が進められておりまして、マンションなども建替えも進んできているというところで、この辺を調和していくべき町並みの誘導を行っていきたいというふうに考えております。","id":"exchange-109"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今後この辺の東品川の地域をどういうふうにしていくかという、そういう話し合いの場を、これは要望としてお伝えしておきます。これは東京電力から借りているのだと思うのですが、今の月見橋の家が元に戻った場合、そこの場所をどのようにしてまた復旧していくのか尋ねました。","respondent":"溝口公園課長、和田河川下水道課長","answer":"平成２９年度に設計を行っていきますので、地域の声も聞きながら、検討していきたいというふうに考えているものです。一番北側にありますトイレの横に、高さ４ｍの六角柱、直径で言いますと３ｍぐらいの換気塔を作る予定です。仮施設を建てているものですが、その後の用途につきましては、今後検討してまいりたいと思っているところです。","id":"exchange-110"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"受託事業でそれを使って、従前、あるいはそれ以上の公園にしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"伊藤委員","kind":"提案","question":"１つの提案なのですけれども、例えば角の場所を品川区が借り入れをして、イメージは渋谷のスペイン坂スタジオってご存じでしょうかね。まだ間に合うと思うのですけれども、検討すべきと思うのですが、いかがでしょうかという質問ですとの意見を述べました。","respondent":"多並道路課長","answer":"国道事務所と連携しながら進めてまいります。事業を進めている中で、全体的な中の、総合的に検討してまいることだと思っているところです。","id":"exchange-112"},{"speaker":"伊藤委員","kind":"提案","question":"しかも目立つ角の場所ですから、品川区役所のイメージアップになると思うので、ぜひ検討をお願いをしておきます。いろいろな構想ができると思うのですが、構想として持っているのですが、いかがでしょうかという提案ですとの意見を述べました。","respondent":"溝口公園課長","answer":"はご理解、そういったものをいただきながら、公園の管理を進めてきているというところではあります。そういったものを考える際に、公園の管理も含めまして、検討していきたいというふうに考えているものです。","id":"exchange-113"},{"speaker":"伊藤委員","kind":"提案","question":"その将来は、当然、この品川区民公園全体を考えていくこともあるでしょうし、水族館だって、毎年何千万円もかけて運営していくわけではないですか。５年、１０年、いかがか尋ねました。","respondent":"溝口公園課長","answer":"一方で、そういったところも踏まえながら、今後のあり方というのは検討していかなければいけないというふうに考えているところです。運営しておりますサンシャイン、または近隣の方のご理解をいただきながら、十分検討していきたいというふうに考えているものです。","id":"exchange-114"},{"speaker":"伊藤委員","kind":"質問","question":"今、思い出しましたけれども、この水族館、閉園も含めた議論、相当されたではないですか、内部の検討会をつくって。それからベンチ、それから休憩する場所等の拡大も検討していくべきだと思うのですが、いかがか尋ねました。","respondent":"溝口公園課長","answer":"そういったところも含めて、いろいろ検討していきたいというふうに考えているところです。レストランも含めまして、平成２９年度に少し検討していく費用も予算化しておりますので、しっかり検討していきたいというふうに考えているものです。","id":"exchange-115"},{"speaker":"伊藤委員","kind":"質問","question":"それから事業者を選定するのは時間がかかるでしょうから、それは１つのアイデアとして、いろいろな社会資源を使うことは今できるはずですよ。やってほしいけれども、そういう移動販売車等の活用をすべきと思うのですが、いかがか尋ねました。","respondent":"溝口公園課長","answer":"ケータリングカーについても、導入したりとか、そういったところも取り組みながら進めてきているところです。リピーターとして水族館に来ていただける、そういった取組み、できることから着実に進めていきたいというふうに考えているものです。","id":"exchange-116"},{"speaker":"伊藤委員","kind":"提案","question":"私も一般質問でこのことを提案させていただきました。小学校や中学校の数も、やはりこのまちのあり方はもっと検討すべきということを提案させていただいたのですが、お答えをくださいとの意見を述べました。","respondent":"中村都市計画課長","answer":"生活施設ですとか、あるいは公共施設、こういったものの方向性についても含めて検討していく必要があると考えております。立会川地区と合わせて検討いたしますので、立会川地区との連携の仕方ですとか、こういったものも重要になってくるかと思います。","id":"exchange-117"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、３４７ページの大井町駅周辺地区再開発事業と、３５９ページの区営住宅について伺いたいと思います。６,０００万円という大きな金額ですので、詳しくの説明を求めました。","respondent":"稲田都市開発課長","answer":"それからもう１つ、単独検討ですが、これは１,５００万円、これは区の検討です。区の庁舎の再配置の検討や、また導入施設等がどういうものが考えられるのか、そういうところを検討していきたいというふうに考えております。","id":"exchange-118"},{"speaker":"石田（ち）委員","kind":"質問","question":"すみません、どこに委託をそれぞれされるのか、伺いたいと思います。それと、大井プレイス構想での、ここの広町の位置づけなども伺いたいと思います。","respondent":"稲田都市開発課長","answer":"ＪＲとの共同検討におきましては、ＪＲと協議しながら、また決めていくということになっていきます。その後、大井町のまちづくりの構想等も立てておりまして、それに沿った形で、この開発やまちづくりを考えていきたいというふうに考えております。","id":"exchange-119"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それなのに、これだけ６,０００万円という金額だけが決まっているというのが、ちょっとわからないのですが、そこを伺いたいと思います。","respondent":"稲田都市開発課長","answer":"委託先ですが、やはりこれはＪＲとの協議を、今後詰めていくというところでございまして、それによって決めていくです。大井町、広町、これもまちづくり構想がありますので、これに沿った形で考えていくです。","id":"exchange-120"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"風呂釜の設置や撤去について伺いたいのですけれども、事務事業概要では１３団地４３９戸ということでいいのか、ちょっと確認させていただきたいのと。そして、設置していない世帯があるのか、伺いたいと思います。","respondent":"今井住宅課長","answer":"長く入居された方もいらっしゃいますけれども、自己負担で設置し、退居の際は撤去をお願いするというのがルールで運用してきたものです。風呂釜の設置が全くないというところの住戸につきましては、把握をしておりません。","id":"exchange-121"},{"speaker":"石田（ち）委員","kind":"質問","question":"区営住宅は、要は所得が低い人が入っているのに、この自己負担はとても厳しいと思わないかどうか、区の見解を伺いたいと思います。ぜひ、区営住宅も、区の責任で設置していくと言うことに踏み込んでいくべきだと思うのですけれども、いかがか尋ねました。","respondent":"今井住宅課長","answer":"建替えを行っていく中で、浴室の設置を含め、バリアフリー化を進めていく考えです。計画的に浴槽の設置を進めるというふうには聞いておりますが、現在も都営住宅で設置をされていないところもあるというのは、品川区同様です。","id":"exchange-122"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、低所得者の住宅にはつかなくてもいいということなのでしょうか。区にもこの目標はあるのか、伺いたいと思います。","respondent":"今井住宅課長","answer":"品川区の区営住宅に対する浴槽設置の考えですけれども、こちらのほう、建替えに伴って進めていくというふうな考えです。建替え等を進めているところですので、風呂釜の設置について、区負担で設置する考えはございません。","id":"exchange-123"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"もしつけられていない世帯があれば、まるでこの水準を満たしていない住宅を、区が提供しているということになるのではないでしょうか。ぜひ目標を持って、計画を持ってほしいと求めましたけれども、いかがか尋ねました。","respondent":"今井住宅課長","answer":"１人当たり２５m2というところで、１人ずつ増加している中で、一定の面積が配分されているものです。品川区の区営住宅、そして区民住宅等とともに、この国が定めました住生活基本法におけますこの水準をきちんと満たしています。","id":"exchange-124"},{"speaker":"石田（ち）委員","kind":"質問","question":"浴槽について、私、伺ったので、ぜひそこに答えていただきたかったのですが、残念です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-125"},{"speaker":"若林委員","kind":"質問・要望","question":"それから、時間があれば、３３５ページの目黒川障害物調査について伺いたいと思います。そしてどんな交通手段を使っているかという調査をしているそうですけれども、こういう調査も合わせて活用しているのか、伺いたいと思います。","respondent":"中村都市計画課長","answer":"こういったものを、将来の交通計画を考える上での統計ということで、行っているです。したがいまして、品川区もこの統計を参考にして、計画を立てているです。","id":"exchange-126"},{"speaker":"若林委員","kind":"質問・要望","question":"今のはパーソントリップ調査を参考にして計画を立てているという答弁ですので、どんな計画があるのか教えてほしいと求めました。この延長１００ｍと、幅員１６ｍということだそうですが、ご説明をほしいと求めました。","respondent":"多並道路課長","answer":"ここの補助１６３号線の今後の整備のあり方とか、一緒に連携を図りながら、ここの大井町周辺の基盤整備というのは考えながら一緒に進めております。東京都とも連携を図り、全体的な調整のところも進めて、総合的な観点で進めていくべきだと考えるところです。","id":"exchange-127"},{"speaker":"若林委員","kind":"質問・要望","question":"補助１６３号線について、目的と、特に成果、ここをしっかりとご答弁ほしいと求めました。いわゆる路線バスがなかなか法律上通れない、こういう課題がありましたので、そこはしっかりとご答弁を。","respondent":"多並道路課長","answer":"安全上の課題があるということで、認可をするにはその辺が課題だろうということで、話を聞いているところです。ここのボトルネックの解消に向け、早期整備を進めたいということで、平成２９年度も予算計上させていただいたところです。","id":"exchange-128"},{"speaker":"若林委員","kind":"質問・要望","question":"この補助１６３号線、こういった課題の１つが大きく進展をするというふうに理解をしますので、頑張ってほしいと求めました。予算・決算の委員会でも取り上げたところですので、調査、または工事の概要をご説明ほしいと求めました。","respondent":"和田河川下水道課長","answer":"五反田リバーステーションが、オリンピック・パラリンピックまでにできるということで、舟運が活性化することが見込まれます。平成２９年度、１年かけまして、３年計画でやっていきたいというふうに考えているものです。","id":"exchange-129"},{"speaker":"若林委員","kind":"質問・要望","question":"しっかり進めてほしいと求めました。除去することによって、少しかさが上がるかということは、あるのか尋ねました。","respondent":"和田河川下水道課長","answer":"喫水の関係で、それはございません。","id":"exchange-130"},{"speaker":"松澤委員","kind":"質問","question":"４目都市開発費、３４９ページ、再度伺いたいということ。近隣との折衝というか、トラブルがなかったかどうか、その辺をまずお聞きしたいと思います。","respondent":"多並道路課長","answer":"舗装してまいりまして、１７５m2ほど、全体的に施工したところです。地元の件ですけれども、１軒１軒お話しさせていただいて、ご了解をいただきながら工事を進めたです。","id":"exchange-131"},{"speaker":"松澤委員","kind":"意見","question":"そして、狭い所は売却するというような方針になっていると思うのですけれども、これは、どれぐらいの広さだったら道路として開放していくのか。このように囲い込まれている土地というのはどのぐらいあるのか、その辺、お知らせほしいと求めました。","respondent":"安井土木管理課長","answer":"若干囲い込みされている、不法占有されているような所が７８路線ぐらいございまして、その辺を順次指導をしているといったところです。大体は、もともとが水路で細い所が多いのですけれども、必ずしも一定というわけではないというところが、実態です。","id":"exchange-132"},{"speaker":"松澤委員","kind":"質問・要望","question":"なおかつ、２軒にまたがっている、当然そうですよね、境ですから。この辺、何か要件が緩和されているということはあるのでしょうか、その辺をお聞きしたいと思います。","respondent":"安井土木管理課長","answer":"それぞれに行いながら、不法占有の解消、そちらのほうを対応していると。普通財産の処分については処理を進めることができるようになりましたので、そういった点でも、さらに進めていけるような形になってあります。","id":"exchange-133"},{"speaker":"松澤委員","kind":"質問・要望","question":"これはどういうことなのですかね。今の話ですと、公共溝渠は、買いたい人が、自分たちで測量するということなのか尋ねました。","respondent":"安井土木管理課長","answer":"私どもとしては、不法占用の早期解消ということで、測量を積極的に、区のほうで負担いたしまして、さらに、測量するということで、不法占有の状態にあるということをご認識いただくということで、少しでも不法占有の解消を進めるという形で、事業を進めてあります。","id":"exchange-134"},{"speaker":"松澤委員","kind":"質問","question":"他人、ほかの方がいるものですからね。これについて、その後、どのような形で、地権者の方にお話をして、交渉が進んでいるのか尋ねました。","respondent":"今井住宅課長","answer":"平成２８年の一定のときに、総合的に検討してまいりますということで、処理経過を差し上げたものです。その部分の不適切な部分については改善していただくようお願いいたしまして、実際に、所有者の方が対応していただいたところです。","id":"exchange-135"},{"speaker":"松澤委員","kind":"質問・要望","question":"都市防災まちづくり事業に関連して、イトーヨーカドー跡地をもう一度伺います。区や地元が要望している店舗というもの、改めて見つかったのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"同店跡地につきましては、解体工事前の地盤調査を先行して行うというふうに聞いております。店舗探しにつきましては、歳入でもお話ししましたとおり、立地上、収益性上から、難航しているというふうに聞いてあります。","id":"exchange-136"},{"speaker":"松澤委員","kind":"質問","question":"歳入で質問の際に、区が借りることも検討しているというお話を伺いました。こういう民間のものを、どんな検討をしているのか、この辺をちょっとお聞きしたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"店舗が見つからないという場合に備えまして、地元のほうからの要請もありますので、全部賃貸マンションにするよりも、地域にある行政ニーズに応えられるためのスペースを区が借りまして、施策展開していくというところを検討しています。","id":"exchange-137"},{"speaker":"松澤委員","kind":"質問","question":"ちょっと伺いたいのですけれども、これは賑わいにつながるのではないかなというふうに思っているのですが、この辺はいかがでしょうか。検討の余地はあるのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"地元の要望につきましては、賑わいの観点から店舗を入れてほしいということですので、私どものセクションとしては要望を続けてまいりたいと思います。区としての施策展開ということになりますので、委員ご提案も含めまして、担当所管とも調整してまいりたいと思います。","id":"exchange-138"},{"speaker":"松澤委員","kind":"質問","question":"要らないのではないかという声もありますけれども、なぜこれが基本設計委託、直すのでしょうか。あるいは何か、直してほかの使い方というものを考えているのでしょうか、その辺お聞きします。","respondent":"溝口公園課長","answer":"戸越公園につきましては、その管理事務所も老朽化、倉庫も含めて老朽化していることから、建替えというのを考えているものです。そういったものも含めて総合的に戸越公園の管理事務所の使い方を考えるために、設計の費用として、予算計上しているものです。","id":"exchange-139"},{"speaker":"松澤委員","kind":"質問","question":"荏原第四中学校の跡地に、今後２つですか。保育園に変えてやっていくということなので、それでは建て替える期間が足りないということで、ここにしましょうということなのか尋ねました。","respondent":"溝口公園課長","answer":"今ある倉庫も含めて、全体のところを見直し、改修をしていきたいというふうに考えているところです。戸越公園のところにつきましては、一応、今のところ、予定で行きますと、三ツ木保育園の改修に合わせて必要なものということで聞いているところです。","id":"exchange-140"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、その後、先ほども言われたように、その後の転用策を考えなければいけないというふうに思うのですね。あるいは恒久的な施設としてやっていくのか、その辺が本当に重要になると思うので、その点についてお聞きしたいと思います。","respondent":"溝口公園課長","answer":"平成３３年、平成３４年、２カ年の仮園舎としての使用を考えているところです。ただ、今後どういう形で、それ以降使っていくのかというのも、合わせて検討していきたいというふうに考えているところです。","id":"exchange-141"},{"speaker":"松澤委員","kind":"質問","question":"傾斜が急ですから、自転車が飛び出してくるのですね、それがある所。当然、品川区でしょうから、その点の考え方というのを聞いておきたいと思います。","respondent":"多並道路課長","answer":"地元の方からご要望がありまして、また警察とも協議して、今ご指摘いただいたような形にしています。ただ、またよりよい形があるのであれば進めていくところなのですけれども、なかなか限界があるのかなというのは感じているところです。","id":"exchange-142"},{"speaker":"藤原委員","kind":"意見","question":"もう２週間ぐらいしかないですけれども、これがどういう状況になるか、お答えください。３３５ページ、これはどういう経緯でああいう形になったか、お答えくださいとの意見を述べました。","respondent":"今井住宅課長、和田河川下水道課長","answer":"今回の定例会のほうに、２０年間の借上げの満期を迎えました２住宅のほうの返還ということで、議案のほうを提出しています。平成３１年度に１住宅、平成３１年度には、この地優賃の住宅はゼロという形になります。この設計変更の設計が完了いたしまして、３月いっぱいで家屋調査を行い、４月に工事を再開する見込みというふうに。","id":"exchange-143"},{"speaker":"藤原委員","kind":"質問・要望","question":"これの確認が１点。それと、３４３ページの天王洲公園の改修とか、３４５ページの八潮北公園の改修が出ていますけれども、この工事について、目的の説明を求めました。","respondent":"柏原企画調整課長、溝口公園課長","answer":"区を挙げて、このオリンピック・パラリンピックに向けての機運醸成ということでは、全力を上げたいというふうに思ってあります。そういった中で、全てのトイレを１回、利用者が多い所については２回、清掃しています。いずれにいたしましても、オリンピック・パラリンピック機運醸成に向けた、公園課としての取組みの一環として行ってきたというのが、実情です。","id":"exchange-144"},{"speaker":"藤原委員","kind":"質問","question":"区は、このスポーツの動向の高まりをどう捉えているのでしょうか。これについてちょっとお伺いしたいのですけれども、この便所に関して、どう臭いを感じられているのか、教えていただけますか。","respondent":"小川オリンピック・パラリンピック準備課長、立川経理課長","answer":"１点目の、オリンピック・パラリンピック大会を契機としたスポーツの高まりにつきまして、お答えします。引き続き根づかせていくことこそが、ソフト面のレガシーという観点からも大切であるという考えのもと、事業を推進しています。無洗浄式便器というのを導入しておりまして、ちょっと女性の委員の方はぴんと来ないと思いますので、ちょっと導入の経過等を説明します。委員ご指摘のとおり、人によっては臭いが気になるなどの課題があると考えているところです。","id":"exchange-145"},{"speaker":"藤原委員","kind":"質問・要望","question":"何か答弁があればいただきたいのですけれども。この土木部門とスポーツ部門、それとオリンピック・パラリンピック部門という形で、それぞれ、その公園に関してお答えをいただけますか。","respondent":"立川経理課長、溝口公園課長、小川オリンピック・パラリンピック準備課長","answer":"日常清掃に加えまして、詰まりの防止や臭気の軽減等を図っていくこととしましたので、今後とも快適にご利用いただければというふうに考えております。オリンピック・パラリンピックに向けた、それぞれ庁内での連携です。例えば八潮北公園のスケートボード場の整備につきましても、同様なことが行われております。","id":"exchange-146"},{"speaker":"藤原委員","kind":"質問","question":"せっかくスポーツ推進課長が出てきてくださったのですから、スケートボードができるわけですから、オリンピック・パラリンピック部門が代表しないで、スポーツ推進課長も答弁をお願いします。","respondent":"池田スポーツ推進課長","answer":"３課連携いたしまして、これ１つを目標にいたしましてやっていきたいと思いますので、ご利用のほうをよろしくお願いいたします。","id":"exchange-147"},{"speaker":"藤原委員","kind":"質問・要望","question":"３課だけではなくて、全庁挙げてやるのですから、３課中心に、全庁挙げてやってほしいと求めました。私も、２０２０、オリンピック、大成功することを祈って、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-148"},{"speaker":"あべ委員","kind":"質問","question":"ただ、午前中のご答弁では、２１７便で１,３００人と聞こえたのですけれども、これは１便当たり６人という数字になるのでしょうか。私はもう、それは１つの選択肢だと思うのですが、どのように考えて行っていらっしゃるのかというお気持ちを伺いたいと思います。","respondent":"桑波田交通安全担当課長、和田河川下水道課長、柏原企画調整課長、稲田都市開発課長、鈴木建築課長","answer":"年に３回ほど、大井ふ頭対策の会議ということで、対策を進めているところです。平成３０年度中に建築工事を着工、平成３１年度中に建築工事を完了し、元の場所に戻っていただくというスケジュールでやっているものです。月見橋の家の仮設が戻った後の土地の活用ということであろうかと思います。北品川五丁目第一地区の再開発によって、仮称目黒川デッキですが、現在のところ、つながっていないという状況です。がけの支援につきましては、公益性、公平性の考え方が必要だろうと。","id":"exchange-149"},{"speaker":"あべ委員","kind":"質問・要望","question":"あの道の部分、今の段階で、拡幅に向けて動いているのでしょうか。動き出す可能性はあるのか尋ねました。","respondent":"鈴木建築課長、稲田都市開発課長","answer":"４３カ所以外の、助成制度も含めて、周知していきたいというふうに考えてあります。そういう中で、委員おっしゃったようなことも話をしましたけれども、それは難しいというような回答を得ております。","id":"exchange-150"},{"speaker":"あべ委員","kind":"質問","question":"御殿山小学校西側の道については、もし、スケジュール的な目途があれば、教えてほしいと求めました。この交渉が難航している背景に、放射第２号線の話もあるとお考えか尋ねました。","respondent":"稲田都市開発課長","answer":"私どもとしては、それは関係ないというふうに思っております。","id":"exchange-151"},{"speaker":"飯沼委員","kind":"質問","question":"３３９ページの特定整備路線沿道まちづくり、３４３ページのトイレ改修工事について伺います。一刻も早く、ＬＧＢＴ対応のトイレ、必要と考えますが、いかがか尋ねました。","respondent":"中村都市計画課長、島袋人権啓発課長","answer":"東京都が進める道路の整備に合わせまして、そういったことに要する説明会、また資料作成等の委託費です。ＬＧＢＴ、あるいは性的マイノリティーの方に対する差別や偏見などは、様々な人権課題の１つであると考えております。国や都の動向を踏まえた上で、関係部署との連携をとり、対応をしてまいりたいと考えております。","id":"exchange-152"},{"speaker":"飯沼委員","kind":"質問・要望","question":"住宅建替えは、耐震化、不燃化、そして公園づくりなどに、住民の願いに、切実なところに応えるべきと思いますが、いかがでしょうか。今日はトイレのことで言いましたけれども、ぜひ区役所に、ＬＧＢＴの指針づくりなど検討会の設置を求めますが、いかがか尋ねました。","respondent":"中村都市計画課長、島袋人権啓発課長","answer":"こういったことを総合的に、重層的に進めることによって、不燃化がより一層加速するものというふうに考えております。人権尊重都市品川宣言を活用し、普及・啓発を、地道ではありますが、積み重ねてまいりたいと考えております。","id":"exchange-153"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ご要望・ご意見が届かないというところに、ぜひ、この間も質問したのですけれども、声が届かないというのは、見ようとしなければ見えないのですね。道路ごり押し、やめてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-154"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それから最後に、３５７ページの空き家等対策事業でお伺いします。本会議の代表質問で、ブロック塀対策についてお伺いをしまして、周知については個別に説明をしていきますと。","respondent":"多並道路課長、鈴木建築課長、今井住宅課長","answer":"この平成２９年度予算の中で計上させていただきまして、踏切が１５ｍぐらい、より通行が円滑にできるような形ということで考えているものです。４月頃には作成し、ホームページ等で公表というか、配っていきたいなというところです。平成２８年７月から、または適正管理に対するご相談またはご苦情、所有者からのご相談等をお受けしているものです。","id":"exchange-155"},{"speaker":"たけうち委員","kind":"質問・要望","question":"しっかりその辺の計画も、国や都の動きと合わせてしっかり連動してお願いしたいなと、これは要望します。その辺のところを、では、ちょっと状況の説明を求めました。","respondent":"多並道路課長、今井住宅課長","answer":"もちろん１日でも早く工事をやりたいところなのですけれども、それを整え次第、１日も早く工事をやっていきたいと思っているところです。空き家ホットラインにつきましては、今、ホームページ等で周知しておりますけれども、確かにまだまだ周知が足りないところです。","id":"exchange-156"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"大きなマンション計画が、今、大きいのが２つ続いています。この辺のところで、東品川のあの一画の関係をどう捉えていくのか、その点の説明を求めました。","respondent":"多並道路課長、中村都市計画課長","answer":"その中で今、国も非常に大きく進めていまして、ＩＣＴの紹介というのがいろいろあります。今後も、そういうようなものを踏まえながら、より道路のＩＣＴに向けた活用ができないかということを検討していきたいとは思っているところです。今、この地域に必要な施設のほうの整備を行い、マスタープランに示しております広域都市活性化拠点ゾーンとしての整備を進めてまいったところです。","id":"exchange-157"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"昨年のときには、まだ診断していないところがあるよと聞いていたのですが、そこがどうなったのかを教えてください。何かと言うと、オリンピックに向けて、ここの土地をどういうふうに交渉するかという、その辺の検討はされているのか尋ねました。","respondent":"鈴木建築課長、稲田都市開発課長","answer":"消火活動や物資の輸送のための復旧・復興の生命線、大動脈となる道路の確保というところで、東京都が条例によって１３路線指定しています。広町の件です。平成３０年１２月には解体工事が完了するということで、利用は今のところは考えてはいないのですが、話はしています。","id":"exchange-158"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"どう考えるかというのは、非常に、逆に聞きたくなってしまいます。これは課長でいいのか、区として今後どう考えるかというのは、どう考えたらいいのか尋ねました。","respondent":"稲田都市開発課長","answer":"確かに、建物が解体されていくと、広い土地ができるですが、ＪＲはＪＲで、この暫定の間、何らかの活用は考えているというふうに思われます。ただ、そういう中におきましても、区としての要望は伝えていきたいというところに考えております。","id":"exchange-159"},{"speaker":"鈴木（真）委員","kind":"質問","question":"長期的には平成３２年以降の検討ということをお聞きしていますし、区の単独の、庁舎の改築とかという問題も十分絡んでくると思うのですけれども。人の集まってもらえる場所にするべきだと、私は考えるのですが、あえてもう一言お答えいただけないか尋ねました。","respondent":"柏原企画調整課長","answer":"本格的な活用は検討ということではあるのですけれども、これだけ大きな土地が出るというのは、なかなかないというのは事実です。相手のあると言いますか、土地でありますので、そこは話を続けながらということになろうかと思います。","id":"exchange-160"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"２３区の中でも、駅前にこれだけの土地ができるというのは、まずないと思うので、ぜひ成功に向けて頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-161"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/805569?Template=document&Id=1064#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":133282,"voices":401}},{"id":"h29-20170315-3","meetingId":"h29-c-budget","date":"2017年3月15日","dateIso":"2017-03-15","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５６分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を164件整理しています。","topics":[{"id":"topic-01","title":"平成２９年度品川区一般会計予算","agenda":"平成２９年度品川区一般会計予算","exchanges":[{"speaker":"松澤委員","kind":"質問・要望","question":"しかし、この６年間、一度も放射性物質が検出されていないとの報告を受けておりますが、これで間違いないのか確認したいと思います。今回、昨年の２５０万８,０００円から１２１万２,０００円と半減しておりますけれども、この内容についてお知らせほしいと求めました。","respondent":"有馬学務課長","answer":"委員ご指摘のとおり、この検査は３月の震災の後、１２月から実施しているものです。全校年１回としておりましたストロンチウムの実施方法を見直して、これは３カ年で全校検査をするというような回数の見直しを行ったものです。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問・要望","question":"なぜストロンチウムの実施方法を見直されたのか、また検査の頻度が３年に１回ということですけれども、その根拠をお聞きしたいと思います。年２回実施しているということですけれども、なぜストロンチウムの見直しをし、説明してほしいと求めました。","respondent":"有馬学務課長","answer":"ストロンチウムの実施方法をなぜ見直したのかですけれども、汚染水問題が出たときに始めたということで、平成２６年度から始めております。","id":"exchange-002"},{"speaker":"松澤委員","kind":"質問","question":"今、伺いましたけれども、ということは、３年に１回にしましたということは、このまま３年間、結果的に続けてみる、続けるということなのでしょうか。その点をお聞きしたいと思います。","respondent":"有馬学務課長","answer":"今後、また汚染水の状況が変わったりしましたら、そのときは適切に判断してまいりたいと思います。現段階では、先ほど申し上げましたとおり、３年間に１度というような考えで実施したいと思ってはおりますが確定したものではございません。","id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"検査費用が安価とはいえ、役割は終わったのではないのでしょうか。原発いじめをなくすためにも、しっかりと調査すべきではないかと思っていますけれども、ご見解をお伺いいたします。","respondent":"有馬学務課長","answer":"当然、ヨウ素・セシウムにつきましても検討を行いました。２３区の状況も見まして、まだ半数以上の区で実施しているという状況もございまして、これについてはしばらく継続していこうという考えです。","id":"exchange-004"},{"speaker":"松澤委員","kind":"質問","question":"今、出荷制限の現状について、様々な食材の中でも出荷制限があるというお話も聞いています。現状と、市場の食材の安全性はどのようになっているのかお聞きしたいと思います。","respondent":"有馬学務課長","answer":"基本的には、関東甲信越でもそういうことで出荷制限にかかっているものもあります。ただし、それはあくまでも出荷制限がかかっておりますので、市場に流通しているものは基本的には安全だとは認識しております。","id":"exchange-005"},{"speaker":"松澤委員","kind":"質問・要望","question":"食の安全を守るために実施してきた。風評被害が広がる、そしていじめが広がるという現状の中では、しっかりと精査していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"つる委員","kind":"提案","question":"３６４ページ、３目教育指導費、３７５ページ、図書館経費、３９１ページ、脊柱側わん検診について伺っていきたいと思います。公明党からもそれを提案しているので、当然、それをきっかけとしていじめの原因にもなるというようなことも全国的にはあるようでありますとの意見を述べました。","respondent":"村尾教育総合支援センター長","answer":"いじめアンケート等を含めて学校からこちらに上がってまいりますが、そういう件については、現在のところは私のほうに入っている状況ではございません。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問","question":"私も実体験としてあるわけですから、冒頭申し上げたとおり、便育の取り組みが非常に大事ではないかと考えています。その絵を指摘しながら、非常に共感するところであるわけでありますけれど、この便育に関する取り組みについての説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"小学校に入ったときに、新１年生にはガイダンスとして、トイレの使い方等をまずしっかり子どもたちに伝えます。我慢するということではなく、健康のためには十分必要であるというようなこと、その辺についても指導はしています。","id":"exchange-008"},{"speaker":"つる委員","kind":"提案","question":"機会を通じて様々提案してまいりたいと思います。なので、過去にも提案させていただきましたが、その後の検討状況の説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"具体的に各学校で何か取り組みをということはこちらのほうには入っていないのですが、校長先生が先生方に対して、「笑点」を見ようと。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"改めてですけれど、品川区でも教師の方にお伝えしているということも伺っておりますので、取り組んでいただけることを検討ほしいと求めました。なので、返却ボックスが、そういう大型図書でもちゃんと返せるような改善というのは対応できますか尋ねました。","respondent":"木村品川図書館長","answer":"あるいはそれを置く場所でありますとか、そういう部分も含めまして、なかなか厳しいかというところはあります。引き続きお知らせなどご案内を丁寧に進めてまいりたいと考えています。","id":"exchange-010"},{"speaker":"つる委員","kind":"提案","question":"機会を捉えて、そういうボックスなどを入れかえる際には、そういったものも返却できるような口のつくりのものを検討ほしいと求めました。","respondent":"木村品川図書館長","answer":"実際に検討いたしました。そういうものと何か連携して、引き続き研究してまいりたいと考えています。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"間接的にも、やはり健全な児童・子どもの育成につながるのではないかと思いますので、取り組みを様々工夫してほしいと求めました。次に脊柱側わん検診ですが、これについては、まず現在、今年度からということで、実施状況についての説明を求めました。","respondent":"有馬学務課長","answer":"対象は５年生・７年生ということで、成長が著しい時期のお子さんということで設定して行いました。受診率はほぼ１００％に近いという形になってあります。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"その中で、治療が必要な生徒がいたのかどうかなど、傾向性の部分もの説明を求めました。","respondent":"有馬学務課長","answer":"中学生のほうは１,５５４人のうち２６人ということで、１.６７％が２次検診です。その結果、最終的に要治療となりましたのが、小学生で８名、０.３５％と中学生で２０名、１.２８％の合計２８名で０.７３％となっています。","id":"exchange-013"},{"speaker":"つる委員","kind":"提案","question":"モアレ検査を提案させていただいて導入していただいたわけでありますけれども、当然、現在もやっていただいていると思うのですが。本当に子どもの幸福のために身を削っていける、鉛筆のような教育委員会として、これからも品川区に頑張ってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"性的マイノリティーの子どもたちのいじめ被害について、なぜ多い傾向があるのか、教育委員会の見解を伺います。性の多様性について子どもたちが小・中学校で学ぶ機会は、どのような場があるのか、現状を伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"そういうところも含めて、子どもたちに対しては、正しい認識・知識を持たせていかなければいけないかと考えているところです。ただ、いわゆる教科指導ではなく、どちらかというと生活指導による個別対応というところで、個々に対応しているのが現状です。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"もう３０年も前のことですけれどもＬＧＢＴなど性の多様性について、当時は授業で異性愛を前提とし、当時の学習指導要領を伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"１点目ですけれども、認識が起きたのは、本当にごく最近の考え方だと捉えております。今、先生方に、これについての正しい認識を持たせなければならないというような現状です。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"その学校はどこかということと、私は全ての小・中学校で図書の配置と啓発ポスターの掲示を求めますけれども、いかがでしょうか。そして、新聞などを使用しての授業の話もありましたけれども、性の多様性について教材の作成と授業の実施を求めますけれども、いかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"「多様な性があることを知っていますか」ということで、こういうものを１つ、形として教員には伝えております。ＬＧＢＴにつきましては当然、教育の大きな１つの課題だと受けとめておりますので、そういうところで連携しながら進めていければと考えています。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"２０１３年のホワイトリボンキャンペーンの調査では、子ども時代に何らかの形でいじめや暴力の経験があったと答えたのが７割とあります。","respondent":"村尾教育総合支援センター長","answer":"特別支援コーディネーターを含めて、このＬＧＢＴについてはしっかり、昨年度から本年度も含めて検証を進めています。きちんとした個別対応ができるような体制、いじめ、また偏見等がないよう進めていこうと考えております。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"」ということへの誤解が、子どもをはじめ、社会全体に存在しているからではないでしょうか。まずは教育委員会でもチームを作って、抜本的に体制を強めていくことが必要だと思いますけれども、チームを作ることはいかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"教育内容の検討、有効性等、やはり意図的・計画的な施策を準備しなければならないと考えています。学習指導要領が今度、新しいものが出ますので、その辺との兼ね合いも含めながら検討を進めていこうと考えております。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"お話を伺ったりすると、例えば恋愛トークでは話を合わせたりと、いじめも含めてとても苦しい体験をしている方が多いということを実感します。","respondent":"村尾教育総合支援センター長","answer":"養護教諭との連携を図りながら、まず個別支援、個別対応を優先すべきものだと考えております。対応について考えていくかにつきましては、今後、市民科の中でどのような扱いをしていくかについて検討したいと考えております。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"どちらもオネエタレントとして扱われ、単に異性愛が前提という固定観念から、どちらも男性が好きだという新たな誤解も生まれております。この問題は私は緊急性があると思いますので、ぜひ積極的に、教材や授業で取り上げていただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"木村委員","kind":"意見","question":"最初に３６７ページのいじめ防止対策費ですけれども、「いじめは重大な人権侵害であり、決して許されません。現在のいじめと、理事者の皆さんの頃のいじめの違いというものは、どのように変わってきたと思いますか、の説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"いじめに関する認識の変化というようなご質問だと思います。そこにやはりいじめというようなものが入ってこないように、それについては子どもたちに正しく、現在も指導しています。","id":"exchange-022"},{"speaker":"木村委員","kind":"質問","question":"品川区の事例というのでしょうか、どのようにそれを解決できたのか、ご紹介ください。","respondent":"村尾教育総合支援センター長","answer":"各学校において、子どもたちに、いじめ防止という取り組みとして、本年度もバッジを作り、子どもたちの意識啓発を図っているところです。そして学校支援チームのＨＥＡＲＴＳが学校のほうに伺ったりしながら、また継続観察をするなど、きめ細やかな対応しています。","id":"exchange-023"},{"speaker":"木村委員","kind":"質問","question":"学校での教師は父親であり母親であるべきですし、生徒たちの前では毅然とした態度で振る舞ってほしいと思っています。人に優しくできるのではないかと考えますけれども、どのように考えているでしょうか、の説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"各学校教員一人一人が、子どもたちに、いじめは絶対許さないのだということで徹底した指導を進めています。子どもたちとの信頼関係を築くことも優先的に考えておりまして、この２面で現在、教育を進めているところです。","id":"exchange-024"},{"speaker":"木村委員","kind":"質問・要望","question":"頑張ってほしいと求めました。次に３６９ページの上から９行目、１つのことに精通した方々の経験談は何物にもかえられないし、の説明を求めました。","respondent":"熊谷指導課長","answer":"まさにそういった視点に立った、まちの人々に学ぶ授業ですけれども、やはり私ども教員だけでは深めることができない学習活動というのが多々あります。地域の方々の専門性、また経験といったことを、また子どもたち自身に地域の一員としての自覚が育つ授業であると感じております。","id":"exchange-025"},{"speaker":"木村委員","kind":"意見","question":"しかしながら、幼児期や小学校での運動経験や環境などが影響しており、１日や２日といった短期間の取り組みだけで改善するような問題ではありません。体力的、そして学力的にはどのように変化があったのか、もし大きな変化があればの説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"７年生から８年生用ということで、まさにこの取り組みは、毎日少しずつ子どもたちに運動習慣をつけさせようというのが目標で進めているところです。今年度はモデル校実施になりますけれども、本年度は４０％ということで、やはり運動習慣が拡大しているかと考えているところです。","id":"exchange-026"},{"speaker":"木村委員","kind":"意見","question":"頑張ってほしいと求めました。地域の住民は午後３時から、そして朝の８時ごろ散歩とありますけれども、その点だけの説明を求めました。","respondent":"品川庶務課長","answer":"８３運動のほうですが、教育委員会としましても、毎年、予算化しておりまして、啓発グッズ等をつくる費用で支援をしております。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"３９３ページ、また時間があれば３７５ページ、文化財保護事業における指定文化財についてお伺いいたします。そこをお伺いいたします。","respondent":"有馬学務課長","answer":"まず学校のほうに、老朽度といいますか、取りかえの希望調査をまず行います。その後は、校長のほうでしっかり検査をしていただくというような形での品質の確保を行っているところです。","id":"exchange-028"},{"speaker":"筒井委員","kind":"提案","question":"仕様変更の提案があった場合は、複数の専門業者、第三者の目からアドバイスを受けた上で決定すべきです。今述べたような問題解決のための提案の内容を、区のお考えはいかがでしょうか、お知らせくださいとの意見を述べました。","respondent":"篠田学校計画担当課長","answer":"かなり細かいところまでを設計に落とし込みまして、それを工事業者が施工図に落とし込んで、実際に工事を実施していく。規格の安易な変更ですけれども、同等の規格に仮に変更するとしても、こういった点での品質の低下が起きるということはございません。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"おそらく学校にいるとき一番長く見るもの、接するものですから、区としてもぜひとも行っていただきたいと考えております。厳しいチェックの目を向けていただきたいのですけれども、品川区のお考えとしてはいかがか尋ねました。","respondent":"小林施設整備課長","answer":"建設共同企業体で頑張っている施工者と、あとそれを見る現場の管理者として、第三者の設計事務所を入れております。そちらのほうでまず現場の管理をして、あと施設整備課の職員も含めて最終的な完了検査というのをやっております。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"実際、報告が届いていない可能性もありますので、ぜひともメーカーなどの専門業者のチェックの目を入れていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"区内開催・応援３競技体験教室、３７５ページ、ＰＴＡ活動支援のことを質問させてほしいと求めました。初めに、教職員健康管理費についてお伺いしたいと思います。","respondent":"品川庶務課長","answer":"教職員の健康管理ですが、定期健康診断につきましては、平成２６年、平成２７年と、両方とも受診率１００％となっています。それから本年度、平成２８年についても、ほぼ１００％に近くなっておりますので、月末までには１００％にいくと考えています。","id":"exchange-032"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"心のケアについてお知らせほしいと求めました。","respondent":"品川庶務課長","answer":"職員のメンタルヘルスの件ですが、平成２４年度から品川区独自でストレスチェックを行っております。教育委員会のほうから産業医等を通じて面談等をしたり、その面談の中で、やはり重い状況であれば病院を勧めるというような体制をとってあります。","id":"exchange-033"},{"speaker":"高橋（伸）委員","kind":"質問","question":"その学校に所属している学校長や副校長などが、ベテランの先生も含めて対応されてから、そういった診療をされるという認識でよろしいのか尋ねました。","respondent":"品川庶務課長","answer":"これはケースによって違ってくる場合もあります。上司である学校長、副校長を通したり、または通さなかったりというような個別の事例によって対応を変えているという状況です。","id":"exchange-034"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、３７１ページ、区内開催・応援３競技体験教室のことをお伺いさせてもらいます。区内３競技を区内全校で、それぞれ３競技ありますので、今現在の状況をお知らせほしいと求めました。","respondent":"熊谷指導課長","answer":"平成２８年度はブラインドサッカーが１６校、そしてホッケーは５校で実施しております。平成２９年度からは、各校１種目ずつローテーションで実施いたしまして、平成３１年度までに全ての学校で３競技の体験教室を行っていく予定です。","id":"exchange-035"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、３７５ページ、ＰＴＡ活動支援について、関連した話をさせてほしいと求めました。けれども、その辺のところの認識を教えていただければと考えています。","respondent":"熊谷指導課長","answer":"マラソン大会等に教員が土日に出ることですけれども、それにつきましては勤務として振り替えることができますので、子どもたちの応援をたくさんしてもらって、そして教員の力にもそれが返ってくると思いますので、ぜひ参加させていきたいと考えています。","id":"exchange-036"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ、各小学校の校長を含めて、啓発というか、ぜひ参加というか、応援に来ていただきたいと考えています。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"そして、あとストロンチウムの検査で、汚染水の状況を見てということも伺いました。その検査の回数が、もとに戻ることなどはないのかということも、重ねてお伺いいたします。","respondent":"有馬学務課長","answer":"これについては、平成２９年度も平成２８年度と同様に行っていく予定です。それから、ストロンチウム検査を３年で１巡にしたということの理由ですけれども、これについては様々私どもも検討いたしました。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問","question":"ストロンチウム検査の仕組みなのですけれど、保護者からも不安の声や不公平感の声というのは上がらないとは思うのです。不公平感が生まれないような仕組みができているのかということが聞きたかったので、そこを伺いたいと思います。","respondent":"有馬学務課長","answer":"そういう意味だと、今までどおり、年１回、各学校でやっていたという意味では公平だったですけれども、これまで３年間やってまいりました。どこまでやるのかというと切りがないと思いますけれども、これまでの３年間の状況を見て、今回はこのように判断させていただいたです。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問","question":"そこでもやはり、消費者の立場でも、検査して、その計測結果を見て判断することは大切だと私たちは伺いました。見解を伺います。","respondent":"有馬学務課長","answer":"出荷停止の状況については、毎年やはり件数的には、基準値を超える出荷物というのが減ってきているという状況が１つあります。もう一つは、それぞれの立場のところでやっていただくというのが原則でありまして、品川区がそこまで手を出すというつもりは今のところございません。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"２０１６年度予算特別委員会でＬＧＢＴ対応の質問を幾つかしたときには、それぞれ前向きなご答弁だったと理解しております。教育総合支援センター長は、何よりもまずは教員への研修が第一」と答弁されていますが、現時点で教職員への研修はどの程度進んでいるのか伺います。","respondent":"村尾教育総合支援センター長","answer":"本年度、大きく４点の研修でＬＧＢＴを捉え、教員に研修を行いました。特別支援教育コーディネーター、これは各学校に１名配置しておりますけれども、認識を持たせるような研修を進めております。","id":"exchange-041"},{"speaker":"田中委員","kind":"質問","question":"ＬＧＢＴに特化した教員向けの研修だったのでしょうか。もう一回、教えていただけますか。","respondent":"村尾教育総合支援センター長","answer":"ＬＧＢＴということで、性的マイノリティーに関する人権を含めての研修です。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問","question":"２０１６年度予算特別委員会のときに、ＬＧＢＴの子どもへの対応を伺ったところ、進めていくということを伺いました。具体的に挙げていただいた細かな個別の配慮はどの程度達成されているのでしょうか、伺います。","respondent":"村尾教育総合支援センター長","answer":"保護者への対応、それにつきましては各学校、どのような形でも対応できるように準備は進めているところです。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問","question":"ＬＧＢＴの子どもたちからの相談を待つだけではなく、相談機能もしっかりと学校の中に配置していこうと考えているところですと答弁されています。現在の相談機能の配置状況と、子どもたちへのメッセージはどのように発信されているのか伺います。","respondent":"品川庶務課長、村尾教育総合支援センター長","answer":"トイレの件ですが、改築する学校については、必ず、だれでもトイレというものを設置しておりますので、そういうもので対応しているという状況です。コーディネーターなどの活用により、どのような形でも、子どもが相談できる相談窓口は各学校に十分配備できていると考えております。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"いじめ防止対策推進法が制定され、その中で、各学校は、学校いじめ防止基本方針を策定することが求められました。現在、法律に基づいて、学校の基本方針策定状況はどの程度、進んでいるのか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"各学校におけるいじめ防止基本方針の状況というようなご質問です。いじめ防止対策推進法に規定された１３条で、いじめ防止基本方針を定めることとなっておりますので、この防止基本方針を持っているところです。","id":"exchange-045"},{"speaker":"田中委員","kind":"質問・要望","question":"伺ったところによると、法の求めに応じて基本方針を策定している学校も、２０１７年に向けて新たに方針を策定していると伺いました。どうしてこのような２度手間になるような事態になったのか、学校のほうが待つべきだったのでしょうか、伺います。","respondent":"村尾教育総合支援センター長","answer":"その後、実はこの基本方針というのは、学校の実態に応じて毎年、見直しを行うものです。区で行っている様々な取り組みを、この対策基本方針をつくっておりますので、毎年の変更について学校からの問い合わせ等は特にございません。","id":"exchange-046"},{"speaker":"田中委員","kind":"質問","question":"この学校いじめ防止基本方針というのは、各学校の特色が出てこそなのではないかと思います。これだと、何か品川区の定めた基本方針に沿わなければいけないというふうに、何となく思ってしまうのですけれど、そのところはいかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"各学校がつくっております基本方針については、どうしても、やはり基本的なベースは似ているかと考えています。ただ、いじめ防止という部分につきましては、全てにおいて共通する内容も当然含まれていくものと考えております。","id":"exchange-047"},{"speaker":"田中委員","kind":"質問","question":"学校の先生方はとても忙しいと認識しています。学校に余計な負荷をかけるべきではないという立場と各学校の特色も踏まえて作成されたほうがいいのではないかという意味で質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先日の一般質問でもやりましたが、この前の日曜日に新聞社主催の「ＡＩ時代に求められる教育とは」というフォーラムに参加してまいりました。","respondent":"熊谷指導課長","answer":"そういった能力のことですけれども、理解していること、できることをどう使っていくか。未知の状況にも対応できる、そういった力、思考力・判断力・表現力を活かした、そういった能力が必要であると考えております。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"意見","question":"これからすごい時代に突入するというご認識を教育委員会がお持ちで、どういう未知の状況に対応する能力を養っていくのか、ということでありました。京陽小学校について、ご答弁がまだでしたねとの意見を述べました。","respondent":"村尾教育総合支援センター長","answer":"本区においては、プログラミング教育におきましては、委員のご指摘のとおり、京陽小学校で３年間の研究を進めてまいりました。そういうことに対して、そういうものを子どもたちの学習の中で、様々なものに含めながらスタートしていくというような考えで行ってきております。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問","question":"ＡＩというのは、様々調べていくと、どうしても出てくるのが、ＳＴＥＭ教育という名称が出てきます。今回の京陽小学校の取り組みは、このＳＴＥＭ教育の一環として見ていいのかどうか、お伺いします。","respondent":"村尾教育総合支援センター長","answer":"その中で、子どもたちは情報技術を効果的に活用して、まさに論理的・創造的な考えができる。１つの大きな、総合的な理科系の教育の考え方ではありますけれども、様々な形で含まれていくものと考えております。","id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問・要望","question":"子どもたちに求められていく力というのは、ではどういう職がいいのですかという質問をみんな投げかけるのですけれども、そんなことはわかりませんと。そのためにどういう力を養成していくのか、改めて伺いたいと思います。","respondent":"熊谷指導課長","answer":"知・徳・体をしっかり持った上で、品川区の生き抜く力を育てていきたいと考えています。その上で、品川教育検討委員会を進めてまいりたいと考えています。","id":"exchange-052"},{"speaker":"あくつ委員","kind":"質問・要望","question":"３７３ページの人権教育というところで伺います。先ほどご答弁にもありましたけれど、多様性に関する理解力、差別解消といったものを学ぶ時間というのはどこにあるのか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"その取り組みを全校に広げながら、子どもたちの人権教育というものを今進めているところです。特別支援学校の子どもたちと、様々な形で、障害のある子どもたちとの触れ合いを通して学んでいくというような取り組みも進めているところです。","id":"exchange-053"},{"speaker":"あくつ委員","kind":"質問・要望","question":"企画調整課長に伺いたいのですけれども、２３区の中で、２０２０年から人口が減る１１区のうちに名指しされておりました。この根拠は何なのですかと私も問い合わせをしましたら、２０１３年の東京都の調査ということだったので、確かにそのとおりになっていました。","respondent":"柏原企画調整課長","answer":"その人口の全体のピークというのは５年先に延びておりまして、平成３７年がピークということで、東京都は新たに出しています。それで、品川区の人口推計で言いますと、平成３９年がピークということで、そこから緩やかに減るという状況で推計を出しています。","id":"exchange-054"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ただし一方で、これも長期計画の範囲内ですから、平成３９年まで、予想を超えて若年人口が増えていくとしている。この犯人は、意思疎通が困難な人が誰なのかをわざわざ職員に確認してから、１９人の知的障害者の方を選択して殺害した。","respondent":"村尾教育総合支援センター長","answer":"差別を行わないというような１つの方向、自治的活動領域、いわゆる道徳実践や社会的判断という中に福祉教育というものが大きく入っております。子どもたちに、正しい認識だけではなく、豊かな人間性や社会性というものをしっかりと身につけていこうと考えております。","id":"exchange-055"},{"speaker":"横山委員","kind":"質問","question":"３７１ページ、３６７ページ、いじめ防止対策費についてお伺いいたします。１点目は、いじめ防止対策費についてお伺いいたします。","respondent":"村尾教育総合支援センター長","answer":"都のほうから出されたものにつきましては、３つのアプリケーションを３月に公開予定と聞いております。同じグループなのですけど、学校のほうで対応するとともにＨＥＡＲＴＳも派遣し、すぐに対応させていただきました。","id":"exchange-056"},{"speaker":"横山委員","kind":"質問・要望","question":"情報モラルの研修にも参加していただいて、警察からも情報を得て連携しながら活動されているということをお聞きいたしました。そういった方を中心に研修を進めていただきたいと思うのですけれども、こちらの点、もう少し答弁をお願いいたします。","respondent":"村尾教育総合支援センター長","answer":"そこで本区では、情報モラル研修に、専門の外部機関の方に来ていただいて、研修を実施しています。教育委員会としても連携を図りながら、相談体制をしっかりと置きながら、子どもたちのトラブル解消に向けて取り組んでいこうと考えています。","id":"exchange-057"},{"speaker":"横山委員","kind":"質問","question":"そして、児童相談所移管推進に関連して、一時保護児の学校の扱いと、学校と一時保護所の連携についても、現状どうなっているのか教えてください。区だからこそできる部分が大いにあり、可能性を感じておりますが、区のお考えの説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"学校と一時保護所との連携につきましては、３つ目のご質問にもありますように、様々な形でケアをしております。現在、そのような状況で学校と取り組みを進めているところです。","id":"exchange-058"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目は、品川英語力推進プラン、オリンピック・パラリンピック教育推進事業の国際理解についてお伺いいたします。青山学院大学、アレン玉井教授が携わっておりますが、どのような経緯で導入されたのか尋ねました。","respondent":"熊谷指導課長","answer":"既に平成１８年度から実施してきているところですが、１年生から６年生に関しましては、全ての学校で３５時間実施していくところです。平成３０年度には、５・６年生には７０時間ということで、全校実施を行っていく予定です。","id":"exchange-059"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひ、品川区の今まで進めてきた英語教育に加えて、今回の改訂を含めまして進めてほしいと求めました。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今後のスケジュールを教えていただきたいのが１点です。品川区は市民科という教科がありますけれども、文部科学省の道徳の教科化と市民科との整合性をどう考えているのか、お伺いいたします。","respondent":"村尾教育総合支援センター長","answer":"まず５月ごろに、教科用図書調査検討委員会という、まず組織を立ち上げます。検討した上で、改めてこの検討委員会に提出し、８月までに決定するというような大きなスケジュールになっております。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そして面接などで、資料を様々集めて、考え方から行動に至るまで全面的な評価を行うように求められると思っています。内心の自由に踏み込んだ評価を教員がしていかなければならないという、このことに対して、区教育委員会の所見をお伺いしたいと思います。","respondent":"村尾教育総合支援センター長","answer":"そのステップ２の内容が、市民科の授業を、これまでと同様に進めていければと考えているところです。いわゆる評価としての考え方ですので、より子どもたちの道徳性の育成という部分につきましては、今後とも進めていければと考えています。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問","question":"新しく教科の本ができるということにおいて、品川区は今までの市民科の流れの中で道徳の教育ができていくのか、また評価が同じようなものとなるのか。この危惧を持っているのですけれども、今までと変わらない状況の中で道徳をやっていけるのか、もう一度お伺いいたします。","respondent":"村尾教育総合支援センター長","answer":"子どもたちの人間育成については進めていければと考えていますし、当然、様々な教育課題に対応できるものとしての市民科もあります。今後、国の道徳の教科化も含めながら、品川区ならではの市民科を進めていこうと考えております。","id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問・要望","question":"教職員が子どもたちにしっかりと向き合ってほしい、多忙化を何とか急いで解消していただきたいと思って質問します。多忙化の現状と課題をどのように認識されているのか、改めて伺います。","respondent":"熊谷指導課長","answer":"しかしながら、これについては省略できるのではないかというところについては時間短縮をということで取り組んでいるところです。そうした中で、現在、様々ではありますけれども、校長、副校長の働きかけにより、実態としましては勤務時間が短くなる状況にあります。","id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問・要望","question":"現状のところがちょっと一般論かと思って伺ったのですけれども、具体的につかんでいらっしゃるのでしょうか。数字で教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"ご質問にお答えしますが、勤務時間としては把握はしてございません。土日の勤務状況の把握ということがございましたけれども、土日につきましても打刻はできますので、打刻ができないという状況はございません。","id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それを、一体どこでどうやってつかんでいるのか、ぜひここを教えていただきたい。ぜひ、実態をどれだけつかんでいるのか、もう一回お伺いします。","respondent":"熊谷指導課長","answer":"先ほどご質問がございましたけれども、打刻ができないということにつきましては、土曜授業ですとか行事のときにできます。超勤につきましても、超勤４項目が決まっておりますので、それについては校長が職務命令として認めることができます。","id":"exchange-066"},{"speaker":"飯沼委員","kind":"意見","question":"そして、そこで仕事をしているにもかかわらず、本人が記録をとらない限り、その人の仕事状況がわからないのです。こんな状況ではとてもいかないと思いますので、ぜひつかんでくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"松永委員","kind":"質問","question":"水害など、いつどこで起きるかわからない災害に対してどのようなシステムで行動されることになっているのでしょうか、伺います。あわせまして、災害に対して、どのような教育がなされているのか、その内容について伺いたいと思います。","respondent":"熊谷指導課長","answer":"まず夜間・休日等、それから初期消火への従事、および教育長が指定する各種防災訓練への参加が義務づけられております。３回、それから避難訓練等にも活用することで、教職員として子どもへの安全教育にそれを活用しています。","id":"exchange-068"},{"speaker":"松永委員","kind":"質問","question":"年３回ということなのですけれども、昨年、震度７クラスの地震が発生したことを想定して、１２月５日に防災訓練が行われました。そのときに、教職員の方々はどのような形で防災訓練に参加されていたのか、そのことについて伺いたいと思います。","respondent":"熊谷指導課長","answer":"今のご質問ですけれども、直接、待機寮に入居している職員がそれに参加して、どのような動きをしたのかということはつかんでおりません。","id":"exchange-069"},{"speaker":"松永委員","kind":"質問・要望","question":"平成２９年度予算には、寮が２寮となっておりますけれども、現在何世帯住んでいて、災害対策の教職員が何人住んでいるのか、伺いたいと思います。","respondent":"熊谷指導課長","answer":"それから伊藤寮ですけれども、伊藤寮につきましては８世帯入居、そして入居者は８名となっています。実際にどのような役割分担がなされているかというご質問ですけれども、現段階では特段、役割といったものは課してはございません。","id":"exchange-070"},{"speaker":"松永委員","kind":"質問","question":"もしかしたら、これは独身の方なのかというふうな感じには読み取れるのですけれども、その辺について改めて伺いたいと思います。そして警察との連携について、どのような連携がとられているのか、また災害対策の教職員の男性と女性の割合がわかりましたらの説明を求めました。","respondent":"熊谷指導課長","answer":"こちらは偶然なのですけれども、男性が０名、女性が８名です。消防団等との連携ですけれども、消防、消防団とのつながりの構築がなされていると聞いております。","id":"exchange-071"},{"speaker":"松永委員","kind":"質問・要望","question":"本区では、昨年も同様、１０人となっておりますが、２３区内で比べまして１０名が妥当なのかどうか伺いたいと思います。先ほど巡回相談員について、ＬＧＢＴの知識も持っていると伺ったのですが、改めてその辺も伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"１０名で、各小・中、それから義務教育学校を巡回しながら対応はできていると考えているところです。特別支援教育係にこの巡回相談を束ねるチーフがおりますので、そことも連携しながら、児童・生徒の支援に回っているところです。","id":"exchange-072"},{"speaker":"松永委員","kind":"質問・要望","question":"３６７ページの品川学校支援チーム（ＨＥＡＲＴＳ）との関係性について、どのようになっているのか、それについて伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"特に重点的に行っていかなければいけない支援はどこだ、お互いに協力しながら進めていく、そのような関係です。その６年生は今度、それは、１年生などその他で使っていくということで考えております。","id":"exchange-073"},{"speaker":"松永委員","kind":"質問","question":"ポスターもお願いしたいのですけれども、そのときに行われたのかどうか、実績について少し伺いたいと思います。目安箱というのを質問させていただいたのですが、実績、必要性があるのかどうかというのも改めて伺いたいと思います。","respondent":"村尾教育総合支援センター長","answer":"今回、いじめ防止については進めているということで、またポスターについては少しこちらのほうでも研究させていただければと考えているところです。昨年度同様、そして学校に行き当該の児童・生徒と話をしたりするような取り組みは、現在も進めているところです。","id":"exchange-074"},{"speaker":"松永委員","kind":"質問・要望","question":"そこで、教育委員会として、なぜ差がついているのかについて、どのように考えているのか伺います。今後、保育園を卒業される方が小学校に上がった場合の、受け入れ体制について伺いたいと思います。","respondent":"有馬学務課長","answer":"今後は、各学校がそれぞれ良い教育に裏づけられた内容を進めていくことが大事だと考えています。就学人口につきましては、人口推計を毎年行っているところです。","id":"exchange-075"},{"speaker":"鈴木（博）委員","kind":"意見","question":"それと３８９ページの給食運営費に関連して、３９１ページの保健運営費に関連して、インフルエンザ罹患の中学生の転落事故についてお尋ねいたします。性感染症と性教育についてお尋ねしますとの意見を述べました。","respondent":"村尾教育総合支援センター長","answer":"性感染への問題意識のご質問ですが、ＡＩＤＳおよび性感染症の部分につきましては、現在、増加傾向、また低年齢化ということがうたわれておりますので、これについては教育委員会として高い問題意識を持っております。","id":"exchange-076"},{"speaker":"鈴木（博）委員","kind":"質問","question":"性感染症は、正しい知識と注意深い予防、そして、もしも罹患したときは早期の発見と早期の治療が極めて重要だとされています。例えば校外の医療関係者による性教育の授業などは考えられていたり、現在行われているのでしょうか、ご説明をお願いします。","respondent":"村尾教育総合支援センター長","answer":"７年生におきましては、そして９年生においては、進めているところです。現在、各学校においても外部講師による授業は行われておりませんが、基本的には養護教諭が連携して授業をしていると聞いております。","id":"exchange-077"},{"speaker":"鈴木（博）委員","kind":"質問","question":"平成２０年１月１７日の中教審答申では、以下のような、健やかな体を育む教育の在り方に関する専門部会の見解を踏まえて、告示、公示されました。","respondent":"村尾教育総合支援センター長","answer":"国も様々な形で性感染につきましては予防対策を進めていると、こちらも認識しております。これが教育の基本として考えております。","id":"exchange-078"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今回の事例を踏まえて品川区ではどのような対応がなされているのでしょうか。ノロウイルス感染症を含む感染性胃腸炎に対する学校現場の今現在の対応についてもご説明をお願いいたします。","respondent":"有馬学務課長","answer":"過日、立川市で発生した集団食中毒に対する区の対応ですけれども、私どものほうから衛生管理の徹底に努めるようにという通知をまず出しています。","id":"exchange-079"},{"speaker":"鈴木（博）委員","kind":"質問","question":"特に感染性胃腸炎の臨床検査については、現場ではどのように指導されているのでしょうか。ノロウイルスを含めた感染性胃腸炎一般について、現在の学校現場での感染予防の方法・指導についてご説明ください。","respondent":"有馬学務課長","answer":"今回の事例を受けて特に過剰な反応、何か、下痢をしたからすぐ医者に行けなどという指示は特に行っておりません。トイレを使った後あるいは食事を作る前といったところは、きちんと手洗いをするようにと、従来からの指導に努めているです。","id":"exchange-080"},{"speaker":"鈴木（博）委員","kind":"質問","question":"マスコミ報道に関連しまして、２月１４日、区内中学生が自宅マンションから転落死したという報道がありました。今回の事例の大まかな経過についてご説明をお願いします。","respondent":"村尾教育総合支援センター長","answer":"その後、また警察から第二報、第三報と入る中で、教育委員会としても緊急対応をとって体制を整えてまいりました。現在、子どもからの相談はありませんし、保護者からの問い合わせも特になく、学校も終業式を含めて予定どおり進んでいるという状況です。","id":"exchange-081"},{"speaker":"鈴木（博）委員","kind":"質問","question":"リレンザを服用したというような表現のニュースが多かったのですが、抗ウイルス剤については何か学校現場や教育委員会のほうで対応などはされたのか尋ねました。","respondent":"有馬学務課長","answer":"それから、２日間は特にそういう行動が多く見られるので、なるべく１人にさせないような配慮が必要だと言われているということ。それから、今言ったようなことを、ちゃんと学校内でも情報を共有してくださいというようなことを、校長会で伝えたです。","id":"exchange-082"},{"speaker":"西本委員","kind":"意見","question":"３６７ページの、いじめ防止の点で、福島県のほうから避難されている方がいらっしゃると思います。原発に関するいじめがあるのか、ないのか、そういう調査をしたのかどうかお尋ねしますとの意見を述べました。","respondent":"村尾教育総合支援センター長","answer":"原発に関する避難の子どもたちへのいじめということで、私も新聞を見て大変心を痛めました。学校のほうでも、それについては今後、十分気をつけていくようにということでお答えをいただいています。","id":"exchange-083"},{"speaker":"西本委員","kind":"質問・要望","question":"私は、もう６年過ぎている中で、税金を使ってこれの検査をするという意味があるのかどうかということを非常に疑問に思っております。それについてのお考えをほしいと求めました。","respondent":"有馬学務課長","answer":"あくまでも食の安全の確保ということです。一気に廃止というのは、まだもう少し様子を見たいということで、今回はこういうご提案をさせていただいたところです。","id":"exchange-084"},{"speaker":"西本委員","kind":"質問","question":"それで、品川区の給食では、保育園・幼稚園もそうですけれども、チェックされているものを使っているのですよね。そこでチェックしていないものを使っているのか尋ねました。","respondent":"有馬学務課長","answer":"安全を確保するために、一歩踏み込んでという形にはなりますけれども、それで実施してきたということです。全体の方向としてみれば、私どもについても、このまま縮減の方向に向かっていく事業であるかとは思っているところです。","id":"exchange-085"},{"speaker":"西本委員","kind":"質問・要望","question":"現在、不登校は何人いらっしゃるのか、そして要因はどのように分析をされているでしょうか。は病気等、それぞれの不登校になっている要因というものがわかっているのかどうか、の説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"平成２７年度につきましては、昨年度からの比較というのも変ですけれども、同じような横並びの数値になっているのかと考えているところです。その辺を含めまして、各学校においてもその辺を十分に注視しながら、子どもたちへの対応を、今、進めているところです。","id":"exchange-086"},{"speaker":"西本委員","kind":"意見","question":"それに対しての、何か原因を探るという、本人の状況で異なるかと思いますけれども、その要因をどのように解明していくのか。様々なサポートをする体制などは研究されているのか、実際やられているのか、お知らせくださいとの意見を述べました。","respondent":"村尾教育総合支援センター長","answer":"現在、対応といたしましては……。","id":"exchange-087"},{"speaker":"塚本委員","kind":"質問","question":"それから３９１ページ、かみ合わせの矯正について、それから時間があれば３８１ページの学校ＩＣＴ活用経費をお伺いしたいと思います。","respondent":"村尾教育総合支援センター長","answer":"地域の主任児童委員との連携を図りながらも含めて、きめ細かく一件一件、対応させていただいているところです。年間、また保護者の支援が子どもの学校復帰にはとても重要かと考えていますので、センターとしてもできる限りの対応を進めていこうと考えております。","id":"exchange-088"},{"speaker":"塚本委員","kind":"質問・要望","question":"もとに、学校に通えるようにと思うために、学校側にも様々な対応を求めてくる場合もあるかと思います。そういったことは良いことなのか、どうなのか、考え方としてどう思っていらっしゃるかお伺いしたいと思います。","respondent":"村尾教育総合支援センター長","answer":"特別教室を使って、子どもをそこで、様々な形で対応できるようにしているというのが一般的だと考えております。中学校で言うと、また教科書を一緒に時間があればやってみるような形で、やはり個別に学校のほうでは対応していると聞いております。","id":"exchange-089"},{"speaker":"塚本委員","kind":"質問・要望","question":"では次に、平成２４年の我が会派の一般質問でこの問題を取り上げまして、まずは国の保険適用の動向を注視したいというご答弁でありました。かみ合わせの状況で大変に心配だというようなことは、常々ご要望、お話があるところです。","respondent":"有馬学務課長","answer":"それで、申しわけございません。歯科の部分だけの統計は、今資料を持ち合わせてございません。","id":"exchange-090"},{"speaker":"塚本委員","kind":"質問・要望","question":"適宜、適切な対応ができるように今後とも対応してほしいと求めましたので、よろしくお願いいたします。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"沢田委員","kind":"意見","question":"それから３７３ページの代替職員雇用費について、それから時間があったら３６９ページの市民科の士業を活用した授業について聞きたいと思います。最近されているのか、またどういった基準で品川区の学校に教育実習の学生が来ているのか、の説明を求めました。","respondent":"熊谷指導課長","answer":"実習の受け入れですけれども、平成２８年度、品川区では、幼稚園２９名、小学校５１名、中学校２６名、受け入れてあります。大学によっても、その受け入れ、どのように依頼をしてくるかというのは異なっているところです。","id":"exchange-092"},{"speaker":"沢田委員","kind":"意見","question":"学校としても良いことだし、品川区としても良いことだし、子どもにとっても良い影響があると思うのです。受け入れる先生たちの意識、学校の意識というのはどういう形で、その辺のお考えの説明を求めました。","respondent":"熊谷指導課長","answer":"ですので、学習指導、生活指導、進路指導、それぞれきちんと指導を行って受け入れをしています。この教育実習の場であると思っていますので、そういったことも踏まえながら、学校としては組織的に支援をしていっているところです。","id":"exchange-093"},{"speaker":"沢田委員","kind":"質問・要望","question":"これは年間、どれぐらいの代替の教員がいるのか、また代替の教員の質というものがどうなっているのか、お聞かせください。どういった方が代替で来ているのか、どういった方を採用しているのか、の説明を求めました。","respondent":"熊谷指導課長","answer":"その上で、決定が下った後に、その名簿から候補者を選んでいるです。そして義務教育学校では育休代替が９人、産休代替が０人ということで、７３名の育休・産休代替教員が教壇に立っているところです。","id":"exchange-094"},{"speaker":"沢田委員","kind":"意見","question":"その質というのはやはり重要だと思うのですけれども、これはどういった研修体制を整えられていて、また代替で来るとすぐに授業をやると思うのです。そういったときに、どのように代替教員のサポートをしているのか、その辺のところの体制について聞かせてくださいとの意見を述べました。","respondent":"熊谷指導課長","answer":"ＯＪＴもしっかりとっておりますし、また区の研修、都の研修にも参加できるような体制をとっております。基本的には、校長、副校長を中心にサポート体制をしっかりとって、実際には子どもたちへの授業力向上に向けて支援しています。","id":"exchange-095"},{"speaker":"沢田委員","kind":"質問・要望","question":"そういったサポートをしっかりやっていってほしいと求めましたし、教員を抜けられていたりされていて、来られる方だと思うのです。校長、できれば品川区の他の先生がしばらく、そのあたりの体制をもう一度聞かせてください。","respondent":"熊谷指導課長","answer":"比較的、品川区の場合は、継続して行ってらっしゃる先生をお願いしているケースが多うあります。ただ、若手の代替教員もおりますので、学校としてサポート体制を今後もしっかり組んでいきたいと思います。","id":"exchange-096"},{"speaker":"南委員","kind":"質問","question":"３８８ページの学校給食費について伺います。子どもたちの命と安全を守る上での自治体の役割として、これはしっかり検査するべきだと考えていますけれども、その点について伺います。","respondent":"有馬学務課長","answer":"２３区の動向、それから他の地方の都市の状況というところも、まだ検査をしているところもあります。あわせて、それらの動向を見ながら、あるいは出荷停止の状況等、様々見ながら考えていきたいと思ってあります。","id":"exchange-097"},{"speaker":"南委員","kind":"質問・要望","question":"私は、品川区の自治体としての立場をしっかり守って、必要な検査はきちんと続けていただきたいと改めて要望したいと思います。この給食費補助を導入した理由というのはどういうことなのか尋ねました。","respondent":"有馬学務課長","answer":"これにつきましては、事業を開始したのは昭和５５年となります。区立の小・中学校、経済的理由によりこれを負担することが困難と認められる保護者に対して、負担の軽減を図るということで開始しているものです。","id":"exchange-098"},{"speaker":"南委員","kind":"質問","question":"昭和５５年という、大分、何年も前なわけです。１・２年生、３・４年生、それぞれ区分けしているグループで月額の説明を求めました。","respondent":"有馬学務課長","answer":"給食につきましては、単価はそれぞれ、低学年が２４０円、中学年が２６０円、高学年が２８０円、中学生は一律３２０円となっております。これの食数、月分という形になります。","id":"exchange-099"},{"speaker":"南委員","kind":"質問・要望","question":"中学生も４,８７３人、計算を合わせると大体１億１,０００万円ぐらいあると、これは品川区の今の財政状況から見て十分可能ではないかと思います。","respondent":"有馬学務課長","answer":"今、平均すると、大体２万人、生徒がいらっしゃると思います。それで、月額５,０００円ですので、年に直すと６万円程度になりますので、これを単純にすると１２億円という計算になります。","id":"exchange-100"},{"speaker":"南委員","kind":"質問・要望","question":"数字の違いは訂正したいと思います。１２億円にしても、本当にこの不況の中で、その負担を軽減するという立場に立ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"渡部委員","kind":"質問","question":"３６７ページは校外授業費のところで伺ってまいりますので、よろしくお願いいたします。それと、１つ私ども、ずっと、兄弟枠というのですか、優先をお願いしていた経緯もあります。","respondent":"有馬学務課長","answer":"兄弟枠につきましては、小学校で３名が入れませんでした。これは昨年１０名でしたので、これも多少は改善されているという状況です。","id":"exchange-102"},{"speaker":"渡部委員","kind":"質問","question":"そもそもの位置づけというのですか、移動教室ですから、もともとどういう質のものなのかというところを教えてください。お願いします。","respondent":"有馬学務課長","answer":"６年生と７年生で実施していますけれども、それから集団生活をそこで行って、規律や連帯感を養う。実際には、これは教育課程上の一環ということで行われているものです。","id":"exchange-103"},{"speaker":"渡部委員","kind":"確認","question":"５年生の段階から徐々に始めて、その集大成として移動教室なのか、改めて確認するというような意味合いの授業というのはできないのか。","respondent":"有馬学務課長","answer":"まず日光の光林荘を６年生は使っておりますけれども、ここは従前、学習室やレクリエーションホールといったものもそろっています。宿を借りるときにはアルコールの自動販売機は全部禁止するですとか、細かいルールもありますので、なかなかちょっと難しいかと思ってあります。","id":"exchange-104"},{"speaker":"渡部委員","kind":"質問","question":"費用的なところですとか、様々な問題点が多いのはもう承知しております。どういうふうにやったら何か可能なのかなどと少し考えながら、またいつか質問したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"あべ委員","kind":"質問・要望","question":"３６４ページにかかわって、特別支援教育費ですとか、そしてまた３８１ページにありますタブレット端末等の導入などについて伺いたいと思います。指導課長に以前、その後、ご体験していただいたかどうかということをお伺いしたいと思います。","respondent":"熊谷指導課長、村尾教育総合支援センター長、有馬学務課長","answer":"ダイアログ・イン・ザ・ダークにつきましては、委員からご説明いただきまして、私、個人として非常に興味深く思ったところです。更衣室については、どこがあいているかみたいなものについては、十分やはり検討できる内容かと考えています。大体、教員の８０％ほどが毎日使っている、週に３回以上は使っているということで、大分、浸透はしてきていると考えています。","id":"exchange-106"},{"speaker":"あべ委員","kind":"質問・要望","question":"不登校の子どもたちに対しての学習支援策の一つとして、ぜひタブレットを使っての学習というのを導入してはいかがかと思いますが、いかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"ｅラーニングという形で、パソコンを使って、自分のつまずきのところまでさかのぼって学習ができるような仕組みをとっております。モデル的に進めていまして、全学年対応で１年生から９年生までの内容が入っておりますので、様々な形で拡大できればと考えています。","id":"exchange-107"},{"speaker":"あべ委員","kind":"質問・要望","question":"この機会に、これからの品川区の教育について私の考えを少しお伝えし、また教育委員会のお考えも伺いたいと思います。この荒波、変化する社会の中で、生きていけるだけの力を持つ子どもたちを育てていくことが、教育委員会、そして大人たちに求められていると思います。","respondent":"中島教育長","answer":"今までは学校の教員が中心となって進めてまいりましたけれども、学校だけでは解決できない要素もそこにたくさん入り込んできております。今、まさにそういったところの連携を図って、これからの子どもたちを育てていける１つの仕組みではないかと考えております。","id":"exchange-108"},{"speaker":"こんの委員","kind":"確認","question":"プラン２１推進事業に関連して、学校選択制について、小学校における兄弟枠の受け入れの考え方についてお聞きしたいと思います。確認したいのですが、保護者の方の状況などを踏まえて、どのように捉えていらっしゃいますか尋ねました。","respondent":"有馬学務課長","answer":"これはやはり当然、兄弟は同じ学校に行ったほうが、そのお子さんのためにもなるだろうというような配慮はあったと考えています。それから、これまでもブロック外で、指定校変更によって希望があったかですけれども、毎年数件は発生しております。","id":"exchange-109"},{"speaker":"こんの委員","kind":"意見","question":"これは１つの事例を申し上げたいのですけれども、２人のお子さんを持つご家庭の事例であります。今後どのように、こうしたことの対策としてお考えになっていることがあるのであれば、お聞かせ願いたいと思いますとの意見を述べました。","respondent":"有馬学務課長","answer":"しかし、基本的なルールといたしましては、まずは区域内のお子さんは必ず受け入れるという責務もありますので、それは最低限行うです。今回の事例もまた課題だとは捉えておりますけれども、全体を見通して、また兄弟枠のあり方については考えていきたいとは思ってあります。","id":"exchange-110"},{"speaker":"こんの委員","kind":"質問・要望","question":"教育の公平性というところで、やはりご家庭の事情があっても、その子には行ける権利というのがあるというところを担保していただきたい。","respondent":"有馬学務課長","answer":"個々の事情は本当にそれぞれケースがあると思いますので、きちんと聞いていきたいと思います。その中でご家庭も判断されることだと思いますし、我々も１つのそういった兄弟枠についての課題だとは、今回は受けとめてあります。","id":"exchange-111"},{"speaker":"こんの委員","kind":"質問・要望","question":"要望で終わります。どういう手だてを、またどういうサポートを、品川区としてされているのか教えてほしいと求めました。","respondent":"村尾教育総合支援センター長","answer":"今年から始まったので９年生が入って、センターのほうに合格の報告に来て、みんなで喜んだということもあります。進学というのを１つの目標として子どもたちは頑張っておりますので、２次募集を含めて、様々な形で対応していこうと考えております。","id":"exchange-112"},{"speaker":"こんの委員","kind":"質問","question":"それは、やはり同じようなものが情報提供されて、進路が決まっていくものなのか。連携をとっているといっても、より細かく情報提供ができるのはマイスクールの先生のほうかとイメージしているのですが、その辺はどうなのか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"直接、当然ながら連携を図りながらということはありますけれども、学校とマイスクール八潮はしっかり連携を図りながら進めていく。必ず毎月、学校とやりとりをしながら情報交換をしているということもありますので、今後とも引き続き行っていこうと考えております。","id":"exchange-113"},{"speaker":"こんの委員","kind":"質問・要望","question":"私が少し問題として思ったのが、確かに学校に来る情報のほうが多いですから、そこから合ったものを情報提供しながら進路を選んでいく。毎年、進学が進むように、これからも頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"渡辺委員","kind":"質問","question":"そして、４つのアクションがその後、続いて、今後やりたい抱負というのですか、目的がある。あるいは次年度、どんな予定で、この４つのテーマがそれぞれどう進めていかれるのかの説明を求めました。","respondent":"村尾教育総合支援センター長、熊谷指導課長","answer":"これも１つの教材開発かと考えています。本当にその地域の特色ある教育活動を進めたり、今後とも様々な形での外部人材の活用、また教育の質の向上に向かって進めていければと考えております。今年度は、オリンピアンが１７校、そしてパラリンピアンが９校で実施したところです。オリンピックもパラリンピックもできませんので、環境の取り組みといったものを中心に、子どもたちには学習をさせているところです。","id":"exchange-115"},{"speaker":"渡辺委員","kind":"質問","question":"国際感覚を養うという点で、もう一言、こういう課題に対してどう取り組むのか教えてください。この辺で、障害者スポーツの啓発を含めて、学校教育の件、抱負をお知らせください。","respondent":"熊谷指導課長","answer":"国際交流ですけれども、国際理解教育におきましては、現在、区内の全ての学校、幼稚園で、世界ともだちプロジェクトを実施しているところです。","id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"質問","question":"学校選択制なので、３６３ページの就学事務費か、先ほどのプラン２１推進事業なのでしょうか。どのように整合性をとって、品川区の新しい教育要領を策定していくのか尋ねました。","respondent":"有馬学務課長、村尾教育総合支援センター長、熊谷指導課長","answer":"とれないです。私からは、特別支援教室におけるご質問にお答えいたします。これにつきましては、学校の様々な状況、また理由により、校長の判断で行ったと聞いております。実際にカリキュラムの中でもリテラシーを行ってまいります。","id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"あわせてご見解を伺います。普通教室の担任となった先生には、兼務発令ということで、そして特別支援教室の継続した指導についてのお考えを伺います。","respondent":"有馬学務課長、村尾教育総合支援センター長","answer":"例えば保育園でも、スクールステイというようなことで、保育園も連携しているようなところもあります。そうしますと、大分、対象も広がってしまったりしますので、これは慎重な検討が必要だと考えております。継続性につきましては、通常、きちんとした引き継ぎを行っていくというような考えです。なお、兼務発令等については、今年度、特には行っていないということなので、これについては交代ということで進んでいるところです。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ですから、志望する保護者の方や児童が増えて、特別支援教室の希望者が増えているとお聞きしています。ですから、その成果をぜひ来年度に活かしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-119"},{"speaker":"のだて委員","kind":"質問","question":"私からは、３６３ページの学事制度検討経費に関連して、学校選択制について伺います。現在行われております学事制度審議会の検討項目に学校選択制を入れた区の問題意識を伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"学校選択制につきましては、平成１１年・１２年から、小学校・中学校という形で導入されてきました。今年度から品川区教育ルネサンスという形で新たな展開を進めている中で、学校選択制についても検討項目の一つとして入れてきたものです。","id":"exchange-120"},{"speaker":"のだて委員","kind":"質問","question":"なぜ入れたかをお聞きしたので、区の問題意識をお答えほしいと求めました。","respondent":"篠田学校計画担当課長","answer":"１つの制度ですので、必ずしも１つの制度が永久に続くわけでもございませんし、ここでの検討の項目として改めて入れることとしたものです。","id":"exchange-121"},{"speaker":"のだて委員","kind":"質問","question":"人口の変化や、選択できない状況、永久に続かないというお話もありましたけれども、まだこの選択制については、学事制度審議会の議題にはなっていませんけれども、自由発言のときなど、この間の審議会では、学校選択制についてどういう指摘があったのか伺います。","respondent":"篠田学校計画担当課長","answer":"必ずしも地域との結びつきという部分ではうまくいっていない部分があるのではないかというような率直なご意見をいただいているところもあります。","id":"exchange-122"},{"speaker":"のだて委員","kind":"質問","question":"学校選択の結果、別々の３つの小学校に通っているような現状もあり、町会側がどこの学校とかかわればよいか迷っているという意見も出ています。選択制によって、地域とのつながりが弱まっているのではないかと思いますが、いかがか尋ねました。","respondent":"篠田学校計画担当課長","answer":"他の地域の学校に行ってしまうといった形で、町会活動等にも影響が出ているというようなお話もいただいているところではあります。学校との結びつきといった観点で考えますと、そういった意味では、そういった考え方も変化してきているのではないかと考えているところです。","id":"exchange-123"},{"speaker":"のだて委員","kind":"質問","question":"一応、弱まっているという声もあると。導入から、こういった、学校選択制によって地域とのつながりが弱まるという声が根強く上げられているのはなぜだと考えているのか伺います。","respondent":"篠田学校計画担当課長","answer":"例えば、今、実際に学校に通われている方の７５％は学区域のお子さんでいらっしゃいます。ですので、そういった意味では、必ずしも地域との結びつきが弱くなってしまっているという形では捉えてはおりません。","id":"exchange-124"},{"speaker":"のだて委員","kind":"質問","question":"なぜ弱まっているという声が上がっていると考えているか、なぜなのかということをお聞きしたので伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"それは、それぞれ地域ごとに、必ずしも全ての地域で全てのお子さんが地元の学校に行かれているとは限りませんし、比較的多くのお子さんが別の学校に行かれているといった地域もあると思いますので、それぞれの地域特性によるものと考えております。","id":"exchange-125"},{"speaker":"のだて委員","kind":"質問","question":"選択制で地域のつながりが分断されているという声も寄せられます。学校選択が地域のつながりを弱める一因だと考えているのか、伺います。","respondent":"篠田学校計画担当課長","answer":"制度実施による１つの結果ですので、地域の７５％の子どもはそれぞれ地域の学校に行かれているというような状況もありますので、一概にそれだけが原因という言い方はなかなかできないのではないかと考えているところです。","id":"exchange-126"},{"speaker":"のだて委員","kind":"質問","question":"様々な理由があるということでしたけれども、私が聞いたのは、学校選択がその一因でもあるかということをお聞きしたので、伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"ただいまご答弁申し上げたとおり、様々な要因の中で、要因であることは否定はできないけれどもという形を申し上げたので。ただ、それだけではないと考えているところです。","id":"exchange-127"},{"speaker":"のだて委員","kind":"質問","question":"どの学校にするのか選ぶ心理から、学校の内側からでなく、外側からの視点が強くなってしまったのではないでしょうか。教育委員会の見解を伺います。","respondent":"篠田学校計画担当課長","answer":"保護者の方の選択という観点ももちろんあるのですけれども、そもそも学校が地域に対してどうやって開かれていくかということ。特に、地域との結びつきが弱いといった中で、学校がどう変わっていくかといったために導入された制度であると認識しております。","id":"exchange-128"},{"speaker":"のだて委員","kind":"質問","question":"親の心理が変わってしまったのではないかということをお聞きしたので、その見解を伺いたいと思います。","respondent":"有馬学務課長","answer":"全体では７割、８割の方がいらっしゃいまして、学校の活動にも入っていますしＰＴＡの活動にも入っております。そして、それなりにきちんと活動はされている状況は、かいま見られるのではないかと考えております。","id":"exchange-129"},{"speaker":"のだて委員","kind":"質問","question":"杉並区では、学校関係者からも、廃止の声が３８.１％、見直しが３４.４％ということでアンケート結果が出ておりまして、既に廃止しました。中学校で６名いるわけですから、見直す必要があるのではないでしょうか、伺います。","respondent":"有馬学務課長","answer":"希望校に入れなかった人数というのは１１０名、小学校が約７００名、中学校でも６００名を超える方が希望している中での数字です。６００名を超える中での６名が入れなかったということですので、全て選択制がだめだとは、まずならないのではないかと考えております。","id":"exchange-130"},{"speaker":"のだて委員","kind":"質問","question":"やはり、公教育、義務教育ですから、悩んで選択しても入れないと。この状況をどう考えているのか、伺いたいと思います。","respondent":"有馬学務課長","answer":"理想を申し上げれば、１００％受け入れられる状況をつくり出す、そういう努力をするのが必要だとは思っています。１００％ではないかもしれないですけれども、できる限り応えているというのが今の現状です。","id":"exchange-131"},{"speaker":"のだて委員","kind":"質問","question":"１,０００人いる学校から１学級しかない学校など様々あって、そういったところで、義務教育のところで競争が生まれてしまっています。","respondent":"有馬学務課長","answer":"基本的に、競争によってとは考えてございません。クラブ活動だとか、そういうことが優先されておりますので、そういったことはないと理解しております。","id":"exchange-132"},{"speaker":"のだて委員","kind":"質問・要望","question":"学校選択制によって、様々地域の繋がりなどの問題が発生してきております。ぜひ廃止も含めて見直しをしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-133"},{"speaker":"伊藤委員","kind":"質問","question":"品川女子学院にお伺いした際、多分、生徒が作成したパワーポイントを使ってプレゼン等をしていく。これからの品川区のＩＣＴ化の方向について、こういうことを例にして具体的な展開をしていくべきと考えますが、いかがでしょうかという質問です。","respondent":"熊谷指導課長","answer":"今ご指摘いただいた品川女子学院の例ですけれども、確かに非常にすぐれた取り組みをしていると感じています。そうした事例につきましても今後、発表して、様々な学校でその取り組みを活かしていけるよう努力していきたいと思います。","id":"exchange-134"},{"speaker":"伊藤委員","kind":"意見","question":"やはり、それがこれからの方向性として可能だと思うのだけれども、その具体的な今後の計画、見通し等についてお知らせください。お願いいたしますとの意見を述べました。","respondent":"有馬学務課長","answer":"小規模校の支援ということで、中学校２校につきましては、１人１台のタブレットを配備しています。あわせて、校内ＬＡＮを整備しまして、そういった環境を整えていきたいと考えているところです。","id":"exchange-135"},{"speaker":"伊藤委員","kind":"意見","question":"年齢の関係があるからなかなか難しいのかもしれないけれども、タブレット端末等を貸与して、それを活用して授業を展開していく。それが次のステップだと思うのだけれども、もう一言、答弁をお願いいたしますとの意見を述べました。","respondent":"有馬学務課長","answer":"今後、どこまで広げていくかですけれども、その効果を見ながらというのが１つです。全教室に対するプロジェクター等の整備も同時に行いますので、そういったことを踏まえて、また検討していきたいとは思ってあります。","id":"exchange-136"},{"speaker":"伊藤委員","kind":"意見","question":"逆の現象ですよね。だから、例えば世界文化の多様性に応じた教育の展開をすべきではないかという意見があったので、そのことについて品川区の見解をお願いいたしますとの意見を述べました。","respondent":"品川庶務課長","answer":"学校では、１年生のときに生活科の中で、トイレのことを勉強するということがあります。そこで、１年生も和式トイレの使い方などを勉強するというような教育体制を図っております。","id":"exchange-137"},{"speaker":"伊藤委員","kind":"質問","question":"世界の中で多様な文化があるわけですから、そのことの、もう一つ答弁をお願いしたい。そういう教育の現場では、１つの方向性のみ推し進めていくのではなくて、いかがでしょうかという質問なのです。","respondent":"村尾教育総合支援センター長","answer":"当然教えていくべきものだと考えておりますし、また子どもたち同士が様々な形で話し合ったり考えたりする、必要になってくるかと考えております。","id":"exchange-138"},{"speaker":"伊藤委員","kind":"意見","question":"ざっくりとした答弁で、要は１つの固定観念を中心として教育を展開していくと、様々なところで弊害が出てくるわけだと私は思うのですとの意見を述べました。","respondent":"村尾教育総合支援センター長","answer":"１年生から９年生という義務教育の中で、きちんと社会の中での現実を見せ、それに対して子どもたちの意見をまとめながら教育は進めていく。その中で市民科が中心になっていくべきだと考えております。","id":"exchange-139"},{"speaker":"若林委員","kind":"質問・要望","question":"３７３ページの特別支援教育費と、３６４ページの教育指導費、これはがん教育について伺いたいと思います。特別支援教室のない学校はあるのか、あったら数も教えてほしいと求めました。","respondent":"村尾教育総合支援センター長","answer":"当然、子どもたちは様々個別対応が受けられますので、その学校の特別支援教室で特別の支援を受けるというような形になっておりますので。この特別支援教室の考え方は、全校で実施していますので、この教室がない学校はございません。","id":"exchange-140"},{"speaker":"若林委員","kind":"質問・要望","question":"施設に行ったときも伺っておりまして、これまでは２年生と聞いていた覚えがあるのですが、この辺をちょっと教えてほしいと求めました。そして今後どういうふうに、平成２９年度、そこをお聞かせほしいと求めました。","respondent":"村尾教育総合支援センター長","answer":"Ｗｉｓｃ検査につきましては、１年生から６年生、どの学年でも対応できると考えています。今後、がん教育については、より進めていければと考えております。","id":"exchange-141"},{"speaker":"石田（秀）委員","kind":"質問","question":"それから、あと、この前伺ったら、美理容の学校も定数割ればかりだと。それで、では木育というのはあまり学校で聞かないと思っていたのだけれども、こういう木育という捉え方はどうお考えかというのをまずお聞きします。","respondent":"村尾教育総合支援センター長","answer":"図工の中で木を使って様々なものを作るというような取り組み、どういうふうな中で自然とのかかわりがあるのかなどについても学習をしている。トータルで言うと、木に触れる教育というのは、実はまだまだ学校の中にはあるのかと考えております。","id":"exchange-142"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これはお願いで、要望だけでやめます。だから、そこら辺の点を公の部分としてどうお考えなのかというのを教えていただきたい。","respondent":"熊谷指導課長","answer":"実は本区におきましては、私立幼稚園の教員も、それから保育士も一緒に学ぶための研修会も実施しているところです。私立の幼稚園のほうは、こちらのほうで把握してございませんけれども、そういうところです。","id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"「わからないことが多い」と回答した子どもは、小学校５年生で困窮層で２８.７％、中学２年生では５１.５％に上りました。子どもの学習指導をしている教育委員会は、このことについてどのようにお考えか尋ねました。","respondent":"熊谷指導課長","answer":"子どもたちの置かれている様々な環境、それに伴って支援していくということは、とても重要だと思っています。コミュニティ・スクール実施に伴い、放課後の学習支援、そして長期休業中の学習支援ということで。","id":"exchange-144"},{"speaker":"須貝委員","kind":"意見","question":"例えば、この子たちが、授業の３分の２しか受けられない、半分しか受けられないのだったらわかります。それについて、責任というか、そういうものをお感じになりませんかとの意見を述べました。","respondent":"熊谷指導課長","answer":"本区でも放課後の学習支援をやっていますけれども、保護者、一緒にやって学習習慣を定着させている。そこのところで子どもたちの学力がぐんと伸びていると聞いております。","id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"他自治体でやっているのですから、何で品川区ではできないのですかということを、まずお聞かせください。やはりきちんとした成果というのを出さないと、教育の現場としても私はおかしいのではないかと思うのですが、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"委員が今、品川区はなぜできないのかというご質問があったのですけれども、大丈夫です。ですので、そういった苦手分野を克服するための支援を、学校でもそうですが、放課後の学習でも行っていくことが重要だと考えております。","id":"exchange-146"},{"speaker":"須貝委員","kind":"質問・要望","question":"そういうものを求めていくには、学力がないと、やはり難しいではないですか。そういう状態になってほしいのですが、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"そういった子どもの顔を見ながら、その時、その時で対応していく。それが私たち教員の存在意味だと思っています。","id":"exchange-147"},{"speaker":"須貝委員","kind":"意見","question":"教員の負担は絶対、どう考えても重過ぎます。きちんと学べるような、私はそういう学校を、教育現場をつくってほしいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-148"},{"speaker":"石田（し）委員","kind":"質問","question":"３６５ページの学校ＩＣＴ化推進経費について、３８１ページの学校ＩＣＴ活用経費について、時間があれば図書館経費についてお伺いいたします。伝統文化の発信能力育成事業等もやられているので、非常に効果的ではないかと思うのですが、どのようにお考えか尋ねました。","respondent":"熊谷指導課長、有馬学務課長、村尾教育総合支援センター長","answer":"先に組織間連携ツールについてお伝えしたいと思います。指導課、教育総合支援センター、それから学校管理職がモデルとして実施することによりまして。来年度は８校分、新たに校内無線ＬＡＮを設置する予定でございまして、約１,１４０万円というものを見込んです。愕然とするほど、主体的に学習に取り組んでいないというような結果があらわれたと、そこで大きく取り上げられたものかと考えております。英語で、または片言の現地の言葉で、伝え合うというようなことを行っているところです。申し訳ございません。","id":"exchange-149"},{"speaker":"石田（し）委員","kind":"質問","question":"月、何回会議があるかだけ教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"会議ですけれども、大体、週に１回は、職員会議、もしくは研修会、研究会というのがありますので、大体、月にしますと多くて５回ぐらい、４、５回だです。","id":"exchange-150"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"情報収集、そして小規模校の支援にぜひ活かしてほしいと求めましたが、いかがでしょうか。これはぜひこういったデータをしっかりと蓄積して活用していただきたいと思うのですが、ご見解をお知らせください。","respondent":"有馬学務課長","answer":"平成２５年に一度、導入を検討するまでには至りませんでしたけれど、こういうものがあるのだということで認識したものです。ぜひ、このデータを活かして、タブレットのない学校の学習指導にも活かしていきたいと、今、考えているところです。","id":"exchange-151"},{"speaker":"石田（し）委員","kind":"意見","question":"どうしても、これは学校の工事も、ぜひそういったことも検討を今後進めていってほしいと求めました。時間があるので１点だけ、図書館経費ですが、品川区の図書館における、電子書籍の導入の取り組みについて、現状と今後のお考えをお知らせくださいとの意見を述べました。","respondent":"木村品川図書館長","answer":"現在、研究段階というようなところです。まだ具体的に、そういうところまではまだ至っておりませんが、引き続き研究してまいりたいと思ったところです。","id":"exchange-152"},{"speaker":"石田（し）委員","kind":"意見","question":"もう民間では全然、使われているわけでありますし、いわゆる人的な部分も非常に効率がよくなっていくのかと思います。電子書籍があればなくなっていくのかと思いますので、ぜひ研究から検討の段階に入ってほしいと求めましたので、引き続きとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-153"},{"speaker":"安藤委員","kind":"質問","question":"移転理由を変えるとは一体どういうことなのでしょうか。これでは住民をだましたのではないでしょうか、伺いたいと思います。","respondent":"木村品川図書館長","answer":"それから、品川産業支援交流施設（ＳＨＩＰ）の開設に伴いまして、大崎図書館自体の再活用を検討するというような段階におりました。ですので、理由に関しましては今までのご説明、ご答弁と変わるところはございません。","id":"exchange-154"},{"speaker":"安藤委員","kind":"質問","question":"区立図書館の広報紙にも、大崎図書館の紹介として、「２階にはビジネスコーナーが設けられており」とあります。それがあって、批判が強くなって、その都度、理由を後から考えているから、こうなるのではないのか尋ねました。","respondent":"木村品川図書館長","answer":"理由をその都度変えているというようなご認識ということではありますけれども、説明をそのような意味で、してきたつもりはございません。それで、実際にそこでＳＨＩＰとの連携みたいな部分も考え得るのではないかというところです。","id":"exchange-155"},{"speaker":"安藤委員","kind":"質問・要望","question":"本人、あるいは担任や学校への、そして学校ホームページなどの掲載はどうなっているのか、それぞれ伺いたいと思います。最後に、東京都の学力テストおよび全国学力テストとの違いはあるのか、ないのかも伺います。","respondent":"熊谷指導課長","answer":"これはコミュニティ・スクール実施校のみですけれども、９月７日に教育委員会に、そして９月２０日に学校ホームページに公表していきます。これまでも、区は４年生と７年生、そして都は５年生と８年生ということで実施してきたところです。","id":"exchange-156"},{"speaker":"安藤委員","kind":"質問","question":"おまえ、どうなのだということで競争が激化しないか、危惧するところです。区の考えを伺いますが、学力テストではかれる学力とは何なのか、子どもの何がはかれると考えているのか伺いたいと思います。","respondent":"熊谷指導課長","answer":"そして、教員にとっても指導力の改善ということにつなげていけると考えております。そうした手だてを講じることができると思います。","id":"exchange-157"},{"speaker":"安藤委員","kind":"質問","question":"中学校も、品川区が１３.３％で全国は３２％と、非常に低くなっております。そうした心配について、区はどのように考えるか尋ねました。","respondent":"熊谷指導課長","answer":"そのため、これまでよりも増えるかといいますと、実は４・７年生に関しては減るです。だからこそ、これから、こうした子どもへのアンケート等も含めて、授業の改善について、また区としても学校と一緒に考えていきたいと考えております。","id":"exchange-158"},{"speaker":"安藤委員","kind":"質問・要望","question":"紹介しましたように、テストの点数を獲得するためにどうするかということが中心の学校になっていき、そして子どもたちが追い詰められる。学力テストの拡大は中止を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-159"},{"speaker":"たけうち委員","kind":"質問・要望","question":"３６７ページの、いじめ防止対策費、３７５ページの文化財保護事業、３８７ページの就学援助費でお伺いします。ネットいじめが４件、持たせる理由はなぜなのかというところ、どのようにつかんでいるかの説明を求めました。","respondent":"村尾教育総合支援センター長、品川庶務課長、有馬学務課長","answer":"保護者への啓発も進めながら、持たせるのであれば必ず、きちっと子どもと話し合って家庭のルールを決める。このような取り組みは進めているところです。文化財の件ですが、これは広報のほうで、しながわ百景アプリ、ＡＲ技術を活用した記念撮影スポットというものをアプリでやっていく予定でおります。３点目の、新入学学用品費につきましては、当該学年に入らないと対象になっていないというのが現状です。","id":"exchange-160"},{"speaker":"たけうち委員","kind":"質問・要望","question":"２０２０年までに２００カ所を目指して、ぜひ検討していただきたいと、これは要望にとどめておきます。そうした動きを見きわめて、積極的にそういった前倒しも行っていただきたいと要望させていただきたいのですが、ご見解をお願いいたします。","respondent":"濱田生活安全担当課長、有馬学務課長","answer":"区民の声で、平成２６年に回答しております。こういったことで対応しております。前倒しの検討ですけれども、そのような国の動きということがあります。２３区でも実施あるいは検討を始めたという区もありますので、そういったことも含めながら、今後の検討課題とさせていただきたいと思ってあります。","id":"exchange-161"},{"speaker":"鈴木（真）委員","kind":"確認","question":"小学校・中学校・義務教育学校の建築年次を確認させていただいたところ、一番古いのが昭和３３年の鮫浜小学校ということで、改築の計画が出ています。","respondent":"熊谷指導課長、篠田学校計画担当課長","answer":"学校支援ボランティア連絡用郵券が、そして学校支援地域本部通信費が、学校支援ボランティア保険料が。本部用の備品購入費として、３４校分、３４０万円を計上しています。現在、本日も幾つかお話が出てきましたけれど、就学人口の急増といったことが見込まれているところがあります。","id":"exchange-162"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"前に質問に入れさせてもらったことがあると思うのですが、すごくこれから責任感を持ってやっていこうということでお話を伺っています。それから、この１億３,４００万円というのは、自費なのか、国から出てくるのか、その辺の説明を求めました。","respondent":"熊谷指導課長、篠田学校計画担当課長","answer":"コーディネーターの人数ですけれども、学校配置が３７人、そして指導課で総括するコーディネーターが１人ですので、３８名です。城南小学校の改築に当たっての埋蔵文化財の対応ですけれども、こちらのほうで計上していたものです。埋蔵文化財等の対応につきましては、そういった調査に関しましては全部、一般財源でやるという形になっているものです。","id":"exchange-163"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"どういうものが出てくるか、その辺はわからないのですけれど、工事が順調に進むようにお願いしたいと思います。この学習指導要領と教育ルネサンスをどのように結びつけて、区の教育を展開させていくのか、そこら辺の点についてお答えをお願いしたいと思います。","respondent":"中島教育長","answer":"まさにこれは、教育ルネサンスの中でコミュニティ・スクールを実施する私たちの構想と合致するところであります。さらに、これからも教育のあり方を検討していくことも踏まえて、より良い品川区のあしたの教育をつくってまいりたいと考えます。","id":"exchange-164"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/805569?Template=document&Id=1066#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":132166,"voices":367}},{"id":"h29-20170317-7","meetingId":"h29-cm03","date":"2017年3月17日","dateIso":"2017-03-17","committee":"厚生委員会","time":"午後 ２時００分～午後 ３時３２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"第３６号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第３６号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"横山委員","kind":"確認","question":"１点だけ確認したいことがあるのでお願いします。品川区も既に取り組みされているかと思うのですけれども、その辺について確認をお願いします。","respondent":"高森国保医療年金課長","answer":"２年に１回更新なのですけれども、１０月の時期に同封して、ジェネリックの医薬品のＰＲをしております。平成２７年度に計画を策定させていただいて平成２８年度から進めているのですけれども、さまざまな形で機会を通じて推進を図っているところです。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それからこの資料なのですけれども、国保運営協議会に出された資料と随分違う資料になっているというのはなぜなのでしょうか。なぜ国保運営協議会に出された資料からかなりのページを減らした資料になったのかの説明を求めました。","respondent":"高森国保医療年金課長","answer":"今日お出しした厚生委員会資料よりもかなり大きいものですけれども、必要な部分を抽出いたしまして、今回委員会資料として提示しています。それ以上の意味はございません。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"加入世帯がどれぐらいいて、それが経年的にどういうふうに変化しているのかとかという、そういう推移はどこかに書かれているでしょうか。４０歳から６４歳までの方は、その介護納付金の所得割のパーセンテージですとか、そういうものの記載がありますか尋ねました。","respondent":"高森国保医療年金課長","answer":"次回以降については、また戻させていただいて、よりわかりやすい資料を作成のうえ、提案していきたいと考えています。そしてこの賦課割合、所得割率については、各区独自という形になっていますので、ここでは１.３９という所得割率になっているところです。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"制度の仕組みがわかるような形で説明してほしいというのが毎回国保運営協議会で出されていると思うのですけれども、ぜひしてほしいと求めました。資料と説明のことについてお願いします。","respondent":"高森国保医療年金課長","answer":"国保運営協議会の資料も変更するような動きもありますので、もう一度検討して、なるべく同じ形のものを出すように進めていきたいと考えております。先ほど来、この部分が残りの５０のところで保険者支援制度または保険料の軽減部分ということで入ってまいりまして、全体として。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２.３％減少するということでは書かれているのですけれども、これは何人から何人減ったのかというところをちょっと教えていただきたいのが１点です。","respondent":"高森国保医療年金課長","answer":"被保険者数ですが、全体の話で、２３区の話でよろしいですか。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"９８件、８６件というのは、今まで対象でなかった方が新たに対象になる世帯数ということで考えてよろしいか尋ねました。","respondent":"高森国保医療年金課長","answer":"５,１０３件だったのですけれども、これが５,２０１件、２割軽減４,６５７件が４,７４３件となります。ただ、この数字はあくまでも推定ですので、その旨ご理解いただければと思います。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうした場合に、１３億５,０００万円が１人当たりにしたらどれぐらいの値上げになるのかということを伺ったときには。予定だと思うのですけれども、その３３％というと、１７％と１６％みたいな感じに二等分するとそうなるではないか尋ねました。","respondent":"高森国保医療年金課長","answer":"一度変更していますので、おそらくそこは入れるという考え方と、かなり厳しくなるという考え方も出てるのかなと思います。それはまた改めて新たに検討するです。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"せめて協会けんぽ並みに国保の負担割合を持っていってほしいというようなことを出していますね。その辺のところはどう考えられているのか尋ねました。","respondent":"高森国保医療年金課長","answer":"やはり２３区においては、すぐに何かちょっと具合悪いなと思えばすぐお医者さんにかかれるような医療環境というのも充実しているというのも事実です。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"地方３団体代表の全国知事会、去年の１１月に緊急要望を出していますけれども、もうほとんど皆さんの認識になっているわけではないですか。そのように誰もが認める構造的な問題の解決の一助になるわけですから、ぜひそうすべきなのになぜそうしないのか。","respondent":"高森国保医療年金課長","answer":"そして残りの４分の１が区の負担ということで、一般会計に入ってあります。それは使っているといえば使っていることになるのかなと、この前さまざま考えたのですけれども、そのように考えています。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"さらに財源措置をしてほしいという要望を出して、本来であれば４,０００円の繰り下げができることになるのに、それも引き下げに使わない。７,７５１円というのは、制度も破綻というふうなことになっていくのではないかと思うのですけれども、いかがか尋ねました。","respondent":"高森国保医療年金課長","answer":"さまざまな形の医療水準が上がってきておりますので、そういう状況の中で、現在１万円という状況になってあります。医療水準が上がったことによって、さらに医療費が高額になったという状況もありますので、その辺のところもご理解いただきたいと思います。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"逆に増やしていただきたいということで、要望をします。基本的なことなのですけれども、そこのところ確認をさせてください。","respondent":"高森国保医療年金課長","answer":"３月に最終的に補正を行っている状況でございまして、保険料の関係でいけば、入っていないと考えてもらったらよろしいかと思います。入っていたらまたおかしくなってしまいますので。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうしますと、今回これで条例で決められて、この保険料と決まりましたら、それはいつどのように反映されるということなのか尋ねました。","respondent":"高森国保医療年金課長","answer":"さまざまな形で支出として、国保の会計のご説明しますと、それと同時に９月から保険料を賦課しまして３月までの間に被保険者の方から保険料いただく。最終では１１月、１２月ぐらいに実績に基づいて年度末までの見込みを出しまして、それに基づいて歳出額を調整するのです。","id":"exchange-012"},{"speaker":"松永委員","kind":"質問","question":"薬剤師もそうですけれども、その点についてお伺いします。もう１点が１２ページなのですけれども、１人当たりの医療費が上がった、これはおよそ大体どこまで上がるのかというのは計算されているのか尋ねました。","respondent":"高森国保医療年金課長","answer":"１,８７１億５,９４１万円ほどというふうに見込んでおり、平成２８年から平成２９年で３％程度増額するという見込みになっていますので、これは今。","id":"exchange-013"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"なぜ政令は、このような動きになっているのか、その理由についてお伺いしたいのが２点目です。４点目は、年齢構成は４２％が６０歳以上の前期高齢者だということで、勤労している方はどれぐらいかなどはわかるのか尋ねました。","respondent":"高森国保医療年金課長","answer":"均等割の率というのが微妙にずれてまいりまして過去において、平成２７年度は６０対４０とか、そのようにご理解いただければというふうに思います。","id":"exchange-014"},{"speaker":"安藤副委員長","kind":"質問","question":"そちらもお伺いします。あるべき保険料水準を議論すべき」と述べておりまして、なぜこれを、あわせてお伺いしたいと思います。","respondent":"高森国保医療年金課長","answer":"均等割が２割程度上がっていくのかなという状況でありますので、５８：４２というのを、今特別区のほうでは採用しています。保険者の財政支援ということで、それを踏まえて保険者の財政支援を行うのだということで、１,７００億円余が投入されたと聞いてあります。","id":"exchange-015"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"中心は、保険料を下げるために使わないとこの提言の趣旨には合わないのではないですかという意味でお伺いしたので、もう一度お伺いしたいと思います。そこら辺大事な点なので、実際にどのように個々のケースを把握しているのかというのをお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"安藤副委員長","kind":"質問","question":"品川区で財政的に一般財源からの投入で具体的に危機だという状況があるのかどうか、そこら辺はどうなのでしょうか。私はしっかりと保険料を下げるためにこのお金は充てるべきだと思いますけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"委員が自由に発言をし、質問もできるという場ですから、そういう形で抑えるというやり方はちょっと。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"去年の平成２８年の１２月２６日に、区長会で、国保について、先ほども課長からありました特別区の緊急要望が出されています。２０１８年度予算からとなって、そして品川区では、このペナルティというところはどういう状況になっているのかということもの説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"渡部委員長","kind":"質問","question":"２点目に区の一般財源の投入の話ですけれども、それに対して答弁いただけないと判断して進めておりますので、ご了承ください。答弁お願いします。","respondent":"高森国保医療年金課長","answer":"そのうちの３つ目に「子育て世帯の経済的負担の軽減のため、出てあります。子育て支援の関係の課で、いわゆる国の方針とはずれているという形で、確かそういう話になっているかと思います。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで、そこのところのペナルティで出されているのが、品川区ではどの程度なのかということについて、先ほどお聞きしましたのでご答弁お願いいたします。","respondent":"高森国保医療年金課長","answer":"申し訳ございません。私のほうでは、今その資料を持ちあわせてございません。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ求めていただきたいのと、子育て世代にとっては、特に国保が大変だという。そういうふうな制度を検討すべきなのではないかなと思うのですけれども、そういう制度の検討というところでは出ていないのか、の説明を求めました。","respondent":"高森国保医療年金課長","answer":"いわゆる大人も子どもも均等割については同額だという形になっていますから、そこが変わらなければなりません。２３区だけでそういう形のことを、さまざまな形での指導が入ると認識していますので、現状ではそれについてはできないです。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やはり、区民の実態というのを、一番つかんでいらっしゃるのは、地方自治体である品川区です。多子世帯の減免というのは、ぜひともそういう制度を要望として上げていただきたいなと思うのですが、いかがか尋ねました。","respondent":"高森国保医療年金課長","answer":"先ほど、特別区長会で出ているということで、やはり子育て世代の負担軽減ということが、厚生労働省のほうに出ていますので、こういうことは必要に応じて、また進めていきたいと考えています。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"確認させていただきたいのが、滞納繰越分の収納率、滞納繰越分収納の伸び率です。この報奨金は１億を大きく超えるかなという思いがしているのですけれども、例えば平成２７年の収納率が８９.３６％でいいのか尋ねました。","respondent":"高森国保医療年金課長","answer":"そのとおりです。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"多分平成２６年が８７.１９％で、平成２７年が８９.３６％ということで、その点を確認だけさせていだきたい。平成２６年が４０.３２％なので、１０.５８％ということでいいのか、そのことの確認だけさせてください。","respondent":"高森国保医療年金課長","answer":"そのとおりです。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"滞納繰越分の伸び率で２,０００万円。１億６,５００万円が取組み別成績交付算定表からもとめられる交付額になるのではないかなと思うのですけれどもいかがか尋ねました。","respondent":"高森国保医療年金課長","answer":"それと、差し押さえ割合に対する交付というのが３００万円ありますから、平成２８年度の交付見込み額につきまして１億６,８００万円です。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"わかりました。改めて１億６,８００万円ということで確認をさせていただいていいでしょうかということで、確認です、お願いします。","respondent":"高森国保医療年金課長","answer":"本会議の質問のときには確定通知が来ておりませんでしたので、お知らせすることはできなかったという状況です。現在は確定通知が来てあります。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"もう限界に来ているということが、３首長会の中でも確認されているにもかかわらず、さらに大幅な値上げになったということ。本当にこの苛酷な取り立てと、それから高い保険料の条例ですので、反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/999880?Template=document&Id=3472#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":26559,"voices":82}},{"id":"h29-20170322-3","meetingId":"h29-c-budget","date":"2017年3月22日","dateIso":"2017-03-22","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を122件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"このように、１,０００時間を超える職員の方もいらっしゃる事実、また多忙やストレスが理由で病気休暇・休職となる方もいると伺っています。区職員で年間残業時間が８００時間、１,０００時間を超えている方は、それぞれどれぐらい、何人ぐらいいらっしゃるか尋ねました。","respondent":"田村総務部長","answer":"款別でもお答えしたように、高齢者の地域支援で施設開設等あったこと、あるいは選挙管理委員会は急な都知事選等の対応があったということで。総数とすると、大体、先ほどの数が１％程度、１００人に１人ぐらいの勘定ということになります。","id":"exchange-001"},{"speaker":"渡部委員","kind":"確認","question":"状況を確認させていただいて、１,０００時間のほかにもそれに近い方々もいらっしゃると思うのですけれど、この先述べします。ここ５年間のこれらの推移をお示しいただくとともに、低下に至った背景と要因がありましたらの説明を求めました。","respondent":"田村総務部長","answer":"学校警備の委託あるいは住民情報のオンライン化、戸籍事務の電算化等を実施してきて、工夫した上で人件費率を下げてきたです。今後は、やはりオリンピックや児童相談所の設置等も勘案して考えていく必要があるだろうと考えております。","id":"exchange-002"},{"speaker":"渡部委員","kind":"質問","question":"さまざまなお話を伺えています。具体的なところでは、夜間町会長会議や火曜延長開庁時などで出勤時間の調節などは可能なのではないか尋ねました。","respondent":"田村総務部長","answer":"常時何かあるかというと、ない月もあるということですから、やはりその辺は弾力的にさまざまな方策を含めて検討してまいりたいと考えております。","id":"exchange-003","title":"町会・自治会支援"},{"speaker":"渡部委員","kind":"意見","question":"区職員の皆様が、仕事にやりがいと生きがいを感じて幸福感をお持ちいただかなければ、区民を幸せにすることはできません。最後に、本区におけるこれからの働き方改革に取り組まれる区のご決意の説明を求めました。","respondent":"田村総務部長","answer":"ですから、職員自体が、やる気なり、仕事に対する生きがいを感じないと、やはり区民サービスにも反映できないだろうと考えております。","id":"exchange-004"},{"speaker":"渡部委員","kind":"質問","question":"次に、子育て支援について伺います。平成２２年度から本年度までの、幼齢人口の推移、待機児童数の推移、待機児童解消に向けた施設建設などの区の取組み、予算の変遷をお知らせください。","respondent":"齋藤子ども未来部長","answer":"平成２２年以降の乳幼児人口の推移についてご説明申し上げます。１３４億円、１５５億円、来年度予算は２０７億円を予定しております。","id":"exchange-005"},{"speaker":"渡部委員","kind":"質問・要望","question":"予算を今、伺いました。そして、また中途開設園への申し込みなどを丁寧に行っていただきたいと考えていますが、あわせてさらなる取組みについてもの説明を求めました。","respondent":"齋藤子ども未来部長","answer":"およそ４００人の方が入所見込みですが、およそ２００人の予算枠を設けておりますが、保育料の助成をする仕組みを設定していること。さわやかサービスなど、さまざまな仕組みがありますので、こういったことについても丁寧にご説明しています。","id":"exchange-006"},{"speaker":"渡部委員","kind":"質問・要望","question":"親育ちの支援等について伺っていきますが、職員派遣を含め、準備が進められていることと承知しています。これにつきましては、さまざまな場面で会派からも要望しています。","respondent":"齋藤子ども未来部長","answer":"あり方検討委員会の筋論から言うと、一歩でも進めたいということで、品川区をはじめ２２区はこれに応じたところです。地域に根差した児童相談所を設置することが本来のあり方でもありますので、品川区らしい、これからも整備に向けて取り組んでまいります。","id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"続きまして、児童センター等について伺いますが、品川区の児童センターは、０歳から１８歳までの間、地域の子育てや活動を支えていただいています。子どもたちに幼少期、どのように接していらっしゃるのか尋ねました。","respondent":"齋藤子ども未来部長","answer":"平成２０年当時から、父親の子育て参加促進事業、プレママ・プチママタウンといった事業を進めてまいりました。児童センター育ちのお子さんが、また児童センターで次の世代の育成を担う、こういった好循環となるよう、これからも取組みを進めてまいります。","id":"exchange-008"},{"speaker":"渡部委員","kind":"質問・要望","question":"２５館ある児童センターが、さらに地域の子育て拠点となるよう、お願いを込めて要望し、次の質問に入らせていただきます。今の話からも見てとれますが、最終的に社会に出てから苦労しない人となるには、より実践的な教育が必要なのではないか尋ねました。","respondent":"本城教育次長","answer":"いわゆる自己管理領域等の５領域、そして１５の能力を整理しまして、９年間の一貫した教育の中で身につけるために取り組んできたところです。９年間の一貫した教育の強みを活かしまして、授業のあり方の研究・工夫を深め、広げていきたいと考えているところです。","id":"exchange-009"},{"speaker":"渡部委員","kind":"質問","question":"これから小中一貫の質問を続けしますが、次に学習指導要領について伺います。今回の改訂のポイントをお示しいただくとともに、区の今後の改訂について伺います。","respondent":"本城教育次長","answer":"そのような学習指導要領の内容を踏まえまして、それに品川区のよさ、品川区独自の品川区立の学校教育要領を策定していくことを考えているところです。","id":"exchange-010"},{"speaker":"渡部委員","kind":"質問・要望","question":"改めて伺います。やはり、今後、他の中学校においても勉強合宿を進めるべきと考えますが、いかがでしょうか、伺います。","respondent":"本城教育次長","answer":"今後といたしましては、義務教育学校以外の他の中学校の実施についても、より支援していきたいと考えているところです。そういうことを含めて支援のあり方をこれから検討していく必要があると考えているところです。","id":"exchange-011"},{"speaker":"渡部委員","kind":"確認","question":"さまざまな、今のお話を伺いますと、これからしっかりと進めていただけると確認させていただきました。非常勤として、これらの時間等の取扱いはどのようになっているのでしょうか、現況の説明を求めました。","respondent":"本城教育次長","answer":"平成２８年度は、１５校で実施したところですが、複数校で合わせて実施したコミュニティ・スクールにおきましては。月８回・１日６時間、３年間の計画配置を考えている中で、今後の検討課題の一つであるとは考えているところです。","id":"exchange-012"},{"speaker":"渡部委員","kind":"質問・要望","question":"問題点と課題もこれから多々出てくることと思いますので、ぜひ現場で活躍されている方々からさまざまなお話を伺って。さらなる品川区の教育の発展と小中一貫教育の充実を、これからもますます求めてまいりますが、最後に教育委員会としての意気込みの説明を求めました。","respondent":"中島教育長","answer":"今年度刊行いたしました「品川の教育」という冊子をめくりますと、地域の熱い思いと支援にいっぱい支えられて今があると考えることができます。","id":"exchange-013"},{"speaker":"渡部委員","kind":"質問","question":"続きまして、高齢者福祉について伺っていきます。ここで、誰でもなり得る認知症への取組みについて伺います。","respondent":"榎本福祉部長","answer":"配布の対象と時期ですけれども、まず、４月１０日には、区ホームページへ掲載する予定です。その後、６月には、６５歳以上の方のいる全世帯に配布する予定です。","id":"exchange-014"},{"speaker":"渡部委員","kind":"質問・要望","question":"６５歳以上の方々には全戸配布することは伺いました。この理解というものを促すためにしっかりと取り組んでほしいと思うのですが、６５歳未満の方に知らせていただくのか、お答えをお願いいたします。","respondent":"榎本福祉部長","answer":"ケーブルテレビの番組の「しながわほっとインフォメーション」で、６月には「品川くるみ認知症ガイド」についての放送を予定しております。そのほか、各種イベント等を活用して、若年層や地域の方々への周知を図っていきたいと考えております。","id":"exchange-015"},{"speaker":"渡部委員","kind":"確認","question":"高齢者クラブについて１点確認させてください。これらの活動に対してきめ細かい支援を行っていると思いますが、活動にあたっての保険はどのようになっていますでしょうか、の説明を求めました。","respondent":"榎本福祉部長","answer":"高齢者クラブは１１４クラブありまして、全国老人クラブ連合会が推奨しております会員向けの傷害保険、賠償責任保険等があります。直接、高齢者クラブの担当の方から、事故が起こった場合には手続をしていただくという形になっております。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問・要望","question":"次に町会支援について伺います。加入促進に向けて、区として可能な限り支援を要望いたしますが、お考えの説明を求めました。","respondent":"堀越地域振興部長","answer":"制定後１年の町会・自治会の皆様からの反応についてですが、皆様からは、「加入の勧誘の際に町会・自治会について説明しやすくなった」。加えて、管理組合に対しましては、今後も積極的に周知に努めてまいりたいと考えているところです。","id":"exchange-017"},{"speaker":"渡部委員","kind":"質問・要望","question":"地域連絡調整員のほうも機能しているとも伺っておりますので、引き続き支援をお願いいたします。さまざまな活動を行っている町会ですが、款別審査でも伺ってまいりましたが、町会活動における、ふれあい保険が新年度から変更になると聞きました。","respondent":"堀越地域振興部長","answer":"このような形で、活動のさらなる活性化、町会・自治会の担い手確保にもつなげていただければと考えています。それから、周知につきましては、町会長会議等で、地域センターを通じて積極的に周知を図ってまいりたいと考えているところです。","id":"exchange-018","title":"町会・自治会支援"},{"speaker":"渡部委員","kind":"質問・要望","question":"東芝病院は救急指定で３０８床ある総合病院であることは承知しています。同等の施策を受けられる他医療機関はあるのでしょうか、の説明を求めました。","respondent":"西田健康推進部長","answer":"実施しており、昨年開始したばかりではありますが、産後ケア事業宿泊型も実施しております。高齢者施策でも、医療ショートステイ事業を平成２４年４月から実施しております。","id":"exchange-019"},{"speaker":"渡部委員","kind":"質問・要望","question":"全会派統一見解として、本年の２月６日に大沢区議会議長名で東芝社長宛てに、東芝病院存続に関する要望書を提出いたしました。行われるのであれば、どのような支援策が考えられるのか、答えるよう求めました。","respondent":"西田健康推進部長","answer":"現時点でも東芝本社が東芝病院の売却を検討しているという情報は報道のみであり、東芝本社からは正式な発表はなされてございません。区としての支援策につきましては、状況に応じてさまざまなケースが考えられますので、現在お示しする状況にはないと認識しております。","id":"exchange-020"},{"speaker":"渡部委員","kind":"質問","question":"以上で私の質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問","question":"シティプロモーションについて伺います。まずお伺いしたいのと、ここには力を入れたというところを、まず初めにお聞きしたいと思います。","respondent":"濱野区長、中山企画部長","answer":"そのことがシティプロモーションを通してシビックプライドにつながっていくのだろうと考えています。予算については担当の部長よりお答えをします。あるいは動画の作成もやってまいりますけれども、こういう中で、区民の参加、力を得ながらやっていく。こういう方法の中でも、今のシビックプライドにつなげるプロモーション活動というものは可能と考えています。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"意見","question":"区のほうで発信する側、デザインする側、その辺をどうお考えなのか。今言った、行政主体のシティプロモーションから、それについてのお考えもの説明を求めました。","respondent":"濱野区長","answer":"品川区というところが東海道の第一宿だったということを周りに発信していくという意味で、非常に区をアピールする、よいお祭りだと考えています。","id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問","question":"ですから、先ほど、しろへびサミットも１つです。区がやはりそこは仕掛けていくべきだろうと思っておりまして、私は非常に大切だと思っておりまして、改めてそこの考え方を伺いたいと思います。","respondent":"濱野区長","answer":"直感的に自分たちのまちのよさを捉えて、あるいはよその区の人との会話の中でＰＲしてくれているのだということをすごく感じたことがあります。","id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もう、シティプロモーション担当が全てわかっていて、こういうことはこうやって、全部、指示していくのだぐらいの行政の体制があってほしい。","respondent":"濱野区長","answer":"そういう横串を通して連結ピンをつくって、そして前へ進めるような組織として機能していくように指導していきたいと思っているところであります。これからもさまざまに展開してまいりますので、ご理解をいただければありがたいと思います。","id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"質問","question":"次は、広町再開発と庁舎建替えについて伺いたいと思います。６,０００万円の中身についてまずお伺いしたいのと、改めて互いに検討する上でのスケジュール感を区はどういうふうに考えているのか。","respondent":"藤田都市環境部長","answer":"それから区が単独で検討する部分の２つがございまして、この検討を両方進める経費として、６,０００万円を見込んでいるものです。大井町駅周辺地域と連携した複合市街地を形成する拠点として、土地利用の転換を図るエリア、こうしたものとして位置づけているものです。","id":"exchange-026"},{"speaker":"石田（秀）委員","kind":"質問","question":"品川の新駅は２０２０年までというのが発表されていて、２１年、２２年ぐらいまでになるかもしれないという話があります。改めてそこだけ、スケジュール感と決意というのか、その辺をもう一回お聞きしたいと思います。","respondent":"藤田都市環境部長","answer":"そういった面では、やはり今までの交渉とは違うのかと考えています。区とＪＲ、両者にとってよりよいまちづくりの計画になるよう、しっかりと進めてまいりたいと考えています。","id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"その前に１つ、ＪＲ東日本も独自に考えを持っているということもお聞きしますが、ともに情報を早目に出していただきたい。そういうことを含めるなら、豊島区方式も１つ検討の視野に入ってくると思いますが、その辺のところもあわせてお考えの説明を求めました。","respondent":"藤田都市環境部長","answer":"こういった部分についても、どういった形でやるのが最適なのか、こちらについてはしっかり検討していきたいと考えています。どのように進めるのが有効な手立てなのかといったことについて、十分に、区の考え方をしっかりと持って進めていきたいと考えています。","id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうなってくると、あとはさまざまな方法を考えると、今回、平成２９年度予算では、約４億円かけて第二庁舎の熱源機器の改修を行う。","respondent":"藤田都市環境部長","answer":"現在、広町地区の検討の中でも、一定の検討が進んだ段階で、今後、高架下の活用も含めた東急との調整が必要であると考えています。建替えまでは一定の年数がありますので、その間も必要な施設として、適切な維持管理に努めてまいりたいと考えています。","id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それは再度、再開発の網のかけ方というのは区でもやれるわけですから、その辺のところの考えをお聞きしたいと思います。この辺の異なってくるところを、どうやってこれから整理していくというお考えなのかも、お聞きしたいと思います。","respondent":"藤田都市環境部長、本城教育次長、中山企画部長","answer":"来年度予算、平成２９年度予算には、西品川一丁目におきまして木密連坦地域のまちづくりのあり方等についても検討していく予定になってあります。どうしても高温多湿ということになって、運動等の環境の中では、なかなか厳しい面もどうしても生じていると考えているところではあります。それに伴うキャンセルですけれども、なかなか免除団体からキャンセル料は、料金から返すという考え方なので、現実難しい。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私はもちろんやっていただきたいと考えていますし、電気代相当分は徴収するとか、応益負担の考え方。そういう減免団体、特に免除団体のあり方も含めて、この中で私はやっていくべきだと考えていますが、その考えの説明を求めました。","respondent":"本城教育次長、中山企画部長","answer":"体育館の建物の構造上の問題といたしまして、後づけで機器を設置すると、どうしても建物に負荷がかかって、耐震上の課題がある。そのような中で、現状では冷暖房がつけられていない状況があるというのが現状ではあります。先ほどの繰り返しになりますけれども、それぞれの料金設定あるいは減免については、一定の政策的目的との兼ね合いというものもあります。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"そして施行規則の改正を受けて、改めてどのような計画をお考えか、お聞かせください。８割ぐらいだと考えていますけれども、それをお聞きしたいのと、改めてお聞きしたいと思います。","respondent":"本城教育次長","answer":"そして、基本的な部活の加入率ですけれども、運動部と文化部、合わせて８９％の加入率に今なっているところであります。運動部が５９％、文化部は３０％の加入率です。","id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"提案","question":"最後の質問になると思いますが、コミュニティ・スクールも始まります。その中で、やはりそこは教育委員会がさまざまな形で提案して、その決意を最後にお聞きして質問を終わりたいと思いますとの意見を述べました。","respondent":"本城教育次長","answer":"そういった背景、意義を持つ部活動については、１つは指導力等向上によって、部活の質的向上を図ること。地域との交流の中で指導者を得ることができれば、学校の質の向上とあわせて、そういう観点から推進していきたいと考えているところです。","id":"exchange-033"},{"speaker":"あくつ委員","kind":"提案","question":"これは、都議会公明党が昨年の議会質問で提案し、１２月には小池都知事に直接要望した政策が反映されたものです。教育委員会として、子どもたちにとって学校トイレをどのような施設として捉えているのか、また洋式化することについて、どうお考えか伺いますとの意見を述べました。","respondent":"本城教育次長","answer":"その上で、洋式の考え方ですが、現在、原則として洋式化を進めていく考え方ではあります。毎年４校程度、平均で言うと、費用約２億円ぐらいの予算を使ってトイレの改修にあたっているところです。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"提案","question":"文部科学省への回答のとおり、品川区は今後、学校トイレを９０％以上、洋式化していく方針であるということを確認しますが、お考えを伺います。今後の改築の際にもさらに活用していただきたいと考えますが、いかがか尋ねました。","respondent":"本城教育次長","answer":"主に学校の新築や改築の場合のトイレの整備に対する教育委員会での方針といたしまして、おおむね洋便器を設置すると回答したところです。今後もそのような取組みを継続していきたいと考えているところです。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問・要望","question":"本年の２月２０日には濱野区長に対しまして、区立学校や公衆・公園のトイレの洋式化を強く要望したところですので、早急な洋式化をお願いいたします。質問の２点目は、公衆トイレ・公園トイレについて伺います。","respondent":"本城教育次長、松代防災まちづくり部長","answer":"おおむね洋便器を設置するということの中で、その中での回答ですので、目標を達成するように努めていきたいと考えているところです。平成２９年度より実施します、オリンピック会場の周辺に移設されている１５カ所に、だれでもトイレや洋式化等の整備を重点的に実施してまいります。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問","question":"質問の３点目は、女性にとって使いやすいトイレについて伺います。女性の目線での区内のトイレの使いやすさ・衛生面・安全面の工夫について、イメージアップが必要と考えますが、ご見解を伺います。","respondent":"松代防災まちづくり部長","answer":"これまでに、いたずらや誤作動による対応がありましたが、トイレでの事件・事故は起こっておりません。広報紙や、さまざまな機会を捉えまして、イメージアップにしっかりと取り組んでまいります。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問","question":"地方からの２０代、３０代の、低所得の若年層の流入がどの程度あるのかお知らせください。その意味で、国の提唱する地域共生社会を今後構築していく必要性についてご所見を伺います。","respondent":"中山企画部長、榎本福祉部長","answer":"したがって、今後１０年間は人口増を見込んでおります。所得については現段階において分析しておりませんけれども、いわゆる若年層ということでありますから、いわゆる高額所得者は少ないと考えております。委員がおっしゃったとおり、地域住民や地域の多様な主体が参画し、分野を超えてつながるという、地域共生社会の考え方は必要であると考えています。","id":"exchange-038"},{"speaker":"あくつ委員","kind":"確認","question":"双方が我がこととして、今後来るべき地域共生社会の構築であるという意識改革の工夫が必要と考えますが、いかがでしょうか。いずれにせよ、コーディネーター機能を、人数も含め、大幅に強化する必要性があると考えますが、ご見解を伺います。","respondent":"榎本福祉部長","answer":"支援員の世代を次につなげていくことも課題であると認識しております。この地域支援員を増やすのはなかなか難しいところですけれども、理解と参加を促していきたいと考えています。","id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問・要望","question":"助成によってその内容が大幅に制限されることのないよう確認いたしますが、いかがでしょうか。認知症の人がアクセスしやすいよう、できるだけ偏りのない認知症カフェの全区展開を働きかけてほしいと求めましたが、いかがか尋ねました。","respondent":"榎本福祉部長","answer":"相談支援包括化推進員のことですけれども、都からの制度を使っているほうが有利ですので、そちらでいく予定です。それから、全区展開ということですけれども、助成金の制度化によって、地域ごとでの設置を促していきたいと考えております。","id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"こども食堂や認知症カフェなどを実施するなど、地域貢献事業の展開を促してほしいと求めましたが、いかがでしょうか。施設側にはできるだけ同性介護を行い、区内全ての高齢者施設にどのように改善策をとられるのか、今後の具体的な対応を伺います。","respondent":"榎本福祉部長","answer":"障害児者総合支援施設では、今後の障害者の状況やニーズに対応した総合的・継続的な支援を行うことを、まず第一として考えたいと考えています。しかしながら、できるだけ家族と本人の意向を配慮しつつ、きちんと説明した上で介護にあたっていきたいと考えています。","id":"exchange-041"},{"speaker":"あくつ委員","kind":"質問・要望","question":"款別審査でのご答弁と異なっているのでもう一回お伺いいたしますけれども、たしか、そこのところをもう一度お伺いしたいと思います。","respondent":"榎本福祉部長","answer":"同性介護の部分についてですけれども、できる限り、きちんと、家族と本人の意向を配慮しつつ、それに努めていきたいという形です。まずは本来の役割を第一義的に進めさせていただきまして、さまざまな先駆的事業についても検討していきたいと考えています。","id":"exchange-042"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そこで、生活調査の結果と分析、今後の方針を議会にお示しほしいと求めましたが、いかがでしょうか。子どもの未来を応援する姿勢を明確に品川区が示すことは、根拠も意義もあることと思いますが、ご見解を伺います。","respondent":"齋藤子ども未来部長","answer":"新年度におきましては、こども食堂、学習支援の事業もありますので、進行管理も含めて文教委員会等にご報告したいと考えています。国の子ども・若者育成支援推進大綱の中でも、子どもの貧困問題への対応ということは、計画を策定してまいります。","id":"exchange-043"},{"speaker":"あくつ委員","kind":"質問・要望","question":"さらなるインクルーシブ教育、人権教育の進化が求められると思いますが、教育委員会のお考えを伺います。子どもたちにアール・ブリュット展の鑑賞機会の創出を求めますが、そして教育委員会、それぞれのご見解を伺います。","respondent":"本城教育次長、榎本福祉部長、中島教育長","answer":"来年度、観賞を予定している学校もあるところです。しながわ夢さん橋という事業と連携いたしまして、障害者への理解を深める一層の機会として活用していきたいと考えています。本区の市民科において、１から９年生までの全ての学年にこの人権に関する単元を設定してありまして、理解の深化に努めているところです。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１０年ぶりに改訂される新学習指導要領でも、アール・ブリュットを観賞する際には、ぜひ作品の作成過程の映像なども見てほしいと求めました。ご清聴ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"塚本委員","kind":"質問","question":"ここでは、区有施設全体の約６割が建築後３０年を経過して老朽化する中、効果的・効率的な区有施設のあり方をまとめています。当活用プランによってどのような効果が得られたのかの説明を求めました。","respondent":"中山企画部長","answer":"例えば平塚橋、これは平塚橋会館の廃止を行いながらも、新たに特別養護老人ホームとゆうゆうプラザの複合施設を設置しました。こういった事例が、１つの成果の具体例としても挙げられるものと考えております。","id":"exchange-046"},{"speaker":"塚本委員","kind":"質問","question":"区の行政需要の増加につながると認識いたしますが、人口増加ピークの延伸が品川区にもたらす影響について、品川区の見解をお聞かせください。には、どのように区民ニーズを的確に捉えるのかを踏まえて、区の公共施設の管理・運営について見解を伺います。","respondent":"中山企画部長","answer":"特に子育て関係、あるいは学校の規模等については、この人口動向を踏まえた対応をしていく必要がある施設と考えております。従前からのトレンドの対応というものを、ご質問もありました、これはサービスをしっかり維持しながら活用を考えていかなければならないです。","id":"exchange-047"},{"speaker":"塚本委員","kind":"質問・要望","question":"世論調査、さまざまな手法のご案内がありましたけれども、区民ニーズを的確に捉えた施設のあり方を確認してほしいと求めました。区民集会施設について伺います。","respondent":"中山企画部長","answer":"例えば一定の目的を限定して利用しているような施設、例えばシルバーセンターとなりますと、これは集会機能だけで言えば１５％ぐらいに下がります。","id":"exchange-048"},{"speaker":"塚本委員","kind":"質問・要望","question":"さらに、我が会派では、ひとり暮らし高齢者、ひとり親家庭、低所得者など住宅困窮者に、空き家を活用した住宅政策を求めてきました。","respondent":"藤田都市環境部長","answer":"住宅確保要配慮者へのさらなる支援のために、空き家の活用も含めた不動産関係団体などとの連携、居住支援協議会の検討などを進めていく考えです。","id":"exchange-049"},{"speaker":"塚本委員","kind":"質問・要望","question":"少子高齢化社会を迎え、区民生活の変化に即応して的確な政策決定が求められると思います。区執行部、企画部門として、現状の認識と今後の展望についての説明を求めました。","respondent":"中山企画部長","answer":"片やそのための一定の効率的な運営、あるいは役割の分析を踏まえた見直しもしながら、必要なものをしっかりやっていく。こういう観点での区民のための施設の整備をより充実させていきたい、このような計画をしていきたいと考えております。","id":"exchange-050"},{"speaker":"塚本委員","kind":"質問","question":"次に、少子化対策についてお伺いいたします。品川区として対応すべき課題について初めにお伺いするとともに、平成２７年の品川区の合計特殊出生率が１.２３となったことへの評価と。","respondent":"中山企画部長","answer":"年少者に対する対応としては、この１０年間の増というものを、ある意味ではどう乗り切っていくか検討したときに。全国平均１.４２にはまだまだ届いておりませんので、数値をさらに高めて、総合戦略に定めた数値に近づけていきたいと考えております。","id":"exchange-051"},{"speaker":"塚本委員","kind":"意見","question":"人口を維持するために必要とされている合計特殊出生率が２.０７人ですので、これを目標として間断なく少子化対策を進めるべきものと考えております。あわせて、多子計算にかかわる年齢制限という考え方がある理由についての説明を求めました。","respondent":"齋藤子ども未来部長","answer":"世帯所得制限はありますが、世帯収入１,８００万円程度を予定しておりますので、ほぼ皆様が対象となっております。環境整備や財源確保を図りつつという方針がありますので、国の動向、特定財源確保を踏まえて検討しています。","id":"exchange-052"},{"speaker":"塚本委員","kind":"質問・要望","question":"区の財政負担がどの程度になるのかということを伺うとともに、年齢制限のさらなる引き上げというものを検討しているですが、求めたいと思います。区の見解をお伺いいたします。","respondent":"齋藤子ども未来部長","answer":"１つ目は受益者負担の考えでございまして、保育料で保育の経費を賄えているのは約２０％弱です。こういった受益者負担のことと国の方針、財源ということがありますので、国の動向を注視しながら、国の動向を踏まえて拡充を検討してまいります。","id":"exchange-053"},{"speaker":"塚本委員","kind":"質問","question":"この多子軽減に関するお声は結構、最近多く伺うところがありますので、今、ご検討いただくということでしたので、よろしくお願いしたいと思います。次に、待機児童対策について伺います。","respondent":"齋藤子ども未来部長","answer":"５５１人の拡大で、ほぼ８０人ぐらいの余裕が生まれる予定でございましたが、入園希望者が増えているところです。このことで、開設準備経費を区で上乗せしておりますし、家賃助成期間も５年から１０年へと拡大を図る予定です。","id":"exchange-054"},{"speaker":"塚本委員","kind":"質問・要望","question":"こういった施設においてどうなのか、保育施設の種類などについて伺いたいと思います。さらに、平成３０年度４月入園に向けた保育定員の拡大について区の見解を伺います。","respondent":"齋藤子ども未来部長","answer":"私どもとしても、東京都の社会福祉審議会に諮られるよう、準備を進めているところです。区としても保育定員の拡大が図れるものですので、平成３０年度に向けて大きな受け皿の確保ができるよう、引き続き取り組んでまいります。","id":"exchange-055"},{"speaker":"塚本委員","kind":"質問","question":"保育士処遇に対する２３区の独自政策の現状について、品川区としてどのように考えているのかお伺いします。例えば品川区の魅力を発信するなど、そういった政策も有効ではないかと思いますが、ご見解をお伺いします。","respondent":"齋藤子ども未来部長","answer":"２３区で１１区が一定の上乗せの施策を実施する予定だということを確認しております。先ほどご説明申し上げましたが、公定価格に５０％上乗せして、区として現時点で上乗せをする考えはございません。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この願いをかなえ、安心して子育ても仕事も両立の支援をしてくださいとの内容が届いていますが、どのように受けとめたのでしょうか、伺います。保護者の子育てに関する要望をどのように受けとめているのかお伺いします。","respondent":"齋藤子ども未来部長","answer":"平成３０年以降も新規園では定員差を３人以上、設けましたので、平成３０年からは２００人の定員差が設けられる見込みです。したがいまして、認証保育所を卒園された場合、３歳児の入園はほぼ全員が可能ではないかと考えております。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"直接話を聞く機会を得たのですから、認証保育所の子どもたちの３歳の壁が、早急に改善してほしいと求めました。４月に一人の子どもも路頭に迷わせない丁寧な対応を、具体的にお伺いいたします。","respondent":"齋藤子ども未来部長","answer":"不承諾者に対する対応といたしましては、認証保育所のご利用が約４００人見込まれますので、平成２９年度からはご議決を頂戴できれば。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"深刻な事態を改善できない原因はどこにあるとお考えでしょうか、伺います。実態の把握と将来予測をどのように立てているのかお伺いいたします。","respondent":"齋藤子ども未来部長","answer":"お子様の路頭に迷うということの定義が少し承知しかねますが、そのようなことがないよう、区としても取組みを進めているところです。スキームに加えて、区独自の仕組みを複数用意しておりますので、待機児解消に向けて認可保育園の開設を誘導していきたいと考えております。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問","question":"民間の認可保育園でしょうか、今までの従来の考えで待機児ゼロになるのかどうか、そう思っていらっしゃるのかどうか伺います。潜在的需要にも拡大して考えていくべきではないかと思いますが、いかがか尋ねました。","respondent":"齋藤子ども未来部長","answer":"これは本会議でもご説明申し上げました。これは、継続的に品川区が待機児対策に取り組んできた成果、期待に対するあらわれだと理解しております。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いかがでしょうか。入園内定者が増えなかったのはなぜなのか、この理由もお伺いします。","respondent":"齋藤子ども未来部長","answer":"平成２２年の待機児という言葉が本格化して以来、約３倍近い財源を投入させていただいて、定員拡大に努めてまいりました。引き続き、議会と一体となりながら、待機児対策に取り組んでまいりたい。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"待機児ゼロ実現のため、品川区がみずから公設・公営保育園を増設することを求めますが、いかがでしょうか。民営化はやめるべきですが、いかがか尋ねました。","respondent":"齋藤子ども未来部長","answer":"あわせて、私立保育園の方は不動産会社の方などと上手に連携しながら、さまざまな働きかけをして認可保育園の整備を進めていらっしゃいます。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ総合対策に公立保育園建設を入れていただきたい。保育園をつくることが大きな経済的効果を生み出すと考えていますが、この点はいかがか尋ねました。","respondent":"齋藤子ども未来部長","answer":"来年度の１２園の開設につきましても、私ども保育課の職員は、本当に血のにじむような努力をし、進めてまいりました。やはり継続的に財源を確保し、待機児対策に対して大変効率的な進め方をするには、現在の手法が正しいものと考えております。","id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問・要望","question":"全国福祉保育労働組合からは陳情が出ておりまして、ぜひ今の窮状を救うために、区独自の月１万円賃金加算の支援を求めていますが、どうか尋ねました。","respondent":"齋藤子ども未来部長","answer":"実施設計、住民対応をする、スピーディーに待機児対策ができるです。国・都の補助金が予定されておりますので、改善されない保育園、保育事業者は保育士を獲得できないです。","id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ずっと賃金のことでされていたのですけれども、今日私が示しましたこの差をどう受けとめていらっしゃるのか、もう一回お伺いしたいと思います。ぜひ区民参加、住民参加で、福祉を取り戻す区政の転換を求めますけれども、いかがか尋ねました。","respondent":"齋藤子ども未来部長","answer":"私立保育園の区の支援ですが、先ほど、ほかの委員にご説明申し上げましたが、品川区は公定価格に５０％上乗せして負担金として交付しております。これから国や都が力強く支援してくれる処遇改善の仕組み、スキームを使って、これを強く発信してまいりたいと考えています。","id":"exchange-065"},{"speaker":"飯沼委員","kind":"提案","question":"最後に、今予算特別委員会、民生費質疑の中で、齋藤子ども未来部長の発言について、この場で改めて取消しを求めたいと思います。区民の福祉増進のために区政をチェックし提案を行う予算審議を、議会を冒涜するもので取消しを求めますが、お答えくださいとの意見を述べました。","respondent":"齋藤子ども未来部長","answer":"私がその発言を取り消してしまうと、私立保育園の事業者、働く皆さんの思いを伝えることができません。したがいまして、私は取り消す考えはございません。","id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問","question":"区民の皆さんが、きっとこの発言を聞いて判断されると思います。私は断固抗議をして質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"南委員","kind":"質問・要望","question":"飯沼雅子委員に続き、羽田新ルート計画の撤回を求め、質問します。低空飛行の羽田新ルート計画を区民はどう考えているのかなど、つかむべきではないでしょうか、いかがか尋ねました。","respondent":"藤田都市環境部長","answer":"フェーズ１あるいはフェーズ２における説明会、今年に入りまして２月１１日に開催した説明会にもつながっているところです。国として、こうした中で２８０余りの意見というものを認識しておりまして、この中には期待も、不安の声もあるところです。","id":"exchange-068"},{"speaker":"南委員","kind":"質問","question":"改めて伺いますから答弁してください。改めて伺いますが、墜落や落下物をゼロにできると思っていますか、伺います。","respondent":"藤田都市環境部長","answer":"国としても２８０余りの意見といったものを認識してございまして、期待も、不安の声もあります。努めているところですので、それに努めていただくということを、国に求めているところです。","id":"exchange-069"},{"speaker":"南委員","kind":"質問・要望","question":"区民はゼロにできなければだめだと言っているのですから、国に「飛ばすな」と言うべきです。いかがか尋ねました。","respondent":"藤田都市環境部長","answer":"国が努めているところですので、これをしっかりやるよう、区として求めているところです。落下物等についても、今ご答弁申し上げたとおりと同じようなことで、国としてしっかり対応してもらうことが大切であると考えています。","id":"exchange-070"},{"speaker":"南委員","kind":"確認","question":"今までの区の姿勢と違う答弁なので確認したいと思っての質問です。品川区の上空を低空で飛行することを、区は認めたのかどうか伺います。","respondent":"藤田都市環境部長","answer":"今進めております羽田空港の機能強化に対する私どもの考え方ですけれども、進めているところにつきましては、一定の理解はする。そういった意味で発言したものです。","id":"exchange-071"},{"speaker":"南委員","kind":"確認","question":"ということは、品川区の上空を低空で飛行することは、今までと同じという立場で捉えているということなのですか。確認したいと思います。","respondent":"藤田都市環境部長","answer":"区として、これまでの姿勢は変わるものではございません。","id":"exchange-072"},{"speaker":"南委員","kind":"質問・要望","question":"変わるものではないということ、答弁を繰り返しましたけれども、品川区上空を低空飛行で飛ぶことは了解していないという態度でいいということですか。今までと同じ立場なら、はっきりと訂正してほしいと求めました。","respondent":"藤田都市環境部長","answer":"そのことについて国としてしっかりと具体的な策を示してほしいということを申し上げているものです。これについては、これまでと同じ姿勢で現在も臨んでいるところです。","id":"exchange-073"},{"speaker":"南委員","kind":"質問・要望","question":"第４回首都圏空港機能強化の具体化に向けた協議会で、関係自治体からの要望や住民意見等も踏まえ、配慮した方策であると評価して。議会と同じ立場に立つよう、改めて求めますけれども、いかがか尋ねました。","respondent":"藤田都市環境部長","answer":"その対策、環境影響に配慮した方策について具体的に区民に説明すること、多様な手法について工夫をすることというような形で書かれてあります。８月９日には、まだまだ具体的ではないと考えていますので、引き続き国に具体的に示すように求めているところです。","id":"exchange-074"},{"speaker":"南委員","kind":"質問・要望","question":"これについては具体的でないので、不安払拭を引き続き求めるというご答弁でした。改めて確認したいのですけれども、８月９日に出されたものについては、区としても議会と同じように危惧している。","respondent":"藤田都市環境部長","answer":"私どもが捉えておりますのは、意見書の中にあります記書き以降の部分、これらについてしっかり議会のほうと連携しながら進めていくべきと考えています。","id":"exchange-075"},{"speaker":"南委員","kind":"質問・要望","question":"なぜ連絡会は一度も開かれなかったのでしょうか、伺います。要請しなかったのであれば、しなかった理由は何かも伺います。","respondent":"藤田都市環境部長","answer":"幹事会も同様ですけれども、その会の性格上、幹事会での事務的な打ち合わせが有効的な手段であるのかと考えています。担当部長には私のほうから、先ほど申したとおり、幹事会での事務的な打ち合わせが有効であるというようなお話をいただいたところです。","id":"exchange-076"},{"speaker":"南委員","kind":"質問","question":"開きなさいと要請したのかどうかの答弁はありませんでした。部長が言ったということだけですけれども、その点について、もう一度伺います。","respondent":"藤田都市環境部長","answer":"この会ですけれども、品川区としても、この会の機会を捉えまして、東京都には、区として国に伝えるべき意見、要望等については伝えてきてあります。品川区独自の要望等については、やはり直接、国に伝えるのがいいのかと考えているところです。","id":"exchange-077"},{"speaker":"南委員","kind":"質問","question":"万が一にでも墜落したらどうなるのですか。その辺についての連絡会の認識を改めて伺いたいと思います。","respondent":"藤田都市環境部長","answer":"その場の中では、やはり状況がさまざま異なることから共通認識になかなかなりにくい部分もありますので、国に直接伝えていく。こうした手法と組み合わせながら進めてやっていくということが、一番いい方法だと考えています。","id":"exchange-078"},{"speaker":"南委員","kind":"質問・要望","question":"いかがでしょうか。そして、そこで区として、８割の区民が反対している状況をつかんだ上ですから、反対するよう求めたいと思いますが、いかがか尋ねました。","respondent":"藤田都市環境部長","answer":"新飛行ルート案のうち、全体の４割ほどの南風の着陸ルート案についてですけれども、運用につきましても１５時から１９時までの間に限定するものです。いまだ十分とは言えないと考えていますので、今、重要なことであると考えています。","id":"exchange-079"},{"speaker":"南委員","kind":"意見","question":"私は、改めて、区が勇気を持って、国に区民意思を伝えるべきだと思います。ありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-080"},{"speaker":"いながわ委員","kind":"質問・要望","question":"団体になれば経費もかさみますので、団体への助成額の増額をお考えいただきたいのですが、本区のご所見をお伺いしたいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"そして、個人では平成２８年度については１万円、それから団体については５,０００円掛ける人数分というような形で支援してまいりました。そのような形でジュニアスポーツアスリートの支援をしていこうと考えています。","id":"exchange-081"},{"speaker":"いながわ委員","kind":"質問・要望","question":"時を過ぎるごとに１回、見直しをしていただいて、助成額の増額もお考えほしいと求めました。今後の事業展開をどのようにお考えなのか、本区のご所見をお伺いしたいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"そのような形でもって、日本体育大学の専門的な持っている能力をかりて、品川区民にスポーツの機運醸成を努めているところです。体験授業をする中で、区民の皆さんのスポーツの向上を図り、また感動と勇気を与えられればと考えています。","id":"exchange-082"},{"speaker":"いながわ委員","kind":"提案","question":"これは提案です。来年度というか、再来年度になるかもしれませんが、しっかり連携をとってほしいと求めましたが、いかがか尋ねました。","respondent":"安藤文化スポーツ振興部長","answer":"そして、実際に子どもたちにメダリストなどの練習風景を見てもらって、また交流もさせていただきました。そのような形で、実際の実技にかかわるスポーツ教室もはじめ、そのような体験授業も含めまして、今後とも事業展開をしていきたいと考えています。","id":"exchange-083"},{"speaker":"いながわ委員","kind":"質問","question":"１年がたつ現在、事例や国の動きなどに鑑みて、何らかの手法は研究されたのでしょうか。国家戦略特区における民泊の指定は、結果として、大阪府とお隣の大田区のみであったことに対して、品川区としてはどのようにお考えかお伺いします。","respondent":"中山企画部長","answer":"この検討が始まったということで、この動きを研究・注視しながら、比較衡量しながら考えているというふうな状況です。いわゆる民泊新法の検討が始まったために、検討に入ったということで、このように認識しているものです。","id":"exchange-084"},{"speaker":"いながわ委員","kind":"質問","question":"今、部長がおっしゃったように、３月１０日に住宅宿泊事業法案が閣議決定され、特区とは異なり、日本全国でそれが解禁されると報道がありました。本区のご見解というか、今後の予定をどう思われているのか、ご答弁をお願いします。","respondent":"中山企画部長","answer":"条例制定に向けての必要性というものを認識しておりますが、実は法案ですと、これは東京都の事務について保健所設置市が行う場合には。","id":"exchange-085"},{"speaker":"いながわ委員","kind":"質問","question":"あえて数字はお伺いしませんが、本区の宿泊施設の現状、これで今後の国内外の来訪者を受け入れる体制ができているのか。これは単刀直入にイエスかノーかになってしまうかもしれませんが、わかる範囲でお伺いします。","respondent":"中山企画部長","answer":"稼働率が上がっているという状況で、直近の平成２７年のデータですと、もう９０％を超えているという状況になります。これからオリンピック・パラリンピックと迎えることを考えますと、いわゆる宿泊施設の不足というものが懸念されるという認識を持っております。","id":"exchange-086"},{"speaker":"いながわ委員","kind":"質問・要望","question":"品川区内のあるホテルも、宴会場を潰して全部客室にしてしまったという事例もあります。本多委員長からも質問がありましたホテル誘致など、課題解決に取り組んでほしいと求めましたが、何かあればお願いします。","respondent":"中山企画部長","answer":"宿泊施設の不足というのは、品川区を訪れる方への制約にもなるということで、これについては、さまざまな手法、民間の力を誘致するような働きを含めて、区としてもしっかり、できることをやっていきたいと考えております。","id":"exchange-087"},{"speaker":"いながわ委員","kind":"質問","question":"これは、東京２０２０大会を含む、多少、都市型観光的なあれに入ってしまうかもしれませんが、お伺いしてまいります。東海道五十三次の絵というのですか、おもてなしの効果につながると考えますが、本区のご所見をお伺いします。","respondent":"安藤文化スポーツ振興部長","answer":"そして、東京２０２０年大会を思い浮かべると、非常に暑い時期に行います。今後、関係機関ならびに企業と相談しながら、可能性について研究を深めてまいりたいと考えています。","id":"exchange-088"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ですから、ぜひ検討してほしいと求めましたので、よろしくお願いいたします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは、ダイバーシティについてと観光施策について、２点をお伺いいたします。","respondent":"田村総務部長","answer":"区においては、平成２８年４月に、次世代育成支援対策推進法と女性活躍推進法に基づく特定事業主行動計画というのをつくりました。出産支援の休暇や育児参加の休暇、目標値を定めて、これに向けて取り組んでいる内容です。","id":"exchange-090"},{"speaker":"石田（し）委員","kind":"提案","question":"そこで、ダイバーシティマネジメントについて、まず区の考えと、今後の取組みについてお伺いいたします。そういった意味で、このダイバーシティマネージャーの育成と、いわゆる担当職員の配置を提案いたしますが、その点もあわせてお答えくださいとの意見を述べました。","respondent":"田村総務部長","answer":"人事課に、そこで制度や手続の紹介、看護師・カウンセラーによる健康相談等も実施しているという内容です。子育てについては特に、それを統括する形で人事課長が全体を調整するという形が、一番ベストのやり方ではないかと考えております。","id":"exchange-091"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"まさに管理職の方がまず先頭に立って、マネージャーとして活躍していただくことを要望します。まずは区の内部から取り組んでいただいて、それを今度は外部へと発信してほしいと求めましたが、その点をお伺いします。","respondent":"田村総務部長","answer":"さらにこのような取組みを進めてまいりたいと考えております。例えば２０時に退庁を促すとか、あるいは可能なら職場のノー残業デーを週２日に増やす等、残業時間の縮減に努めてまいりたいと考えております。","id":"exchange-092"},{"speaker":"石田（し）委員","kind":"質問","question":"さまざまな職員の規定等もあると思いますが、例えばアドバイザー的な採用等も含めて、その点のご見解の説明を求めました。","respondent":"田村総務部長","answer":"外国人の雇用ですが、国籍要件がある場合は別として、やはり国籍要件のない場合には、外国人も含めて平等に採用選考を実施しております。例えば証明発行でのコンビニ交付など、削減できるところがあれば、適正な人員配置も含めて有効活用してまいりたいと考えております。","id":"exchange-093"},{"speaker":"石田（し）委員","kind":"提案","question":"これは要望で終わります。以前もご提案いたしましたが、これはぜひ品川区全体でのサポーターズクラブの設立を、改めてお願いしますとの意見を述べました。","respondent":"中山企画部長","answer":"仕掛けも必要かと考えていますので、いい素材をいかにインパクトあるように発信していくかということで工夫はしてまいりたいと考えています。いずれにしても、区と地域との連携、またプロモーションと観光の連携というものをしっかりとりながらやっていきたい。","id":"exchange-094"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"観光に向けて取組み強化をしてほしいと求めましたが、その点、いかがか尋ねました。","respondent":"安藤文化スポーツ振興部長、中山企画部長","answer":"そこの中で十分協議をして、区内のあらゆる資産を活用しながら体験型の事業を進めていきたいと考えています。１０種類ほどのデータは既に加工できる形で出しておりまして、課題認識としては、観光にもより活かせる方策をさらに拡充していきたいと考えています。","id":"exchange-095"},{"speaker":"石田（し）委員","kind":"意見","question":"アニメに使用された区内のスポットを整理するなどして、この企画にかかわっていくべきかと思いますが、その点についてもお答えください。ぜひ動画をつくって、区内の情報発信に活かしてほしいと求めましたが、その点もあわせてお答えくださいとの意見を述べました。","respondent":"安藤文化スポーツ振興部長、中山企画部長","answer":"私からは、アニメの１００周年の取組みについて回答します。つくるということは考えてはございませんけれども、そこを１つの拠点にして、今後また研究させていただきたいと思ってあります。オープンデータですけれども、区民の声を聞きながら、まずデータの数を増やし、また利用しやすさを考えていきたいと思っています。","id":"exchange-096"},{"speaker":"須貝委員","kind":"質問","question":"教員の長時間労働についてお伺いします。これらの是正について強力に取り組む方針を示したと言われていますが、品川区の職員の長時間労働の実態と、区の人事課の対応についての説明を求めました。","respondent":"田村総務部長","answer":"一般の職員の超過勤務の状況ですが、平成２７年度、８００時間超えが３０人で、うち１,０００時間を超える超勤の職員が１０人ということでございまして、主に職種とすると事務職というのが実態です。","id":"exchange-097"},{"speaker":"須貝委員","kind":"質問","question":"今、品川区役所の人事課のお話をお伺いしました。教員の長時間労働を把握していますか、の説明を求めました。","respondent":"本城教育次長","answer":"学校におきまして、校長等を中心にして、個々にその実態を把握しているような形です。そういう意味で、超過勤務のあり方自体が一般の職員と違う関係で、数値的なデータを持ち合わせているものはございません。","id":"exchange-098"},{"speaker":"須貝委員","kind":"質問","question":"今お話を伺いましたが、そして生徒としっかり向き合えない現状を改善してほしいと、文部科学省に届けられております。きちんとしたデータをお持ちでないとおっしゃいましたが、出退勤のタイムカードが区役所にあるのに、なぜ学校に置かないのか尋ねました。","respondent":"本城教育次長","answer":"当然、そこに出てきた課題等については、しっかり対応していかなければいけないと考えています。例えばストレスへの対応ということもありますので、平成２８年度からも、教員の種々の健康管理について努力しています。","id":"exchange-099"},{"speaker":"須貝委員","kind":"質問","question":"それならば、先ほど、区の人事課、総務部長がおっしゃった、何時間、長時間労働しているとか、そういうデータは出ないのか尋ねました。","respondent":"本城教育次長","answer":"人事課の一般職員のように、超過勤務手当と連動する形で正確な全体の全庁的な状況を把握しているのとは、そもそも前提が違うということがあります。学校長を中心とした管理体制、あるいは先ほどのストレスチェック等を含めて、しっかり体制を組んでやっているところです。","id":"exchange-100"},{"speaker":"須貝委員","kind":"質問","question":"なぜ、もっと早く改善できないのでしょうか。このように、大変ではないか尋ねました。","respondent":"本城教育次長、田村総務部長","answer":"それと、あと教育委員会としまして、教員の勤務の長時間化と言われているものに対する対応はさまざまな要因があると思います。ちょっとお答えしづらいですけれど、時間外勤務手当、休日勤務手当は支給しないという定めが法律にあります。","id":"exchange-101"},{"speaker":"須貝委員","kind":"質問","question":"一般企業ではどうですか。予算の裏づけがある教育特区はつくれないものか尋ねました。","respondent":"本城教育次長","answer":"ただ品川区の教育を進めてもらう軸となる教員を育成していくという面では、１つは、国あるいは都に要望し続けているところです。今の段階では特区の活用ではなく、今、国あるいは都に要望している状況です。","id":"exchange-102"},{"speaker":"須貝委員","kind":"質問","question":"だから、品川区もそういうふうにしないと、やはりできないのではないですか。品川区が人事権を持たない限り、このままいったら、小・中学校の２つの教員免許を持った教員は集められなくなってしまうのではないか尋ねました。","respondent":"本城教育次長","answer":"固有教員ということで、１９人の教員がおりまして、将来的に３０名を目指して核となる教員を移行しています。その移行期の中でしっかり対応できている状況ですが、今も義務教育学校には優先的に、両方の免許を持っている人を配置したりしながら。","id":"exchange-103"},{"speaker":"須貝委員","kind":"質問・要望","question":"このような大きな財源が残るなら、予算を使い切れないなら、その一部を区民にお返しするべきではありませんか、教えてください。予算は立てるだけではなく、初めて予算を立てた意味が出てくるのだと思うのですが、その辺について財政にお聞きしたいと思います。","respondent":"秋山財政課長","answer":"そういう目的で使っているということですので、これを区民に直接的な税として返す、減税については考えてございません。進行管理、進捗を行っているというところで、しっかりとコントロールをしていると考えているものです。","id":"exchange-104"},{"speaker":"須貝委員","kind":"質問","question":"そして、毎月毎月、ちゃんと財政課題を見ているわけですから、これだけ残りそうだ。こうやって、ふるさと納税で持っていかれないように考えます」という姿勢も私は大事だと思うのですが、お考えの説明を求めました。","respondent":"秋山財政課長","answer":"例えば去年であれば、全体のコントロールを見ながら補正予算を立てて、補正予算の中では低所得者向けの施策も打っていると考えているものです。区長会を通じ、また私どもそれぞれの立場で、東京都ないしは国に対して申し入れをしているという状況です。","id":"exchange-105"},{"speaker":"須貝委員","kind":"質問","question":"そういうことをやはり考えて、財政というのは持っていかないと、区民との会話が何もないではないですか。やはりそういうところも見据えて、区政、事業というのはやっていかなければいけないと思うのですが、もう一度、財政課のご意見の説明を求めました。","respondent":"秋山財政課長","answer":"増税したり減税したりということは全く考えておりませんので、今までどおり、必要な事業は必要な財源を使ってやっていきます。そういうことを今後も続けていきたいと考えているものです。","id":"exchange-106"},{"speaker":"須貝委員","kind":"意見","question":"それだったら、そういうふうに、区民にわかりやすいようにやればいいです。以上で終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-107"},{"speaker":"田中委員","kind":"質問・要望","question":"処遇改善は、正規職員だけに限らず非常勤保育士へも求められます。品川区では、区立・私立の非常勤職員に対し、それぞれどのような処遇改善を行っているのでしょうか、伺います。","respondent":"齋藤子ども未来部長","answer":"合同の研修会の実施や、特別な支援を要する児童に対する指導の方法等を教授いたしまして、質の向上を図っております。先ほどからご説明申し上げておりますが、品川区の場合は５０％、保育の処遇の改善の原資となっております。","id":"exchange-108"},{"speaker":"田中委員","kind":"質問・要望","question":"昨年の総括質疑では、待機児童問題に触れ、都市開発との関連性について伺いました。事業者とはどのような協議がされ、具体的に成果としてどのような整備がされたのでしょうか、伺います。","respondent":"齋藤子ども未来部長","answer":"先ほどから繰り返しご説明申し上げておりますが、この支出の中で、常勤・非常勤の別なく給与などの処遇改善につながっているものと考えております。ここでも開設が予定されており、平成３３年、協議を精力的に進めているところです。","id":"exchange-109"},{"speaker":"田中委員","kind":"質問・要望","question":"次に、羽田増便計画に伴って、品川区上空を航空機が低空飛行する問題について伺います。教室型の説明会を区として求めていると伺っていますが、なかなか実現しないことについて、どういう理由があると考えていらっしゃるのか尋ねました。","respondent":"藤田都市環境部長","answer":"品川区といたしましては、教室型の説明会のほかにも、さまざまな形で地域との話し合いがこれまで進められてきたところです。国がしっかりと説明するのがまず一番重要であると考えているところです。","id":"exchange-110"},{"speaker":"田中委員","kind":"質問・要望","question":"情報という性質上、できるだけ早いことが求められると考えますが、見解を伺います。今回の事例については教育委員会への審査請求であったので、教育委員会からも見解を伺いたいと思います。","respondent":"中山企画部長、本城教育次長","answer":"これは実は案件によりさまざまでございまして、最短１カ月のものもあれば、８カ月を要したものもあるという状況です。一番初めの事務を開始する手続をするにあたって、かなりの月数、かかってしまったところでございました。そういう事情がありましたので、公開請求があった請求人も、その経緯を、おわびも含めてご説明させていただいたところです。","id":"exchange-111"},{"speaker":"田中委員","kind":"質問・要望","question":"私たちは１年以上かかっていると思うのですけれど、なぜこのように時間がかかったのかというのをもう一度伺いたいと思います。どのようなデメリットがあることが想定され、その対策をどのように検討されて義務教育学校設置という判断をされたのか伺います。","respondent":"本城教育次長、中山企画部長","answer":"義務教育学校のことに関してですが、当初、本会議で答弁したときに、義務教育学校への移行についての説明の中で私がご答弁させていただいた関係です。それがしっかり確保されて、それに基づいて移行したというのが一番大きな論点です。今ご質問があったように、非公開決定の事実を知った日から３カ月以内に請求人が出すようにというのが行政不服審査法に定められております。","id":"exchange-112"},{"speaker":"田中委員","kind":"質問","question":"１点目は、義務教育学校の標準規模を伺います。２点目は、小学校３クラス・中学校５クラスという構成を想定していなかったのではと考えるのですが、区の見解はいかがか尋ねました。","respondent":"本城教育次長","answer":"今ご説明しましたように、既に学区域を持った、当然このような義務教育学校の制度の中でしっかり位置づけているものであると考えているところです。それにつきましては、約２６０名余ということで、全体の３７％程度の割合になっているものです。","id":"exchange-113"},{"speaker":"田中委員","kind":"質問","question":"９年間の教育課程を可能にするという法律の目的を考えると、義務教育学校から別の中学を選べる、本旨が違うのではと考えます。７年生から２クラス７０人もの子どもたちが、義務教育学校の本旨の整合性をどのようにつけるのか伺います。","respondent":"本城教育次長","answer":"小中一貫教育が始まったのは、それにしっかりとした基盤を与えるという意味づけで法制化されたというのが１つの大きなポイントだと考えています。","id":"exchange-114"},{"speaker":"田中委員","kind":"質問","question":"義務教育学校設置という判断をされたのかという質問は、１年越しではなくて情報が渡されていれば、今この質問をしなくても済んだのです。なので、情報公開に１年かかるのは、やはり時間がかかり過ぎだというのを感じるので、ぜひそこを改善していってほしいと思います。","respondent":"本城教育次長","answer":"今お話がありましたが、それは先ほどご説明させていただきましたが、経緯等については請求された方にもご説明をさせていただいたところです。ある地域はある地域なりに合った学校、それぞれが全て義務教育学校の形で教育を推進しているという理解で考えているところです。","id":"exchange-115"},{"speaker":"田中委員","kind":"質問・要望","question":"どうしてそんなに手続が混乱してしまったのかとも思いますし、その辺はきちんと今回のことを踏まえて改善していってほしいと思います。市民が知る権利として有効活用できるように、丁寧な説明と、そして迅速な対応を、本当に早くしていただけるよう強く求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"鈴木（真）委員","kind":"提案","question":"これらの提案は、各議員が区民の皆さんからお聞きした声を集約したものであり、事業が早期に具体化することを望みます。本委員会で我が会派委員が指摘・提案した、そしてさらなる待機児童対策などの提案・要望を真摯に捉え、今後の施策に活かされることを要望しとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-117"},{"speaker":"たけうち委員","kind":"提案","question":"日帰り型産後ケアや産後家事・育児支援の拡充などの子育て支援の充実、我が会派の提案・要望が数多く予算に反映されたことを評価いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-118"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"区営住宅、公園など、切実な区民要望に充てるよう求めます。５月ではなく直ちに撤退するよう国に求めるべきです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-119"},{"speaker":"大倉委員","kind":"提案","question":"３年後に迫った２０２０年東京オリンピック・パラリンピックの開催に向け、教育関係では、社会とのかかわりを持てる環境づくりが進むよう要望しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-120"},{"speaker":"須貝委員","kind":"提案","question":"学校教員の長時間労働を減らし、８時間労働を超える分については残業手当を支給していただきたい。最後に、我が会派の委員から提案された意見を活かしていただくことを要望しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-121"},{"speaker":"吉田委員","kind":"提案","question":"各款別審査で生活者ネットワークが指摘・提案させていただいた意見を活かしていただくことを要望し、さらに、以下何点か意見を申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-122"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/805569?Template=document&Id=1068#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":120794,"voices":275}},{"id":"h29-20170327-10","meetingId":"h29-cm03","date":"2017年3月27日","dateIso":"2017-03-27","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時１３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件整理しています。","topics":[{"id":"topic-01","title":"途中ですが、ただいまのご案内のとおり、予定表３その他の(3)東京都後期高齢者医療広域連合議会の報告","agenda":"途中ですが、ただいまのご案内のとおり、予定表３その他の(3)東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"飯沼副委員長","kind":"質問","question":"それに基づいて採決されたのだと思うのですけれども、広域連合の議会のところで、議員として意見を述べるような場があったのかどうか。前回欠席をされていると、今伺いましたけれども、議員として発言するような場は保障されていたのか、その１点だけ。","respondent":"本多議員","answer":"臨時議会は一般質問はありませんので、意見表明はできますので、この臨時会に向けて意見表明をされたという方が議事録を読んでわかりました。意見を述べることは可能ということです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"意見","question":"その上で、教育長という教育行政のトップを決める人事ですので、この間の実績を重く見ました。他区には見られない義務教育学校や、学校選択制や、小中一貫教育などを進める品川の教育改革は、抜本的な見直しが必要だと思いますので、反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"}]},{"id":"topic-02","title":"議事日程（５）および追加議事日程","agenda":"議事日程（５）および追加議事日程","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"文教委員会で第３１号議案と第３３号議案につきまして、また区内の中小企業の経営が厳しい中、給与が上がるという今回の条例改正には反対いたします。ほかのものに関しては、賛成いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/706163?Template=document&Id=5216#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":10409,"voices":42}},{"id":"h29-20170414-10","meetingId":"h29-cm04","date":"2017年4月14日","dateIso":"2017-04-14","committee":"議会運営委員会","time":"午後 １時００分～午後 １時４４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"特別委員会の調査事項等","agenda":"特別委員会の調査事項等","exchanges":[{"speaker":"石田（秀）委員","kind":"意見","question":"もう一点は、行財政改革の中で取り扱っていくべきだろうということで、１点目は行財政改革特別委員会を設置するべきだろうと考えています。以上、２つの特別委員会をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"意見","question":"品川区がどのような施策を打っていくべきなのか、今後、早いうちに議会としても調査をする必要があるのではないかと。平成５２年までは幼年人口が増えて、あと５０年後には人口が８,０００万人になってしまうという中で、立てさせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"中塚委員","kind":"提案","question":"特別委員会にふさわしいと思いますし、これも区民の要望が強いテーマだと思いますので、提案させてほしいと求めました。そして緊急性も高いので、特別委員会としてふさわしいのではないかと思い、３つの提案をしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"あべ委員","kind":"提案","question":"せっかくですので、ある程度、一定の考え方を提案できるようなところまで進めていってもいいのではないかという提案です。まちにどんな負担があるのか、そういったことにどれだけ対応していけるのかということも、具体的に材料があれば考えていきたいと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"区の重要課題を審議するからには、必ず関連する事項がある事は当たり前だと思いますので、このような慣例は撤廃すべきです。区民要望がない課題に対して審議する事に疑問を感じますので、維新・無所属品川は特別委員会を設置することは反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"意見","question":"ここの入れ方は、そういう部分の１つの項目にして、調査項目の小さい項目の中に庁舎修繕とか有効活用を入れていくのがいいと我々は思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"提案","question":"委員会としては２つでもいいということで、今のご提案だと、行財政改革の中の基礎自治体のあり方についてというところ。今、立て分けしていただいた中に、区有施設のあり方というところで、それは公有地活用と組み合わせるというご提案をいただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"調査事項の次にある備考、このテーマの中に区民への影響はぜひ入れていただいて、ご議論を深めていただくように位置づけてほしいと求めました。その１点です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"あべ委員","kind":"提案","question":"その中でご質問をさせていただきたいのですけれども、例えば児童相談所の移管など以外のことは、どういう問題意識を持ってご提案をされているのか。ご提案の段階では、どういったことについて問題意識を持っていらっしゃるのかというのを１つ伺いたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"これも３年ぐらい前の行政改革特別委員会の中で、減免団体の利用率だ何だというのは全部１回出して、資料は全部揃っている。予算特別委員会の総括で質問して、我々、自民党・子ども未来の考え方です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問","question":"人口動向と福祉を結び付けるというところを厚生委員会でやるのですかといったら、総務委員会でやるのですかといったら、やらないと思います。そこはもう正副にお預けをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"あべ委員","kind":"提案","question":"これはまた別の議論、別の場での提案になっていくと思います。お２人から丁寧なご説明をいただいたので、そのように確認させていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/706163?Template=document&Id=5218#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":14529,"voices":46}},{"id":"h29-20170421-6","meetingId":"h29-cm04","date":"2017年4月21日","dateIso":"2017-04-21","committee":"区民委員会","time":"午後 １時００分～午後 ４時３４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件整理しています。","topics":[{"id":"topic-01","title":"の順番では、初めに、(1)「荏原第四地域センター改修工事」","agenda":"の順番では、初めに、(1)「荏原第四地域センター改修工事」","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"４月から窓口委託が始まって、当初は一定の混乱が生じたというお話も伺っているのですけれども、どういう状況だったのか。区にあったのか、まだ始まって１カ月にもならない現在の時点ですけれども、状況を伺いたいです。","respondent":"提坂戸籍住民課長","answer":"４月１日にスタートしたばかりで、そういう形もありますので、若干多い人数で対応させていただいているかと思います。来られたときの対応は、今日の段階でもう２０日ぐらい過ぎておりまして、苦情のほうはこれから改善させていただきたいと考えています。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"４人の倍ぐらいはいたのかなと思うのですけれども、現状をどう、その点を伺いたいと思います。いくつかまとめて伺いたいのですけれども、この規定が従事者に厳格に守られているという認識なのか、そこを伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"トラブルの報告と対応ということで、事業者のほうから、口頭および書面で報告が出ている形でおります。一応、基本的にお客様とやりとりをして、疑義が生じたらすぐに区に引き継ぐという形をとらせております。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"公務員には当然求められるスキルだと私は思いますけれども、時給１,０００円という待遇に対して、この点を伺いたいと思います。委託の前と後で、待ち時間や混雑の変化について比較できる調査結果があるのかどうか、そこも伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"２０日しかたっていないというところで、日々、待ち時間は短縮していると考えています。ただ、実際にストップウォッチ等ではかるというわけにはいかないので、正確に検証というのはなかなか難しいというのが実情です。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"待ち時間の短縮や混雑の緩和とおっしゃっているわけですから、先ほど伺ったのは、あるのかないのかご説明ほしいと求めました。どういう業務体制表が区に提出されているのかご説明いただきたいのと、既に４月について再提出はあったのか、そこも伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"先ほど、業務の体制ということで、私、説明不足だったのですけれども、業務体制表は間違いなく受託者のほうから提出いただいております。基本的には７名を確保しているということで、今、繁忙期ですけれども、極力待ち時間を短縮するように努力している最中です。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"渡してはいけない個人情報を他人に渡した場合は、故意または過失に当たるのかどうか、その点を伺いたいと思います。予算委員会でも伺いましたけれども、損害賠償とは、具体的に誰の何を賠償するのか、この点も改めて明確にご説明ほしいと求めました。","respondent":"提坂戸籍住民課長","answer":"費用は一切生じないとご説明したのは、項番２の窓口案内の充実における本庁舎の窓口案内呼出機のことです。損害を受けたですとか、そういう場合に賠償してもらう、そういうケースが考えられるかと存じます。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が伺ったのは、見落としてしまった、ここの仕様書の１１の損害賠償責任に書いてある故意または過失に当たるのかと伺ったので。ひろまち保育園の例もあるだけに、１つの項目でも違反があれば契約解除ができると、そういう区の認識なのかどうか伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"はなくて人材派遣ということであれば、受託者が直接指示命令をできるということで、これは再委託ではないと考えます。内容も個々に様々なケースが考えられてありますけれども、たった１つの項目でも、様々なケースが考えられるかと思ってあります。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこを確認させてほしいと求めました。なぜ担保できるのか、私はとても疑問なので、それについても伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"こちらで考えているのは、そういう性質のものと考えておりまして、人材派遣等はちょっと違う性質のものと考えています。委託の従事者であっても、きっちりと誓約書も出してもらっておりますので、その辺は問題ないと考えています。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"それを確認させていただきたいのと、従事者に求められているスキルや個人情報等、そこをご説明ほしいと求めました。","respondent":"提坂戸籍住民課長","answer":"直接、指示命令等ができることなので、直接受託者が雇用した契約社員とかパートと同じ扱いであると考えます。人材派遣会社から派遣された場合でも、研修等その辺は全く同様に行うということが想定されます。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"もしも情報漏洩などの事故が起こった場合に、区として責任をきちんと持つことができるのかどうか。情報漏洩をしてしまった場合、事業者ではなくて、その個人がしてしまった場合はどうなるのかということを伺いたいのですけれども。","respondent":"提坂戸籍住民課長","answer":"そういう事故が起きた場合、事業者から区のほうに即座に報告するということは徹底させております。一義的には受託者のほうにも責任があるということで考えておりますが、最終的には区が行っている事業なので、区のほうにも責任があると思います。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"そういうことが起こるのはちょっと困ります。今後、情報漏洩は絶対に起きないとは言い切れないので、きちんと徹底してほしいのですけれども、その辺について伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"最悪の場合は契約解除をするとか、あと契約上の問題であれば指名停止処分を行うとか、そういうものがあるかと思います。そういうことで、厳重に個人情報の保護には努めてまいりたいと考えております。","id":"exchange-010"},{"speaker":"こんの委員","kind":"確認","question":"参考までに確認というか、改善されてこうなりますというところをお聞きしたいのが、新しく設置をする庁舎内の呼出機の主な機能です。どうされていて、どういったものなのかと、もう少し詳しくの説明を求めました。","respondent":"提坂戸籍住民課長","answer":"その辺もありますので、その辺は職員が注意して直接お声かけをするとか、そういう対応をしてまいりました。大体半径１５０ｍ以内は届くということなので、少し戸籍住民課の事務室を離れている程度でも届くという形で聞いてあります。","id":"exchange-011"},{"speaker":"こんの委員","kind":"確認","question":"今お聞きしようと思っていた範囲内をお答えいただいたので、持ち歩いていいという、そういうものなのか確認です。端末をお渡しして見ていただくという、さらなるサービスが充実するというか、個別にするというイメージでいいのか尋ねました。","respondent":"提坂戸籍住民課長","answer":"窓口でやりとりした中で、いわゆる健常者の方で、番号掲示板でご自分の番号が出たら窓口に来ていただくという形をとりたいと考えています。そちらについては、受付番号にＱＲコードがついているので、そこを読み取っていただいて、ご自分の番号が反映される形になっています。","id":"exchange-012"},{"speaker":"こんの委員","kind":"質問","question":"端末をお渡しをして、それを持って庁舎内の他の課も行って帰ってきたいという人には使えるのですか。細かいことで恐縮ですが、そういうことも今後はあるのか尋ねました。","respondent":"提坂戸籍住民課長","answer":"はモバイルの貸し出しについては、高齢者、視聴覚の不自由な方、障害者の方を優先に回していきたいと思います。若年層の方とか、ＱＲコードを読み取って処理状況を確認できますということを説明して、そちらを活用していただきたいと考えています。","id":"exchange-013"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうしますと、この方は使えそう、この方は使えなさそう等、非常に判断は難しいかもしれません。今後、そうしたものが充実されるといいかと思いますので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"藤原委員","kind":"確認","question":"３点目は、これ、課長がつくるのですか。あのマークはいろいろ簡単につけてはいけないというのはあるとは思うのですけれども、その辺についてはなかったのかについてお伺いします。","respondent":"提坂戸籍住民課長","answer":"定期的に何年かおきに見直しをしなければいけないと考えていますので、そのときにはまたその都度、様式について検討してまいりたいと考えています。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"改ざん防止用紙というのはそれぐらいですか。それとも、何かいろいろ印刷している中で、名前、生年月日、住所等、何かをいじっても改ざん防止用紙は何か出てくるのか尋ねました。","respondent":"提坂戸籍住民課長","answer":"肉眼ではちょっとわかりづらいのですけれども、「SHINAGAWA」、「SHINAGAWA」と小さい文字を施しています。その辺を複数組み合わせて改ざん防止を施しております。","id":"exchange-016"}]},{"id":"topic-02","title":"戻りまして、(1)荏原第四地域センター改修工事","agenda":"戻りまして、(1)荏原第四地域センター改修工事","exchanges":[{"speaker":"いながわ委員","kind":"確認","question":"改修工事ということで、確認なのですけれども、荏原第四地域センターの耐震は何年か前、４年前にやっていますか。それを確認させてください。","respondent":"伊崎地域活動課長","answer":"こちらの荏原第四地域センターは昭和５７年６月の新耐震で建てております。なお、備蓄倉庫を兼ね備えております関係で、躯体部分はかなり頑丈につくったというふうに聞いております。","id":"exchange-017"},{"speaker":"いながわ委員","kind":"質問・要望","question":"今、１台止まっていますけれども、その車を電気自動車にしたときのための充電設備を設置しますということでしょうか。ステーションと書いてしまうと、ほかの人も使っていいですよというイメージになってしまうので、その確認をさせてください。","respondent":"伊崎地域活動課長","answer":"今おっしゃられたようなご案内のために立てられたものと認識をしておりますけれども、皆さんにわかりやすく、そこは考えてまいります。昨年度４カ所、今年度も４カ所やっていく予定ですので、電気自動車への切り替えを進めている中での１つとして行うものです。","id":"exchange-018"},{"speaker":"いながわ委員","kind":"質問・要望","question":"公園も含めて、うまくそういうものができたらいいのではないかと思いますので、そういうものも計画的にお考えほしいと求めました。答弁は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"前回伺いましたが、その後の状況について伺いたいのと、概要をご説明ほしいと求めました。","respondent":"伊崎地域活動課長","answer":"地域の方々への説明ですけれども、前回の委員会でもご説明をしましたとおり、ご予約にいらしたときに１団体ずつ丁寧にご説明を差し上げています。こちらは地域センターとしては初めて入れるものでございまして、機能としましては、７２時間対応ができるものです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"それがどんなふうになったのか伺いたいと思うのですけれども、個室で座ると足の膝が前の壁についてしまうというようなお話も伺ったのですけれども。要望させていただきましたけれども、それぞれ４点について、どういう状況なのか伺いたいと思います。","respondent":"伊崎地域活動課長","answer":"今まで２階のだれでもトイレの扉が非常に開けづらかったということがありますので、バリアフリーについて対応していくということは考えております。その後、磁気ループは設置が可能だと考えていますので、状況を見ながらというふうに考えております。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"それを伺いたいのと、マイクについては、第１集会室も第２集会室もそれぞれ独立して使えるということなのでしょうか。地域で、こうした大規模改修時にも固定式の磁気ループの設置をぜひ区の方針にしていただきたいと改めて思いますが、いかがか尋ねました。","respondent":"伊崎地域活動課長","answer":"ですので、こちらは特に増設をする予定はございません。様々な配慮が必要であることを担当としても認識をしておりますので、当区の全体の方針は、それぞれ考えていくものだと考えています。","id":"exchange-022"}]},{"id":"topic-03","title":"平成２９年度地域振興基金を活用した区民活動助成制度の審査結果","agenda":"平成２９年度地域振興基金を活用した区民活動助成制度の審査結果","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"何点かお伺いします。もともと選定は年１回、１２事業ぐらいを考えて切ってしまっているのか、その辺を教えていただけますか。","respondent":"遠藤協働・国際担当課長","answer":"回数ですが、平成２１年度から事業を開始しておりますので、今回が８年度目という形になります。去年も９件の応募だったのですけれども、今年は１４件応募いただきましたので、これからどんどん応募が増えればと考えています。","id":"exchange-023"},{"speaker":"いながわ委員","kind":"質問・要望","question":"今度はスタートアップではなくなっていくわけですから、８回もやっていれば増えていかなければいけないというイメージなのです、何となく。","respondent":"遠藤協働・国際担当課長、堀越地域振興部長","answer":"団体設立からおおむね５年以内の団体を対象としておりまして、チャレンジ助成、どちらを申し込んでもいいという扱いになっております。最初はチャレンジ助成だけだったのですが、コースを１つ増設して応募しやすいような形で考えてございまして、このような形になってきてあります。","id":"exchange-024"},{"speaker":"いながわ委員","kind":"質問・要望","question":"増えていかないというのは、今もう３年を超えたら、とにかく広く区民が交流できるような仕組みをつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"本多委員","kind":"質問","question":"簡単に伺います。その団体がそれぞれどういう思いなのかをぜひ入れていただけると、区民もイメージしやすいなと思うので、それだけの説明を求めました。","respondent":"遠藤協働・国際担当課長","answer":"それから、お１人の高齢者に対して、それぞれの団体が何かできないかというようなところが多かったように感じております。資料の作り方につきましては、今後、工夫していきたいと思います。","id":"exchange-026"},{"speaker":"本多委員","kind":"質問","question":"さらにその団体がどういうふうな思いなのかというのをぜひ、そういう思いをさらに細かく出していただけるとイメージしやすいので、ぜひお願いします。","respondent":"遠藤協働・国際担当課長","answer":"８月４日です。","id":"exchange-027"},{"speaker":"伊藤副委員長","kind":"質問","question":"だから、４００万円の上限でいいのかということです。もう少し内容を拡大して、平成２７年度末の基金残高が６億４,０００万円、やはりもっと様々な団体が参加しやすい制度をつくったらどうなのか尋ねました。","respondent":"遠藤協働・国際担当課長","answer":"平成２８年度末で６億４,０００万円ちょっとの金額という形になっておりまして、平成２８年度当初は８０万円がそこから利息として生まれております。","id":"exchange-028"},{"speaker":"伊藤副委員長","kind":"提案","question":"それに対して上限４００万円の予算で運営していくのは、単純にいくと何百年ぐらいかかるわけです。それぞれの事業を拡大するなり、検討してはどうですかという提案をしていますので、改めて答弁をお願い申し上げますとの意見を述べました。","respondent":"遠藤協働・国際担当課長","answer":"今回、３００万円を超える応募がありまして、４００万円にした効果もあったのかと思います。今後も推移を見ながら拡大していこうと考えています。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"以前から審査方法について伺っているというか、もっとオープンにしてほしいという要望をしているのですけれども、審査を受けた団体の方たちも。その辺に関してご答弁ほしいと求めました。","respondent":"遠藤協働・国際担当課長","answer":"ホームページ等で周知をさせていただいているところですが、さらに拡大ですので、それを含めて検討させていただければと思います。それから、資料がもっと手厚く、わかりやすくですので、こちらについては、今回のご意見を踏まえまして工夫させていただければと思います。","id":"exchange-030"},{"speaker":"田中委員","kind":"意見","question":"なぜ今回に限って、この位置というか、そこも検討していただけると良いと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"目的のところで伺うのですけれども、「地域の課題や社会的課題の解決に向けた事業」という意味では、これはそもそも行政がやる仕事だと思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"遠藤協働・国際担当課長","answer":"ただ、なかなか行政単独で細かい全てのものに対応していくのはやはり限界がある部分もあるのかなというふうに感じております。そこが今回、協働の目的なのかなというふうに考えておりますので、そういうところでの区民の方々にもご協力いただくです。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"「いいですね」としか言いようがないと思うのですけれども、今日いらっしゃるから、どういう行動を担当の課とはしていくのかお伺いします。ですから、やることはあるのかという疑問があるので、その辺についてもお伺いします。","respondent":"遠藤協働・国際担当課長、鈴木文化観光課長","answer":"きちんとした説明をというようなお話だったと思うのですが、それはこちらの協働につなげていただければというお話をさせていただいているところです。ご質問にありました例として出ました４番の事業ですが、区のほうでも品川宿での似たような事業はあります。","id":"exchange-033"}]},{"id":"topic-04","title":"春季プレミアム付区内共通商品券発行事業への助成","agenda":"春季プレミアム付区内共通商品券発行事業への助成","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"大体これを見ると８口買う人が多いわけですから、１人１口だったら６万人に行くわけであって、それがどんどん減っていくわけです。１,０００名にアンケートを送付したということなのですが、今回２回目になると思うのですけれども、いかかか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"秋でしたら１.８８倍ですので、共通商品券事業のよりよい方向を分析するためのデータ活用をしっかりやっていこうというふうに思っております。","id":"exchange-034"},{"speaker":"こんの委員","kind":"確認","question":"仕組みをまず確認をしたいのですけれども、秋から事前申し込みという形でしましたけれども、抽選は、これはどういった形で行うのでしょうか。その委任された人が引き換えに行くときに、本人確認をするかしないかという確認です。","respondent":"山崎商業・ものづくり課長","answer":"秋は、やはり最初でしたので、私もその現場に行かせていただいて、説明を聞きながら区としても確認をさせていただきながらやらせていただきました。この取り扱いをいろいろ検討したのですが、当初そういった販売の折りに列ができて危ないとか、そういうことになってしまうので。","id":"exchange-035"},{"speaker":"こんの委員","kind":"質問・要望","question":"今の時点で何かお考えがあるのか、あるいは今後どうしようかというところを検討中なのか、もう１度ご答弁をほしいと求めました。本人確認はきちんとされるということだったので、その点、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"適正な事務の執行に努めつつ、例えば１,３００冊残ったものを、今回は２回で終了させました。検討の中ですけれども、そういったことを検討・研究をしていますので、この事業をやってまいりたいというふうに思っています。","id":"exchange-036"}]},{"id":"topic-05","title":"中小企業センター空調設備改修工事に伴う貸室利用停止","agenda":"中小企業センター空調設備改修工事に伴う貸室利用停止","exchanges":[{"speaker":"いながわ委員","kind":"確認","question":"６階でしたか、水を通したりしているわけですから、別にそこが分かれているわけではないわけですね。では、その上の介護専門学校も行う、それはまた所管が違うので、構成的な要素の中で予算組みがされているのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"学校のほうも５階と６階の機能を一定程度、５階と６階で互い違いに施工していくようなことで、そこは対応していくというようなことです。工事としましたら、一体的な建物として同時に行わせていただくようにします。","id":"exchange-037"},{"speaker":"中塚委員","kind":"意見","question":"それが暑いの寒いのとどう関係があるのかよくわからなかったのですけれども。それを考慮して利用停止期間を決めたということなのか、その辺がよくわからなかったので、の説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"夏場から１２月までの間に工事はいつでも施工ができることになりますけれども、その期間は、そのフロアは空調が全くきかなくなります。大体９月から１１月ぐらいの間だろう、今回、貸室の利用停止の期間を設定させていただいたというようなことです。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"わかりました。かと思ったら暑過ぎたり、今回の工事で何がどういうふうに改善されるのか、そこもご説明ほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"今まで空調改修をしていきながら、利用者の方々の快適なご利用空間を確保してまいりました。そのような状況のところがかなり起きているということがわかりまして、そこを替えて快適な空間といいますか、環境を整えられるだろうです。","id":"exchange-039"},{"speaker":"伊藤副委員長","kind":"確認","question":"確認というか、平成２７年度の利用率を見てみたのですけれども、音楽室、レクリエーションホール、それから小講習室が６０％を超えているのです。","respondent":"山崎商業・ものづくり課長","answer":"例えば大崎の産業支援交流施設なども持っておりますので、そうした施設などの代替を考えたり、こうしたところとしっかり連携をしながら使っていただく団体の方になるべく迷惑がかからないような対応に努めてまいるということで考えてあります。","id":"exchange-040"},{"speaker":"伊藤副委員長","kind":"意見","question":"ある程度、優先的に品川区の他の施設を紹介してあげるなりしていったほうが区民サービス向上だと思いますので、検討してくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"もう１度ゆっくりと答弁をいただきたいと思うのですけれども、情報漏洩が起きたときには、どのような手順が踏まれるはずだったのか。そこまでお願いします。","respondent":"提坂戸籍住民課長","answer":"その個人番号を変更する措置をとらせていただくということで、こういう事例があったという情報を共有化するといいますか、その面では欠けていた面があるというふうに反省しています。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問","question":"その事務上の引き継ぎがうまくいかなかった原因は何なのか尋ねました。","respondent":"提坂戸籍住民課長","answer":"事案が発生したことの処理経過ですとか、その辺の文書の保存が適切でなかった部分があったことが大きいところです。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問","question":"ＤＶ被害者の方に限らず、情報漏洩については、まず起きないものとして今まで答弁をいただいていたと思うのです。それが今回、そこに対してなぜそのようなことが起きてしまったかということと、今後どうしていくのかというところを伺います。","respondent":"提坂戸籍住民課長","answer":"民間委託の場合は、画面でそういうメッセージが出たのを見た場合は、すぐに区のほうに引き継いでいただく。正式なＤＶ支援措置の申し出が出ている分については、ロックをかけて、間違って処理を進めて発行することがないような形をとらせていただきました。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"ＤＶに関しての正式な書面というものは、一体何なのでしょうか。そうでないものの違いを教えていただきたいことと、前回、どうして情報が共有されなかったのかという部分も含めてお伺いしたいと思います。","respondent":"提坂戸籍住民課長","answer":"区のほうで審査して正式な支援決定をした上でシステム上のロックをかけるものですけれども、警察ですとか配偶者暴力相談支援センター等。情報共有化されていなかったというのは、結局、ごく限られた一部の職員で処理を進めていたです。","id":"exchange-045"},{"speaker":"田中委員","kind":"質問","question":"ごく一部の職員で処理がされてしまったということですが、それは単純に考えてやってはいけないのですよね。どうしてそのことが起こってしまったのかということと、今後、その辺をお伺いしたいです。","respondent":"提坂戸籍住民課長","answer":"課内研修を行ったということでご説明をさせていただきましたけれども、ＤＶ支援ですとか、地域センターの職員ですとか。研修ですとかそういうところで、課ですとか係の会議の中で周知していくということを大切に考えて、そこは実践していきたいと思います。","id":"exchange-046"},{"speaker":"田中委員","kind":"質問","question":"きちんと区からの謝罪があったので、共有がされていなかったということは、それは正式な謝罪の文書ではなかったということになるのでしょうか。その辺を伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"その謝罪の文書というのが適切に保管されていなくて確認できなかったというのが事実です。","id":"exchange-047"},{"speaker":"田中委員","kind":"確認","question":"その文書については、相手の方から、こういう文書をいただいたので大丈夫ですということを情報提供として私たちは伺っていて、確認がとられているはずなのですけれども、そこも今は情報共有されていないということか尋ねました。","respondent":"提坂戸籍住民課長","answer":"そういうことではございませんで、当時、謝罪文を出したときに、その辺の、はっきり申し上げて、決裁ですとか、そういうものがとられていなくて、それが保管されておらず２月の区民委員会のときにそれを探したのですが、見つからなかったということです。","id":"exchange-048"},{"speaker":"田中委員","kind":"質問","question":"ご答弁のとおりで、つまりは、うまく言えないのですけれども、隠されていたということで良いのか尋ねました。","respondent":"堀越地域振興部長","answer":"その２つに分けている点は、前段で説明させていただいた様々なケースがありますので、柔軟に対応できるようにという形でとっていたのですが。","id":"exchange-049"},{"speaker":"田中委員","kind":"質問","question":"正式な文書の謝罪を送られたということだったのですけれども、残っていなかったら、それは問題ではないですか。その当事者の方がそれを知ってどう思うのかということについて私もとても納得がいかないというか、その辺についてお伺いしたいと思います。","respondent":"提坂戸籍住民課長","answer":"私がご説明を申し上げた際は、一般的に正式にＤＶ支援がされていた方については、ロックをかけたということでご説明して。説明不足だったところがございまして、それは申し訳ございませんでした。","id":"exchange-050"},{"speaker":"田中委員","kind":"質問","question":"当事者の方への謝罪をどう考えるのかということと、本当にこのまま民間委託にしていくことは正しいのかどうか、そのことについて伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"職員であっても、委託事業者であっても同じことであって、守秘義務が課されております。ロックを解除することはできませんので、本庁舎のほうに連絡していただいて、事故を防ぐという形で進めてまいりたいと考えております。","id":"exchange-051"},{"speaker":"田中委員","kind":"質問","question":"そういう徹底をきちんとしてほしいことと、今度、もっと何かが起きたときに情報が上に上がってこないのではないかということを懸念しています。そんなことはないと思いたいのですけれども、その辺の対策について伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"あくまでも受付ということなので、そこには必ず区の職員が常駐しておりますので、そこで情報が上がってこないということは考えてございません。そこで必ず事故を未然に防ぐ形で万全を期したいと考えています。","id":"exchange-052"},{"speaker":"田中委員","kind":"質問・要望","question":"なので、その辺をしっかりとやってほしいと思います。もしも情報が漏洩したときの従事者との雇用契約について等、その辺をしっかりともう一度ご答弁いただきたいのですけれども、お伺いします。","respondent":"提坂戸籍住民課長","answer":"雇用契約の打ち切りということも当然ありますし、その上で区は受託者に対して処分を行う、最終的に最悪は契約解除することもあると思います。","id":"exchange-053"},{"speaker":"田中委員","kind":"意見","question":"こういうことがあったので、民間委託というか、危機管理が徹底される、情報が共有されること等、そういうことがしっかりしてからまた次の段階として民間委託という感じで、今はまずここの構築をしっかりされることが先決だと思うのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"中塚委員","kind":"質問","question":"アラーム表示があるのに、なぜ発行をしてしまったのか、その原因が今のご説明ではわからなかったので、もう一度そこを伺いたいと思います。２点目は、ご本人の対応も含めてやりとりは伺いましたけれども、この点も伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"住所が全く同じということと、その辺で処理注意ではあったのですけれども、同一世帯で夫婦ということで出してしまったということが考えられます。","id":"exchange-055"},{"speaker":"中塚委員","kind":"質問・要望","question":"住所と名前は確認ができるのでしょうけれども、なぜ交付してしまったのか、ここをご説明ほしいと求めました。２つ目は、実質的被害はないということですけれども、出てしまった情報を取り戻すことができなかったということなのか、この点も伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"処理注意のメッセージが出ますと、その注意の内容も見ることができるのですけれども、その辺を失念したという形と聞いております。取り戻すというか、被害は受けなかったということで、こちらのミスは申し訳ないですけれども。","id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"すみません。平成２７年１２月ということで、起きたのが平成２７年１２月で、これだけ最後にご説明ほしいと求めました。","respondent":"提坂戸籍住民課長","answer":"大変申し訳ございません。その後の対策として、アラーム表示をしている相談中の案件が１００件ほどありましたので、そちらを３月中に全件ロックをかけさせていただきました。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"平成２７年１２月に起きて、なぜ対策が行われなかったのか、区としての判断だと思うのです。なぜ今になってしまったのか、指摘がされるまでなぜ対策を打つことができなかったのか、そこは率直に答弁をほしいと求めました。","respondent":"提坂戸籍住民課長","answer":"それは大変申し訳ございません。実際、ごく一部の職員で処理されていて、情報の共有化がされていなかったので、その辺の対策がなされていなかったです。","id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/824061?Template=document&Id=2778#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":51968,"voices":159}},{"id":"h29-20170421-7","meetingId":"h29-cm04","date":"2017年4月21日","dateIso":"2017-04-21","committee":"厚生委員会","time":"午後 １時００分～午後 ４時２４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)障害児施策","agenda":"はじめに、(1)障害児施策","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"「にじのひろば」の利用料が高いというのは様々ご意見を伺っていましたので。もっと利用したいという方が増えた場合のキャパシティーというか、受け入れのキャパはどれくらいあるのかについてもお聞かせほしいと求めました。","respondent":"中山障害者福祉課長","answer":"それから、放課後等デイサービスと比較しまして日中一時支援事業の利用の支給の決定の基準ですが、１０日を基準とするということになっております。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"2)の一般１で、これは所得割区民税が２８万円未満ということなのですけれども、もしわかったら教えてほしいと求めました。その分、２０１６年度と比べて区の負担はどれくらい増えるのかということについて予算額と合わせて教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"予算要求の段階ではおおむね１,０１６万７,０００円程度を予定しております。これは区が地域支援事業ということで社会福祉協議会に委託をして行っているので、区の事業という位置づけになろうかと思います。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"資格などはどうなっているのかということと、今回、どんな資格者を何人ぐらい配置するのかということを教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"特に荏原については立地の面からもなかなか支援をしたくてもできないような状況もありました。実際に今回配置しました職員の専門職ですけれども、社会福祉士ではないのですが、長く知的障害の支援に携わっていた方を支援員として迎えるとともに。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"職員体制が専門職を配置するということで、具体的には資格がはっきりしない。どんな資格の人が何人かというのを含めて、よくわからなかったのですけれども、はっきり教えていただきたい。","respondent":"中山障害者福祉課長","answer":"こういう子どもにはこういう支援が必要だ、そういったことを研修することで、全体の支援力を上げていきたいと考えています。子どもがまだ来る前の段階で、そうした研修ですとか、具体的に子ども一人ひとりの状況に合わせた活動につなげていけるのではないかと考えています。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"社会福祉主事が１名増えるということと、研修などに割ける時間も増えるということと、具体的にもう１人職員が増えるということなのでしょうか。それならば非常に充実に向けて期待しますけれども、そういう形なのかということを最後に確認だけお願いします。","respondent":"中山障害者福祉課長","answer":"わかりにくい説明で申し訳ございません。その２時間で研修をしたり、その日のプログラムを考えたりということで、これはかなり大きな成果につながるのではないかと考えております。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"おおよそわかりました。それがやりがいにもつながっていくということにもなるかと思いますので、ぜひ充実していただけるようにお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問・要望","question":"今回、それとも少し気をつけて対応しなければならない子どもがおられるのかどうかということについて１点教えていただきたいのと。それとも近くの一般道のような所でとめるのか、その辺の安全性に対する考えについて、確認をしたいと思います。","respondent":"中山障害者福祉課長","answer":"ちょうど送迎車両が出入りするときにあそこが歩行者天国になるということで、バスは警察の許可がないとあそこを通行できないことになります。ちょうど角にあたる、そこからはほんとうにすぐそばですので、職員が付き添って「にじのひろば戸越」までご案内をする予定です。","id":"exchange-007"},{"speaker":"たけうち委員","kind":"確認","question":"２つありまして、まず、確認が１つです。これは１回登録すればいいのか、それとも１年に１回なのかということ、登録料の考え方を教えてもらえますか。","respondent":"中山障害者福祉課長","answer":"それから登録料の考え方なのですけれども、これは年間でいただいているものです。ファクスでのやりとりの経費ですとか、連絡帳の経費ですとか、そういったことで実費相当ということで登録料をいただいております。","id":"exchange-008"},{"speaker":"安藤副委員長","kind":"質問","question":"一般２の方だとかなり費用がかかってしまうということで、ある意味、その辺についての将来的な考え方をお伺いしたいと思います。例えば２０１５年１１月にオープンしたアプリ児童デイサービス北品川とか入っていないような気がするのですが、それはなぜなのかお伺いします。","respondent":"中山障害者福祉課長","answer":"１点目の負担の差についての考え方です。その他には、国立・都立も載せておりますが、これは教育総合支援センターのほうの就学相談を通してご紹介をしております。","id":"exchange-009"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"すまいるの場合はやはり月３,０００円ぐらいで区が一定かかわって、ぜひこれからさらに負担軽減を図っていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-02","title":"後期高齢者医療保険料軽減判定におけるシステムの誤り","agenda":"後期高齢者医療保険料軽減判定におけるシステムの誤り","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"５４名の方で最高額はどれぐらいになるのか、あわせて最低額の方はどれぐらいになるのかということもお聞かせください。それから、「個々の事情を伺いながら丁寧に説明した上で本来の保険料を納付していただきます」と記載されているのですけれども、５４名と７名。","respondent":"三ツ橋国保医療年金課長","answer":"次に、６１名の方に対してはどのように区は対応していくのかという部分ですけれども、分納のご相談も応じますということは伝えております。無理のない範囲で分納のご相談ということは伝えております。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"電話で内容についてわかるのかどうかわからないのですけれども、その辺は丁寧にやる必要があるのではないかと思いますが、その点どうでしょうか。それ以前はどうなのかというあたりもの説明を求めました。","respondent":"三ツ橋国保医療年金課長","answer":"そして、丁寧に説明をしていくことが必要だと思われますけれども、今回につきましては、発送した後、実は今までに問い合わせが５件ほど来ております。今のところその５件につきましては、そのときに丁寧に説明した結果、納得していただいている状況です。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"平成２０年度から平成２６年度までの分というのは、平成２０年度から多く払い過ぎた分は、そのままになってしまうということになるのでしょうか。そうであればちょっと問題にはならないのかという思いがするのですけれども、いかがか尋ねました。","respondent":"三ツ橋国保医療年金課長","answer":"増額更正を行うなど徴収の部分というのは、様々な法律上決まっていることがございまして、その関係で平成２７年度、平成２８年度となっております。","id":"exchange-013"},{"speaker":"横山委員","kind":"確認","question":"１点だけ確認させてください。そちらの再発防止について、複数の担当者による確認を徹底するということなのですが、この辺少し詳しく教えていただけますか。","respondent":"三ツ橋国保医療年金課長","answer":"このシステムは税法上の部分を用いていたようで、ちょっと説明するとかなり細かいことになってしまいますので詳しくは申し上げませんけれども。","id":"exchange-014"}]},{"id":"topic-03","title":"の３、所管事務調査","agenda":"の３、所管事務調査","exchanges":[{"speaker":"横山委員","kind":"質問・要望","question":"そちらのところはまた結果が出ましたらその段階で確認させていただきたいと思うのですけれども、その辺はどのように考えていらっしゃるのか尋ねました。","respondent":"三ツ橋国保医療年金課長","answer":"こちらに3)としてお示ししておりますのが課内の部分でございまして、東京都との関係ですが、主管課長会がありまして、そちらの中で様々な東京都から報告事項などを受けております。","id":"exchange-015"},{"speaker":"横山委員","kind":"質問","question":"それは一方的にというか、一方向的に、都のほうから区のほうに情報がおりてくるという形でよろしいのでしょうか。区のほうからＰＴや広域化対策委員会で挙がったことに関して、都と双方向的に話し合うような場は、今年度中に想定されているのか尋ねました。","respondent":"三ツ橋国保医療年金課長","answer":"そちらの運用方針につきましても、２３区からの要望であったり、東京都の考え方などを主管課長会等で検討・協議をしています。「うちの区はこういうふうに考えているのだけれども」という討議の部分がありますので、意見交換の中では示していく予定です。","id":"exchange-016"},{"speaker":"横山委員","kind":"質問・要望","question":"２３区全体のお話ではあるかと思うのですけれども、実際の運用方法ですとか、異なる部分というのはやはり出てくるかと思います。できる限り、品川区のやり方・要望を都に伝えていただくとともに、２３区全体でもうまくいくような形で要望をお願いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"浅野委員","kind":"質問","question":"国民健康保険の制度改正ということで伺いました。そういうような動きがあるのかどうか、この件に関して区としての考え方、思惑とかそういうものがございましたらの説明を求めました。","respondent":"三ツ橋国保医療年金課長","answer":"こちらは国民健康保険関係の健診受診方針、おそらく後期高齢者支援の加算・減算の部分だと認識いたしましたけれども、制度自体は存続しているです。第２期の加算・減算の実施方法の中で、２％だということで、引き続き受診率の向上に向けて対応してまいります。","id":"exchange-018"},{"speaker":"浅野委員","kind":"確認","question":"もう１つ気になっている点なのですけれども、例えば、これはまた平等ではなくなってくる部分があると思います。例えば２３区とか都下の市町村も含めまして、それぞれが平等だと確認できるような、これについてはどのような動きがあるのかの説明を求めました。","respondent":"三ツ橋国保医療年金課長","answer":"実際に、今までずっと統一保険料方式を用いておりましたので、２３区としても統一保険料率方式の意識は高いと考えています。その中で、また特別区長会の中でも検討はしていると思いますので、そのあたりで平等性についても意識はしていってまいります。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"７５％はすでに保険料の賦課総額としたという状況になっていますけれども、これを、私はもとに戻していただきたい。","respondent":"三ツ橋国保医療年金課長","answer":"運営方針の部分ですけれども、実際のガイドラインについてもまだ案の状態で、今だにはっきりとしたものが出されていない状況だと認識しております。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はできればそれに加えて、そういうところもぜひしていただきたいというのは要望になりますが、要望として出させてほしいと求めました。そういうところも順次ご報告いただきたいと思っているのですけれども、その点についてもの説明を求めました。","respondent":"三ツ橋国保医療年金課長","answer":"情報提供等についてですけれども、必要に応じてお知らせしていくようにしていきたいと思いますので、よろしくお願いいたします。運営方針につきましても区の意見等は、そのあたりもはっきりと今ここで明確にお答えできませんけれども、必要に応じて申し入れてまいります。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほど私が一番初めにお聞きした、次回でも結構ですし、資料としてぜひ厚生委員会に示していただきたい。法定内の繰入金も合わせて示していただきたいというふうに思いますけれども、その点も含めてお願いします。","respondent":"三ツ橋国保医療年金課長","answer":"５割、２割の軽減料になっている、適切に対応していくため一般会計から繰入れているというのが法定外だと認識しております。項目については、詳細については今手持ちがないのですけれども、そのような認識です。","id":"exchange-022"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"もう１つは、実際に払えないということが過去にあったのでしょうかというのをお伺いしたいのと、なぜ今までは回避できたのでしょうか。それは繰入金によるものだったのか、その辺についてお伺いしたいと思います。","respondent":"三ツ橋国保医療年金課長","answer":"月に２回程度、国保医療年金課のメンバーが集まりまして、各係から選出した精鋭が集まって検討しております。品川区が、窓口業務に対応していかなければならない部分もあるものもありますので、そのような内容について検討しております。","id":"exchange-023"},{"speaker":"安藤副委員長","kind":"質問","question":"それとリスクのところは、それはなぜ回避できたのかということはお伺いしたので、別に制度改正は必要ないということになってしまっているわけです。","respondent":"三ツ橋国保医療年金課長","answer":"リスク回避の点ですけれども、委員ご指摘のとおり、一般繰入金の部分で回避できていると考えています。一番のリスクというのは、それ以外の部分というのも一般の繰入金の部分ですので、そこで品川区としては特に問題なくリスクの回避ができているです。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"区にとってどういったことが事務の効率化になるのかなという思いがするのですけれども、なるとしたらどんなところで効率化が具体的に図られるのかとの意見を述べました。","respondent":"三ツ橋国保医療年金課長","answer":"事務の効率化というものが、様々な場面で今検討中ですけれども、実際に東京都の中で違う区に移った場合に、資格はそのままで適用はその区になるですので、資格そのものが変わらないという部分で事務の効率化が図られることが１つだと考えています。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/999880?Template=document&Id=3474#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":26304,"voices":92}},{"id":"h29-20170421-8","meetingId":"h29-cm04","date":"2017年4月21日","dateIso":"2017-04-21","committee":"建設委員会","time":"午後 １時００分～午後 ２時４９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"平成２９年５月都営住宅入居者募集","agenda":"平成２９年５月都営住宅入居者募集","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"すみません、ちょっと細かいことで、気になったことをお伺いしたいのですけれども。４の募集住宅２,４００戸で、1)で世帯向となっているのですけれども、これは単身者向と世帯向という言い方で区別はあるのか尋ねました。","respondent":"長尾住宅課長","answer":"こちらは、今までの制度と変わるものではございませんので、世帯向と書いておりますが、ご家族向のファミリータイプということになります。こちらは世帯向となっておりますので、単身者向に関しては原則入っていないです。","id":"exchange-001"}]},{"id":"topic-02","title":"大崎三丁目地区（大崎駅西口Ｆ南地区）等の再開発計画","agenda":"大崎三丁目地区（大崎駅西口Ｆ南地区）等の再開発計画","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"１５９名参加されたということですけれども、ここでの住民の皆さんの反応とかはどうなのだったのかなというのをまず一つ聞きたいのと。","respondent":"稲田都市開発課長","answer":"説明会で参加された方の反応です。それから、２番目、補助金、事業費等ですが、まだこの辺は決まったものはありません。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"私も説明会に参加された方からお話を伺ったのですが、別紙２の３ページを見たときに、ここで初めて知る方が多かったということでした。住民の皆さんへの説明会を行いますみたいなお話があったかと思うのですけれども、そこがどこなのかもう一回ちょっと伺いたいと思います。","respondent":"稲田都市開発課長","answer":"先般実施した説明会以外に、本日と書いてありますその次に矢印的な四角で都市計画原案の検討というところがありますが、その次。それをもって都市計画案の作成を進めていきますが、この前に地区の方、地域の方への説明会をやっていこうと現在のところ考えております。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"この１１ページの予定が書かれていますけれども、説明会ということなので、要は４月１３日とか１４日とか１６日だということですよね。何年何月がこの都市計画原案の縦覧で、何年の何月が公告・縦覧で、というふうに月日がわかるようにならないか尋ねました。","respondent":"稲田都市開発課長","answer":"これは東京都の予定、スケジュールに合わせていくというところになるのですけれども、そのような形で考えております。この事業化との間にありますけれども、１１月頃決定できればいいかなというところで、組合のほうもそのような認識を持っているところです。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"とても早いペースでだんだんだんと進んでいってしまうのかなというところなのですけれども、この準備組合、今加入率はどれぐらいになっているのか。それからあと、この開発事業の保留床と権利床の割合というのはどんな感じになっているか伺いたいのですが。","respondent":"稲田都市開発課長","answer":"全権利者、先ほど２７名のうち２４名が加入しておりまして、加入率が８８.９％です。保留床等そういうところにつきましては、細かいところはまだ決まっていないです。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"この保留床とか権利床の割合のところは大体、この間開発をずっと進めてきているわけですけれども、どれぐらいにわかってくるのか伺いたいのと、あと保留床というのはどなたがどれくらいを、どなたが取得されるのかというのを伺いたいです。","respondent":"稲田都市開発課長","answer":"保留床等がいつ頃決まるのかという話になってきますが、現段階におきましては詳細というものはわからないという状況です。様々な保留床を持つ方もおられると思いますが、組合が持つ保留床というのもあって、あと参加組合員が持つ保留床もあるです。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"取得されていくというところで、大企業、そして大手デベロッパーの儲け先になっていくのではないかなというふうに私たちは感じているのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"筒井委員","kind":"意見","question":"今年度１１月に都市計画決定を見込んでいるということなのですけれども、今現時点でおおよその時期をお教えください。このＦ南地区の開発によって芳水小学校の児童とかそうした関係者の方々がどういった影響を受けるのか、それもわかる範囲でお教えくださいとの意見を述べました。","respondent":"稲田都市開発課長","answer":"一般的に言えば、このような進捗でいきますと、平成３３年度ぐらいには工事は終わるのではないかと考えております。芳水小学校におきましては、芳水小学校のほうにもお話をしまして、また関係各課、役所の内部でもそのような状況説明等をしてきておるところです。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"この１ページ目の下の図の中で、それはどういう、どういうふうに許可されてきているのか。時期的に、当初の計画と大幅に変更になる部分もあって、それをどういうふうな関係でこういうふうな開発が進んでいるのかというの説明を求めました。","respondent":"稲田都市開発課長","answer":"西口地区も平成６年あたりには大崎駅西口地区まちづくりの方針的なものをやって、全部で６地区割り当てをつくっているのです。水色の地区を拡大するという形になったということで、全くここもやりたいから増やすよという形での拡大ではないと考えております。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"この西口の、要は水色のところの駅に近いほう、これは都の計画の中に入っていたと思うのですよね。この明電舎との連携という意味ではどういう連携を考えられるものか、どういうことでここが入ってきているのかというのを教えて下さい。","respondent":"稲田都市開発課長","answer":"ちょうど再開発を検討する地区になりましたので、再開発を進める、再開発は再開発で準備組合がずっと検討しています。このＥ西地区の明電舎の土地において、基本的にはそういう形で、代替機能みたいなものを設けていくというような形でやっております。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"１つ目のほうなのですが、隣のほうは、何か違う方向で進めていくのでしょうか。それと、明電舎もどういう関係で、明電舎は明電舎の土地であるならば勝手にできるはずではないか尋ねました。","respondent":"稲田都市開発課長","answer":"歩行者ネットワーク、そういうこと等においても連携をしていけたらというところで、現在検討しています。今回の開発とあわせまして、明電舎が建物を建ててやっていくと、明電舎自身がそこにビルを建てるということになってあります。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"なので、どういう関係性を持ってやっていくのですかと、それが気になったのです。そこをお願いしたいと思います。","respondent":"稲田都市開発課長","answer":"ご指摘のとおり、まちづくりとしましては駅前からこの西側の地区につながる西口駅前地区におきましてもそういうところは重要ですので、今の準備組合段階でも区のほうも指導というか調整等を行って、西口一体的なまちづくりができるように調整をしています。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"全体像の中でやはりあのときこうすればよかったのにというふうにならないような形で、広い目で見ていただきたいなという思いがあります。それから、何が言いたいかわかるかと思うのですけれども、そこをしっかり進めていただきたいという意見で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問","question":"別紙２の資料の４ページを見ますと、このイラストのイメージというのがこういうふうになるよという、あくまでこれはイメージなのかどうかをまずお聞きしたいと思います。","respondent":"稲田都市開発課長","answer":"これはあくまでもイメージです。","id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"動線も当然変わってきて、お寺、あと居木神社に足を運ぶ方がいると思うのです。そういうことを含めて、観光にも属するのではないかと思いますが、その辺の区のお考えをお聞かせほしいと求めました。","respondent":"稲田都市開発課長","answer":"今回参道を整備し、また緑道でつながるというようなところも考えておりまして、また今後その辺の発展が期待されればいいなと考えています。","id":"exchange-015"},{"speaker":"塚本委員","kind":"意見","question":"説明会資料の２ページで、保育所はどのぐらいの規模のものになるとかという話が今の段階でどんな感じなのかというところと、あと店舗というのは地元ニーズ等というのはどのくらい活かされてきているのかというところの説明を求めました。","respondent":"稲田都市開発課長","answer":"子育て支援施設ですが、これは今組合と話をしておりまして、子育て支援施設の導入をするということになっています。この下層部分に配置するということでございまして、地域のニーズ等、現在のところはまだ準備組合の中での話し合いでされているというだけのものです。","id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"大きく必要であれば広くこういうことをやっていこうという考え方というのもあるのかなというところをお伺いしたいというのが１つ。","respondent":"稲田都市開発課長","answer":"保育をどうしていこうかですが、関係各課に説明する中で、保育関係部署のほうからもここに保育の施設が欲しいという意見はいただいております。今後におきまして、これもそういうところに気を配りながらというか連携しながら、その辺の配置は考えていくことになろうかと思います。","id":"exchange-017"},{"speaker":"塚本委員","kind":"意見","question":"いずれにしても、これからというところではあるかと思いますけれども、今課長のご答弁があったとおり、地域の連携とか庁内での連携とかということを強めながら、皆さんが本当に良かったなと思えるような形で進めていっていただけるようにお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問","question":"住居ではなくて事務所が増えることによって、大崎駅、今すごいですよね。地下に入る短絡線、あのようなものもどうなっているのか、ちょっと含めて教えてほしいと求めました。","respondent":"稲田都市開発課長、中村都市計画課長","answer":"ＪＲも何もやっていないわけではございませんで、ホームドアの設置もやっております。それから混雑時には警備員等を立てているところです。ＪＲの混雑につきましては、今都市開発課長が申し上げた対応をやっておりますので、区のほうからもお願いをし続けているところです。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問","question":"我々も、自分の場合、りんかい線を使って大崎に行くときに、夕方すごい状況ですよね、大崎駅。これでは危ないなと普段から思っているので、その辺の折衝というか計画、何かその辺のホームドア的なものの情報は入っていないか尋ねました。","respondent":"中村都市計画課長","answer":"非常に速度が遅いということで、緊急時には急停車ができると、ＪＲではそういう説明ではございました。ただ、区といたしましても、万一のことを考えて、やはり万一の安全に対しても対応していただきたい旨はＪＲのほうには申し伝えてあります。","id":"exchange-020"}]},{"id":"topic-03","title":"住宅耐震化緊急促進アクションプログラムに基づく耐震化促進","agenda":"住宅耐震化緊急促進アクションプログラムに基づく耐震化促進","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"国のほうから補助金が、助成金が、対象になる戸別訪問をする住宅というのはどれぐらいあるのか。そしてそれを４か年でということですけれども、どれくらい、１００％を目指しているのか、年間目標みたいなものはあるのか伺いたいと思います。","respondent":"鈴木建築課長","answer":"１１地区で戸別訪問の対象となる建物は戸建ての住宅、それから木造のアパートでございまして、対象が１１地区で計約４,０００棟です。それを３か年に分けるわけですが、当然目標としましては、この４,０００棟を３か年かけて全て回るという予定です。","id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"2)に、なぜ踏み出せないかというような声も聞いていくということだったのですけれども、ではこうだからできないのですという声が出たときの対応。","respondent":"鈴木建築課長","answer":"戸別訪問の回る体制ですが、これは委託を使って、今現在プロポーザルで委託業者を決定する予定です。そこには基本的には職員は含まず、資格を持った、あるいは知識を持った方が回るというような形での予定です。","id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問","question":"そもそも国がこうした助成金を出すというところから始まった事業、もともと品川区が木密のところでも１０年プラン、そういうのとかの中にあったわけではなく、国からこういうのがあるよと来たから、では品川区でやろうというふうになったということなのか尋ねました。","respondent":"鈴木建築課長","answer":"これは昨年度末の、本当に予算ぎりぎりのところで話が出たところですので、２３区で手を挙げていないところもあります。ただ、区としてはそういった拡充策を受けて、早急に内部で検討して、積極的に活用して耐震化を図っていきたいということで取り組んでいくものです。","id":"exchange-023"},{"speaker":"西本委員","kind":"提案","question":"その業者のほうだけではなくて、区のほうからもこういうようなことを提案できるよとか、ここは一緒に進めていかないといけない部分だと思うのです。何か工夫しないと、そこはとても気になりますが、いかがか尋ねました。","respondent":"鈴木建築課長","answer":"３点目の委託業者の守秘義務といいますか、実施に当たっては戸別訪問の実施計画、実施マニュアルというものも区の管理のもと作成して行います。継続して今年度この地区にこういった職員が、を持って、これから戸別に回りますというところの案内も徹底して行っていきたいです。","id":"exchange-024"},{"speaker":"西本委員","kind":"提案","question":"それで、なかなか、ではどうするのといった場合に、具体的な提案をしづらい部分だと思うのです。近隣の何とか不動産に聞いたらどうでしょうということは言えないではないか尋ねました。","respondent":"鈴木建築課長","answer":"これは以前も品川区を語って無料診断を今実施中ですというときもありました。そういった声があれば早急にそういったホームページ上でのお知らせ等も行いますが、あるいは効果的に返せるようなやりとりをしていきたいです。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"アンケートだからいろいろ出てくると思うのですが、ここの重要なことは、そう考えていない人たちに対してどうでしょうか。なので、いろいろと職員の方も一緒に何回か経験をしながら実行してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-04","title":"平成２９年度サマールックキャンペーンの実施","agenda":"平成２９年度サマールックキャンペーンの実施","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"それを強化期間とするということで、軽装というのは要は上着を脱いでネクタイを外すということを区としては軽装と言っているのか尋ねました。","respondent":"小林環境課長","answer":"昨年度環境課で週に１回、より軽装を意識した取組みとしまして、課で統一したポロシャツの着用を行ってまいりました。まずは一人一人のより軽装執務に対する意識の強化を図る等が目的でございまして、何か抗議があったとかそういうことでは基本的にないものです。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"そこは一応２８℃となっているけれども、環境課が私はやるべきだと思っているのですけれども、全体把握がどうなっているのかなというのが一つ。それと、このチラシのエコラ、これは誰が考えたのですかねと。","respondent":"小林環境課長","answer":"２８℃はあくまでも目途でございまして、そこからこの施設は何℃か、各施設のほうでそれぞれ適宜行ってくださいということをしております。エコラにつきましては、これは私が知っている範囲で申し訳ないのですが、区の職員が考えたものと聞いております。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"何かその情報を投げかけ、やってくださいはいいのですけれども、ではそれがどうだったのか。この庁舎もそうですよ、その快適さというのもきちんと情報をとったほうが今後の対策にいいのではないかなと思うのですが、いかがか尋ねました。","respondent":"小林環境課長","answer":"委員ご指摘のとおり、温度がどうかという把握まで我々のほうは実は今しておりませんが、今後、関係所管いろいろとありますので、調整をしながら進めていきたいと考えております。","id":"exchange-029"}]},{"id":"topic-05","title":"しながわＥＣＯフェスティバル２０１７の開催","agenda":"しながわＥＣＯフェスティバル２０１７の開催","exchanges":[{"speaker":"塚本委員","kind":"意見","question":"イベントの特色で、これは会派としても訴えてきたところでありますので、この意識付けの啓発がどんどん進むということは非常に歓迎したいと思いますとの意見を述べました。","respondent":"小林環境課長","answer":"小盛り等の量の調整ですが、容器の大きさは変わる予定ではなくて、各ブースのそばにこのお店では量の調節ができますよということをお示しした上で、その容器の中で小盛りになるとか、そういったところの量の調整だけをするところでまずは始めたいと考えているところです。","id":"exchange-030"},{"speaker":"塚本委員","kind":"質問・要望","question":"多いけれども大丈夫ですかみたいな声を積極的にかけるというのは効果的かなと思うのですけれども。その辺で運営するサイドの人に、そういうことは今回出展を募るに当たってぜひやってほしいと求めましたが、いかがか尋ねました。","respondent":"小林環境課長","answer":"今までこのＥＣＯフェスティバルを開催するまでに実行委員会等を何回か重ねてやってまいりました。それをまずはやって、今年度の反省をまた来年度活かしていくというようなところで取組みを進めていきたいと考えております。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"サービス精神だと安くてたくさん食べていただきたいという思いがあるのではないかと、提供する側としてはあると思うのですよね。物を大切にしようねという意識付けになると思うので、そちらもあわせて考えていただきたいなと思うのですが、いかがか尋ねました。","respondent":"小林環境課長","answer":"委員おっしゃるとおり、一つは食べましょうね、一つは残さないようにしましょうと、多分いろいろなやり方はあるかと考えています。実際にどういった対応をされたかというのはちょっと検証しながら、次年度以降何かうまく活かせないかというふうに考えていきたいと考えています。","id":"exchange-032"}]},{"id":"topic-06","title":"平成２９年度品川区・区内三消防署合同水防訓練の実施","agenda":"平成２９年度品川区・区内三消防署合同水防訓練の実施","exchanges":[{"speaker":"西本委員","kind":"確認","question":"すみません、１点確認ですが、７の（２）、七消防署と一緒にやるのが隔年であるということです。それで、今回はその年ではないので三消防署とやるということでよろしいか尋ねました。","respondent":"川部防災安全担当課長","answer":"委員ご指摘のとおりでございまして、当区と大田区、輪番で第二消防方面本部との連携訓練をやっておりまして、昨年度当区がやりましたので、今年は大田区が第二消防方面本部との連携をされるです。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問","question":"今までと場所が変わるということで、２枚目、別紙に図を載せていただきましたけれども、大体この西大井広場公園でやっていたときと同じなのか。ちょっと工夫して新しい場所だから変わったところがあったりするのか、伺いたいと思います。","respondent":"川部防災安全担当課長","answer":"テントが１２個並んでいまして、西大井広場公園ですとこれがまっすぐ１２個並べられるというような、面積的な大きさがまず一つあります。今回この会場でその規模で訓練を実施させていただきまして、検討事項等を鑑みまして、来年につなげていきたいと考えております。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"今回ここのしながわ中央公園の多目的広場を使ってということですけれども、そうするとずっとここになっていくということなのか尋ねました。","respondent":"川部防災安全担当課長","answer":"先ほどご回答申し上げたことに関連してくるのですが、導入する消防車両がちょっと物足りないということであれば、また西大井広場公園のほうで実施するということも視野に入れながら考えておるところです。","id":"exchange-035"},{"speaker":"塚本委員","kind":"意見","question":"積極的な理由なのか、あるいは西大井でやることに対する消極的な理由が何かあるのか。その辺をもう少しの説明を求めました。","respondent":"川部防災安全担当課長","answer":"こちらにつきましては、本年１月２９日に大々的にオープンをしまして、ここで自衛隊機の着陸訓練等もさせていただいたところです。それと、新しい防災拠点ができたということをこの周囲の皆様にご認識いただくためにも。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"確認","question":"町会長の皆さんは西大井に行っていますから、万が一間違えて、多分人によってはいつもどおりだろうと思って場所なんか見ないわけです。","respondent":"川部防災安全担当課長","answer":"皆様に配付させていただきましたご案内通知に、昨年と会場が変更となりますのでご注意くださいというようなただし書きを加えさせていただきました。","id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ぜひお願いします。せっかくつくった広場を、この公園を各町会の会長にも見てもらいたいと思うので、ぜひその辺もとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり防水訓練といったらもう西大井広場というふうに頭が固まってしまっているものですから、なのでそこら辺も工夫していただきたいなと。これは意見で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594236?Template=document&Id=4198#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":33363,"voices":133}}]);
